INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13381, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买的耐用品们都很好。", "corrected_sentence": "他买的耐用品都很好。", "error_description": "词尾错误：“们”只能加在指人的名词后，“耐用品”指物品，不能加“们”，应写作“耐用品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '721f3fbb-cfc5-4b10-8a1a-9a9c2a0e5c68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "同化", "is_correct": true, "explanation": "反义：“同化”指使事物变得相同或相似，与“异化”指变得不同相反。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”是地理事物，与异化的意思没有反义关系。"}, {"text": "卡车", "is_correct": false, "explanation": "无关：“卡车”是交通工具，与异化的意思没有反义关系。"}, {"text": "花瓶", "is_correct": false, "explanation": "无关：“花瓶”是器物，与异化的意思没有反义关系。"}], "correct_answer": "同化", "explanations": {"同化": "反义：“同化”指使事物变得相同或相似，与“异化”指变得不同相反。", "河流": "无关：“河流”是地理事物，与异化的意思没有反义关系。", "卡车": "无关：“卡车”是交通工具，与异化的意思没有反义关系。", "花瓶": "无关：“花瓶”是器物，与异化的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "同化", "is_correct": true, "explanation": "反义：“同化”指使事物变得相同或相似，与“异化”指变得不同相反。"}, {"text": "石头", "is_correct": false, "explanation": "无关：“石头”是物体，与异化的意思没有反义关系。"}, {"text": "钢琴", "is_correct": false, "explanation": "无关：“钢琴”是乐器，与异化的意思没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”是建筑部件，与异化的意思没有反义关系。"}], "correct_answer": "同化", "explanations": {"同化": "反义：“同化”指使事物变得相同或相似，与“异化”指变得不同相反。", "石头": "无关：“石头”是物体，与异化的意思没有反义关系。", "钢琴": "无关：“钢琴”是乐器，与异化的意思没有反义关系。", "窗户": "无关：“窗户”是建筑部件，与异化的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物在发展过程中逐渐变得与原来不同，或者失去原本的性质。", "primary_collocate": null, "pronunciation": "yì huà", "ipa": "i˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "这种潜在的技术异化，迫使我们必须重新审视图灵测试之后的智能评估体系：是否应建立“自主性-责任性”双轴评价框架，以衡量代理在自由决策与社会嵌入之间的平衡能力？", "target_word": "异化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "衣物从“耐用品”异化为“一次性消费品”，大量未被穿着或仅短时间使用的服装最终被填埋或焚烧，形成巨大的资源浪费。", "target_word": "异化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "过度加班会造成人的异化。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种异化现象在城市里很常见。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机让人与人之间出现了异化。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他担心孩子会发生异化，变得冷漠。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家在小说里写了人的异化。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作变成赚钱的工具，这就是异化。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了劳动的异化。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讨论了技术带来的异化。", "target_word": "异化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "异化现象", "label": "复合词"}, {"form": "異化", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物发展中逐渐偏离或失去原本性质的变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ff47f7-e50e-4937-9c6f-4d98586d83d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "异化", "is_correct": true, "explanation": "正确。“异化”指事物逐渐变得与原来不同，与“潜在的技术……迫使我们重新审视”的隐忧语境相符。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”形容无声，与“技术”带来隐忧、迫使人重新审视的语境不符。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“咖啡”是饮品，“技术咖啡”不能表示抽象的变化过程。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“窗帘”是家居用品，不能指抽象的技术变化，与“潜在的技术……”搭配不当。"}], "explanations": {"异化": "正确。“异化”指事物逐渐变得与原来不同，与“潜在的技术……迫使我们重新审视”的隐忧语境相符。", "寂静": "语义：“寂静”形容无声，与“技术”带来隐忧、迫使人重新审视的语境不符。", "咖啡": "搭配：“咖啡”是饮品，“技术咖啡”不能表示抽象的变化过程。", "窗帘": "搭配：“窗帘”是家居用品，不能指抽象的技术变化，与“潜在的技术……”搭配不当。"}, "sentence_index": 0, "correct_answer": "异化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次改革的异化使学校成绩大幅提升。", "explanation": "这里应该用〈成效〉。“异化”指事物变得与原来不同、失去原本性质，表示改革带来的好结果要用“成效”。"}, {"text": "移民要尽快异化当地的生活。", "explanation": "这里应该用〈融入〉。“异化”指事物变得与原来不同，不能表示使自己与当地相同；移民要尽快融入当地的生活。"}, {"text": "这个社区的风貌几十年来毫无变化，却已经异化了。", "explanation": "这里应该用〈保持〉。“异化”指变得与原来不同，几十年毫无变化说明没有异化，要用“保持”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "异化", "is_correct": true, "explanation": "正确。“异化”指人在社会中逐渐失去本性、变得与原来不同，是小说常写的主题。"}, {"text": "乘法", "is_correct": false, "explanation": "语义：“乘法”是数学运算，与小说里写人的抽象变化无关。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，与小说里写人的内在变化不相关。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：“海拔”指地面的高度，与写人的抽象变化不相关。"}], "explanations": {"异化": "正确。“异化”指人在社会中逐渐失去本性、变得与原来不同，是小说常写的主题。", "乘法": "语义：“乘法”是数学运算，与小说里写人的抽象变化无关。", "体重": "语义：“体重”指身体的重量，与小说里写人的内在变化不相关。", "海拔": "语义：“海拔”指地面的高度，与写人的抽象变化不相关。"}, "sentence_index": 6, "correct_answer": "异化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河经过治理，水质竟然异化得清澈见底。", "explanation": "这里应该用〈改善〉。“异化”指变得与原来不同，形容水质变好要用“改善”。"}, {"text": "这种异化的传染性很强。", "explanation": "这里应该用〈疾病〉。“异化”不表示传播或传染，说传染性要用“疾病”。"}, {"text": "他每天坚持跑步，身体异化得越来越健康。", "explanation": "这里应该用〈变〉。“异化”指失去原本性质的负面变化，不能形容身体变好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长期熬夜会造成人的很异化。", "corrected_sentence": "长期熬夜会造成人的异化。", "error_description": "这里“异化”是名词，作“造成”的宾语，前面不能加程度副词“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部电影写了人很异化。", "corrected_sentence": "这部电影写了人的异化。", "error_description": "“异化”在这里是名词，作“写了”的宾语，应说“人的异化”，不能用“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52471281-3756-4e87-a66a-c94079c46cb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
