INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13387, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使图像、声音、作用等变得比原来更大或更强。", "primary_collocate": null, "pronunciation": "fàng dà", "ipa": "fɑŋ˥˩ tɑ˥˩", "syllable_count": 2, "sentences": [{"text": "这种“即穿即弃”的文化不仅放大了生产端的环境负荷，也暴露出全球供应链在可持续性治理上的结构性缺陷。", "target_word": "放大", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这张照片太小了，请帮我放大一点。", "target_word": "放大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把声音放大一点，后面的人听不清。", "target_word": "放大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社交媒体放大了这件小事的影响。", "target_word": "放大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音响把他的歌声放大了好几倍。", "target_word": "放大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别放大别人的缺点，要多看优点。", "target_word": "放大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "显微镜能把细菌放大几百倍。", "target_word": "放大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师把这张电路图放大，逐一检查每个元件。", "target_word": "放大", "complexity_tier": "T3", "furigana": "gōng chéng shī bǎ zhè zhāng diàn lù tú fàng dà, zhú yī jiǎn chá měi gè yuán jiàn.", "sentence_source": "generated"}, {"text": "紧张会放大人心里的害怕。", "target_word": "放大", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生把片子放大后，找到了小问题。", "target_word": "放大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放大了", "label": "体标"}, {"form": "放大过", "label": "体标"}, {"form": "放大器", "label": "复合"}, {"form": "放大镜", "label": "复合"}], "register": "中性", "sense_fingerprint": "使图像、声音、作用变大变强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64941688-4f27-4463-91b9-e734e0578460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13387, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放大", "is_correct": true, "explanation": "放大：“不仅放大了生产端的环境负荷”表示加重负担，与“也暴露出缺陷”的递进语气一致。"}, {"text": "修复", "is_correct": false, "explanation": "搭配：“修复”的对象是损坏之物，“环境负荷”不能被修复。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉具体设施，与抽象的“环境负荷”不合。"}, {"text": "唤醒", "is_correct": false, "explanation": "语义：“唤醒”指使人或事物从睡眠中醒来，与“环境负荷”无关。"}], "explanations": {"放大": "放大：“不仅放大了生产端的环境负荷”表示加重负担，与“也暴露出缺陷”的递进语气一致。", "修复": "搭配：“修复”的对象是损坏之物，“环境负荷”不能被修复。", "拆除": "语义：“拆除”指拆掉具体设施，与抽象的“环境负荷”不合。", "唤醒": "语义：“唤醒”指使人或事物从睡眠中醒来，与“环境负荷”无关。"}, "sentence_index": 0, "correct_answer": "放大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校的学生人数放大了不少，今年要新建教室。", "explanation": "这里应该用〈增多〉。放大用于使图像、声音、作用等变得更大或更强，人数的增加应说“增多”。"}, {"text": "假期放大了三天，大家都很开心。", "explanation": "这里应该用〈延长〉。放大不表示时间的延续，应说“延长”。"}, {"text": "别担心，你放大心吧，事情会好的。", "explanation": "这里应该用〈放宽〉。放大用于使图像、声音、作用等变大或变强，描述心情应说“放宽心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13387, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放大", "is_correct": true, "explanation": "放大：显微镜使细菌看起来放大几百倍，表示倍数上的放大。"}, {"text": "缩小", "is_correct": false, "explanation": "语义：显微镜的作用是使物体变大，“缩小”与之相反。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：“切割几百倍”没有计量意义，“切割”不能接倍数。"}, {"text": "涂抹", "is_correct": false, "explanation": "搭配：“涂抹”不带倍数，“涂抹几百倍”不成立。"}], "explanations": {"放大": "放大：显微镜使细菌看起来放大几百倍，表示倍数上的放大。", "缩小": "语义：显微镜的作用是使物体变大，“缩小”与之相反。", "切割": "搭配：“切割几百倍”没有计量意义，“切割”不能接倍数。", "涂抹": "搭配：“涂抹”不带倍数，“涂抹几百倍”不成立。"}, "sentence_index": 6, "correct_answer": "放大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的体重放大了三公斤。", "explanation": "这里应该用〈增加〉。放大指使事物变大，体重是数量变化，应说“增加”。"}, {"text": "今天的气温放大了五度，热得受不了。", "explanation": "这里应该用〈升高〉。放大用于使图像、声音、作用等变得更大或更强，气温的上升应说“升高”。"}, {"text": "他的身高放大了不少，同学们都很惊讶。", "explanation": "这里应该用〈长高〉。放大不用于描述人的身高增长，应说“长高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张地图我们放大了过，看起来很清楚。", "corrected_sentence": "这张地图我们放大过，看起来很清楚。", "error_description": "表示经历的“放大过”中，“过”与“了”不能同用，“放大了过”是错误的，应为“放大过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生把这张片子放大了过，才找到骨折的位置。", "corrected_sentence": "医生把这张片子放大过，才找到骨折的位置。", "error_description": "“了”与“过”都表示动作的体，不能同用于“放大”。“放大了过”是错误的，应为“放大过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13388, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
