INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13389, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指原本隐藏的事物、问题或真相被显现出来。", "primary_collocate": null, "pronunciation": "bào lù chū", "ipa": "pau̯˥˩ lu˥˩ ʈʂʰu˥", "syllable_count": 3, "sentences": [{"text": "这种“即穿即弃”的文化不仅放大了生产端的环境负荷，也暴露出全球供应链在可持续性治理上的结构性缺陷。", "target_word": "暴露出", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这次检查暴露出管理上的很多问题。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故暴露出工厂安全制度不完善。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛暴露出球队防守的弱点。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查暴露出公司一直在隐瞒真相。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情暴露出医院人手不足的问题。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试暴露出我基础知识不扎实。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据暴露出这个城市交通压力很大。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次失败暴露出计划本身有漏洞。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "测试暴露出软件存在安全问题。", "target_word": "暴露出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暴露", "label": "基本形式"}, {"form": "暴露出来", "label": "方向补语形式"}, {"form": "暴露出了", "label": "体标"}], "register": "书面", "sense_fingerprint": "事件或检查使隐藏的问题、缺点、真相显现出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64941688-4f27-4463-91b9-e734e0578460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13389, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "暴露出", "is_correct": true, "explanation": "正确。“暴露出”指原本隐藏的缺陷被显露出来，与“放大”和“缺陷”的语境相符。"}, {"text": "生产出", "is_correct": false, "explanation": "搭配：“生产出”搭配的是产品，不能说生产出“缺陷”。"}, {"text": "种出", "is_correct": false, "explanation": "语义：“种出”指种植得到农作物，“缺陷”不能被种出来，句意不通。"}, {"text": "造出", "is_correct": false, "explanation": "语义：“造出”指制造出实物，“缺陷”不是被造出来的，句意不通。"}], "explanations": {"暴露出": "正确。“暴露出”指原本隐藏的缺陷被显露出来，与“放大”和“缺陷”的语境相符。", "生产出": "搭配：“生产出”搭配的是产品，不能说生产出“缺陷”。", "种出": "语义：“种出”指种植得到农作物，“缺陷”不能被种出来，句意不通。", "造出": "语义：“造出”指制造出实物，“缺陷”不是被造出来的，句意不通。"}, "sentence_index": 0, "correct_answer": "暴露出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次改革暴露出了公司的快速发展。", "explanation": "这里应该用〈显示出〉。暴露出指原本隐藏的问题或真相被显露，公司的快速发展是公开的成绩，要说显示出。"}, {"text": "我的书包暴露出了一个苹果。", "explanation": "这里应该用〈装〉。暴露出指原本隐藏的问题被显露，书包里装东西应说「装」。"}, {"text": "他的回答暴露出他很诚实。", "explanation": "这里应该用〈表明〉。暴露出多指隐藏的缺陷或真相，表明诚实这类好品质要用“表明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13389, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暴露出", "is_correct": true, "explanation": "正确。“考试暴露出我基础知识不扎实”，“暴露出”指隐藏的问题被显示出来，语境相合。"}, {"text": "泄露", "is_correct": false, "explanation": "搭配：“泄露”多搭配秘密、信息，不能说考试泄露“基础知识不扎实”这种状况。"}, {"text": "倒出", "is_correct": false, "explanation": "语义：“倒出”指把容器里的东西倒出去，与考试的结果无关，句意不通。"}, {"text": "搬出", "is_correct": false, "explanation": "语义：“搬出”指搬离某处，与“基础知识不扎实”的语境不搭，句意不通。"}], "explanations": {"暴露出": "正确。“考试暴露出我基础知识不扎实”，“暴露出”指隐藏的问题被显示出来，语境相合。", "泄露": "搭配：“泄露”多搭配秘密、信息，不能说考试泄露“基础知识不扎实”这种状况。", "倒出": "语义：“倒出”指把容器里的东西倒出去，与考试的结果无关，句意不通。", "搬出": "语义：“搬出”指搬离某处，与“基础知识不扎实”的语境不搭，句意不通。"}, "sentence_index": 6, "correct_answer": "暴露出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在决赛中暴露出了冠军。", "explanation": "这里应该用〈获得〉。暴露出指隐藏的问题被显露，取得冠军要说获得。"}, {"text": "工厂暴露出一批新产品。", "explanation": "这里应该用〈制造〉。暴露出指隐藏的东西被显露，生产新产品要说制造出。"}, {"text": "厨师暴露出一道好菜。", "explanation": "这里应该用〈做出〉。暴露出指原本隐藏的问题或真相被显露，做好一道菜要说做出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次检查暴露了出很多问题。", "corrected_sentence": "这次检查暴露出了很多问题。", "error_description": "错误：“暴露了出”；正确：“暴露出了”。“暴露出”是“暴露”加趋向补语“出”的固定结构，“了”应放在“出”之后，写成“暴露了出”语序不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个漏洞终于暴露来出了。", "corrected_sentence": "这个漏洞终于暴露出来了。", "error_description": "错误：“暴露来出了”；正确：“暴露出来了”。趋向补语“出来”应整体紧跟动词，“来出”颠倒了顺序，不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13390, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "完美", "is_correct": true, "explanation": "完美与“缺陷”构成反义：完美指没有任何欠缺，正与“欠缺或不够完美”相对。"}, {"text": "复杂", "is_correct": false, "explanation": "与“缺陷”无反义关系；“复杂”指事物头绪多、难以理解。"}, {"text": "遥远", "is_correct": false, "explanation": "与“缺陷”无反义关系；“遥远”指距离很远，与缺陷的含义无关。"}, {"text": "清晰", "is_correct": false, "explanation": "与“缺陷”无反义关系；“清晰”指明白、分明，不是缺陷的对立面。"}], "correct_answer": "完美", "explanations": {"完美": "完美与“缺陷”构成反义：完美指没有任何欠缺，正与“欠缺或不够完美”相对。", "复杂": "与“缺陷”无反义关系；“复杂”指事物头绪多、难以理解。", "遥远": "与“缺陷”无反义关系；“遥远”指距离很远，与缺陷的含义无关。", "清晰": "与“缺陷”无反义关系；“清晰”指明白、分明，不是缺陷的对立面。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13390, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "完美", "is_correct": true, "explanation": "完美与“缺陷”构成反义：完美指没有任何欠缺，正与“欠缺或不够完美”相对。"}, {"text": "陌生", "is_correct": false, "explanation": "与“缺陷”无反义关系；“陌生”指不熟悉，与缺陷的含义无关。"}, {"text": "繁忙", "is_correct": false, "explanation": "与“缺陷”无反义关系；“繁忙”指事务多、忙碌，不是缺陷的对立面。"}, {"text": "嘈杂", "is_correct": false, "explanation": "与“缺陷”无反义关系；“嘈杂”指声音杂乱，与缺陷的含义无关。"}], "correct_answer": "完美", "explanations": {"完美": "完美与“缺陷”构成反义：完美指没有任何欠缺，正与“欠缺或不够完美”相对。", "陌生": "与“缺陷”无反义关系；“陌生”指不熟悉，与缺陷的含义无关。", "繁忙": "与“缺陷”无反义关系；“繁忙”指事务多、忙碌，不是缺陷的对立面。", "嘈杂": "与“缺陷”无反义关系；“嘈杂”指声音杂乱，与缺陷的含义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13390, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "欠缺或不够完美的地方。", "primary_collocate": null, "pronunciation": "quē xiàn", "ipa": "tɕʰɥe˥ ɕi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这种“即穿即弃”的文化不仅放大了生产端的环境负荷，也暴露出全球供应链在可持续性治理上的结构性缺陷。", "target_word": "缺陷", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个制度有一个很大的缺陷。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的性格缺陷让同事不愿合作。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说孩子有先天缺陷。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套方案的缺陷是成本太高。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有缺陷，我们要接受自己。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个理论最大的缺陷是缺少证据。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发现产品缺陷后，公司马上停止了销售。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕别人指出论文的缺陷。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律的缺陷给坏人留下了机会。", "target_word": "缺陷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个缺陷", "label": "量词"}, {"form": "先天缺陷", "label": "复合"}, {"form": "性格缺陷", "label": "复合"}], "register": "书面", "sense_fingerprint": "制度、方案、性格、理论等抽象事物欠缺、不完美之处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64941688-4f27-4463-91b9-e734e0578460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13390, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "缺陷", "is_correct": true, "explanation": "正确答案：缺陷（quē xiàn），指欠缺或不够完美的地方。"}, {"text": "切线", "is_correct": false, "explanation": "qiē（第一声）与 quē（第一声）的介音不同（i 与 u），意思是几何学中与曲线相切的直线。"}, {"text": "区县", "is_correct": false, "explanation": "qū（第一声）与 quē（第一声）的韵母不同，意思是行政区划中的区和县。"}, {"text": "全线", "is_correct": false, "explanation": "quán 与 quē 的韵母与声调都不同，意思是整个战线或线路的全部。"}], "explanations": {"缺陷": "正确答案：缺陷（quē xiàn），指欠缺或不够完美的地方。", "切线": "qiē（第一声）与 quē（第一声）的介音不同（i 与 u），意思是几何学中与曲线相切的直线。", "区县": "qū（第一声）与 quē（第一声）的韵母不同，意思是行政区划中的区和县。", "全线": "quán 与 quē 的韵母与声调都不同，意思是整个战线或线路的全部。"}, "sentence_index": null, "correct_answer": "缺陷"}, "level_3": {"options": [{"text": "优势", "is_correct": false, "explanation": "语义：“暴露出”的对象应是问题，“优势”是好处，与句意相反。"}, {"text": "缺陷", "is_correct": true, "explanation": "正确：“结构性”与“暴露出”指向治理上的不足，只有“缺陷”符合。"}, {"text": "效率", "is_correct": false, "explanation": "搭配：“结构性”多修饰问题、矛盾、缺陷，不说“结构性效率”。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”是取得的成果，不能被“暴露出”，与句意不符。"}], "explanations": {"优势": "语义：“暴露出”的对象应是问题，“优势”是好处，与句意相反。", "缺陷": "正确：“结构性”与“暴露出”指向治理上的不足，只有“缺陷”符合。", "效率": "搭配：“结构性”多修饰问题、矛盾、缺陷，不说“结构性效率”。", "成绩": "语义：“成绩”是取得的成果，不能被“暴露出”，与句意不符。"}, "sentence_index": 0, "correct_answer": "缺陷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天着凉了，今天胃有点缺陷。", "explanation": "这里应该用〈毛病〉。缺陷指事物本身欠缺、不完美的地方，不能指一时的身体不适。"}, {"text": "他在考试中犯了一个缺陷。", "explanation": "这里应该用〈错误〉。“犯”搭配“错误”，缺陷指性质或不足，不能说“犯缺陷”。"}, {"text": "这次比赛他的缺陷只出现了一次，导致我们丢了球。", "explanation": "这里应该用〈失误〉。缺陷指长期存在的不足，不能用来指比赛中一次偶然的失误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13390, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "缺陷", "is_correct": true, "explanation": "正确答案：缺陷（quē xiàn），指欠缺或不够完美的地方。"}, {"text": "全县", "is_correct": false, "explanation": "quán 与 quē 的韵母与声调都不同，意思是整个县。"}, {"text": "缺项", "is_correct": false, "explanation": "xiàng 与 xiàn 的韵母不同（ang 与 an），意思是缺少的项目。"}, {"text": "缺件", "is_correct": false, "explanation": "jiàn 与 xiàn 的声母不同（j 与 x），意思是缺少的零件。"}], "explanations": {"缺陷": "正确答案：缺陷（quē xiàn），指欠缺或不够完美的地方。", "全县": "quán 与 quē 的韵母与声调都不同，意思是整个县。", "缺项": "xiàng 与 xiàn 的韵母不同（ang 与 an），意思是缺少的项目。", "缺件": "jiàn 与 xiàn 的声母不同（j 与 x），意思是缺少的零件。"}, "sentence_index": null, "correct_answer": "缺陷"}, "level_3": {"options": [{"text": "优点", "is_correct": false, "explanation": "语义：“优点”是好处，与后面“缺少证据”这一缺憾相矛盾。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“理论”一般不说“最大的数量”，此处不能作评价的对象。"}, {"text": "缺陷", "is_correct": true, "explanation": "正确：“最大的……是缺少证据”说明的是理论上的不足，只有“缺陷”符合。"}, {"text": "成果", "is_correct": false, "explanation": "语义：“成果”指取得的成绩，不能说“最大的成果是缺少证据”。"}], "explanations": {"优点": "语义：“优点”是好处，与后面“缺少证据”这一缺憾相矛盾。", "数量": "搭配：“理论”一般不说“最大的数量”，此处不能作评价的对象。", "缺陷": "正确：“最大的……是缺少证据”说明的是理论上的不足，只有“缺陷”符合。", "成果": "语义：“成果”指取得的成绩，不能说“最大的成果是缺少证据”。"}, "sentence_index": 6, "correct_answer": "缺陷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛中取得了一个很大的缺陷。", "explanation": "这里应该用〈成绩〉。“取得”搭配“成绩、胜利”，缺陷是不足之处，不能被取得。"}, {"text": "她因为一时缺陷，忘记了开会的时间。", "explanation": "这里应该用〈疏忽〉。缺陷指长期存在的不足，不能用来指一时的疏忽。"}, {"text": "我们应该发挥法律的缺陷，保护弱者。", "explanation": "这里应该用〈作用〉。“发挥”搭配“作用、能力”，缺陷不能被发挥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份计划有一根明显的缺陷。", "corrected_sentence": "这份计划有一个明显的缺陷。", "error_description": "“缺陷”前应用量词“个”，“根”多用于细长的东西，不能修饰“缺陷”。正确说法是“一个明显的缺陷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器犯了一个缺陷，工人已经修好了。", "corrected_sentence": "这台机器有一个缺陷，工人已经修好了。", "error_description": "“犯”搭配的是“错误”等行为，不能说“犯缺陷”；表示存在不足应说“有一个缺陷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
