INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13391, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "按等级或环节一级接一级地进行。", "primary_collocate": null, "pronunciation": "céng céng", "ipa": "tsʰɤŋ˧˥ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "复杂的跨国供应链将生产环节层层外包，导致环境责任模糊，监管链条断裂。", "target_word": "层层", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "文件要层层检查，不能马虎。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱经过层层审批才发下来。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消息层层传达，最后到了每个员工。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司层层把关，产品很少出问题。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察层层追问，他终于说出了真话。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "申请要层层上报，所以很慢。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "责任层层落实到每个人身上。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把任务层层分给各个小组。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题被层层上报，最后到了市长那里。", "target_word": "层层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "层", "label": "单字"}, {"form": "層層", "label": "繁体"}, {"form": "层层叠叠", "label": "复合"}], "register": "书面", "sense_fingerprint": "按等级或环节一级接一级地进行，如层层把关、层层审批", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64941688-4f27-4463-91b9-e734e0578460') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13391, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“层层外包”的逐级推进不符。"}, {"text": "层层", "is_correct": true, "explanation": "正确：“层层外包”指生产环节一级一级外包，导致责任模糊，只有“层层”符合。"}, {"text": "轻轻", "is_correct": false, "explanation": "搭配：“轻轻”描写动作的方式，不能修饰“外包”这种业务安排。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与长期的外包策略不符。"}], "explanations": {"偶尔": "语义：“偶尔”表示不常发生，与“层层外包”的逐级推进不符。", "层层": "正确：“层层外包”指生产环节一级一级外包，导致责任模糊，只有“层层”符合。", "轻轻": "搭配：“轻轻”描写动作的方式，不能修饰“外包”这种业务安排。", "忽然": "语义：“忽然”表示突然发生，与长期的外包策略不符。"}, "sentence_index": 0, "correct_answer": "层层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他层层地喜欢这个城市。", "explanation": "这里应该用〈逐渐〉。层层指按层次一级一级进行，不能修饰“喜欢”这类心理状态。"}, {"text": "我层层吃完了这碗面。", "explanation": "这里应该用〈一口一口〉。层层指一层层推进，不能用来描述吃完一碗面的动作。"}, {"text": "老师层层地在办公室睡觉。", "explanation": "这里应该用〈一直〉。“层层”表示层次推进，不能表示持续不断的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上完成，与“所以很慢”的结果相矛盾。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”表示不认真、不拘形式，随便上报不会导致流程很慢，与“所以很慢”不符。"}, {"text": "层层", "is_correct": true, "explanation": "正确：“层层上报”指逐级上报，流程多，才导致申请很慢，只有“层层”符合。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带做某事，与逐级上报的正式流程不符。"}], "explanations": {"立刻": "语义：“立刻”表示马上完成，与“所以很慢”的结果相矛盾。", "随便": "语义：“随便”表示不认真、不拘形式，随便上报不会导致流程很慢，与“所以很慢”不符。", "层层": "正确：“层层上报”指逐级上报，流程多，才导致申请很慢，只有“层层”符合。", "顺便": "语义：“顺便”表示附带做某事，与逐级上报的正式流程不符。"}, "sentence_index": 6, "correct_answer": "层层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他层层地遇见了老朋友。", "explanation": "这里应该用〈偶然〉。“遇见”是一次性的事，层层不能修饰它，应说“偶然遇见”。"}, {"text": "小猫层层地叫了一下。", "explanation": "这里应该用〈一声〉。层层指一层层推进或连续堆叠，不能修饰一次性的叫声，应说“叫了一声”。"}, {"text": "他的车层层地开走了。", "explanation": "这里应该用〈立刻〉。“开走”是一次性的动作，层层不能修饰它，应说“立刻开走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个通知要层传达到基层。", "corrected_sentence": "这个通知要层层传达到基层。", "error_description": "副词“层层”是重叠形式，不能只用单个“层”，应说“层层传达”，不能说“层传达”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13391, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告要层上报。", "corrected_sentence": "这份报告要层层上报。", "error_description": "副词“层层”是重叠形式，表示逐级进行，不能只用单个“层”。应说“层层上报”，不能说“层上报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bbfc3c-86ef-48f5-a41f-94d52a2daf0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
