INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13393, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "（物体）断开、裂开；也比喻联系或过程中断。", "primary_collocate": null, "pronunciation": "duàn liè", "ipa": "twan˥˩ ljɛ˥˩", "syllable_count": 2, "sentences": [{"text": "复杂的跨国供应链将生产环节层层外包，导致环境责任模糊，监管链条断裂。", "target_word": "断裂", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "两家公司的合作关系突然断裂了。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让这个村子的传统文化断裂了。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资金链断裂，工厂只好停产。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们多年的友情因为一次误会而断裂。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地层断裂后，河流改变了方向。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家庭关系断裂，让孩子很难过。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说历史不能断裂，要一代代传下去。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "供应链断裂了，商店里没有货卖。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的联系断裂了很多年。", "target_word": "断裂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "断裂了", "label": "体标"}, {"form": "断裂过", "label": "体标"}, {"form": "断裂带", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体断开，或联系、链条、过程中断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9585d0-18df-4185-ab2e-1482e7a5a6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13393, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断裂", "is_correct": true, "explanation": "断裂指链条或联系被切断，与“责任模糊”的因果关系相符。"}, {"text": "加固", "is_correct": false, "explanation": "语义：“加固”是使更牢固，与“责任模糊”的因果相反，句子读不通。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”只用于种子或植物，监管链条不能发芽。"}, {"text": "歌唱", "is_correct": false, "explanation": "搭配：“歌唱”只用于人或鸟，不能用于监管链条。"}], "explanations": {"断裂": "断裂指链条或联系被切断，与“责任模糊”的因果关系相符。", "加固": "语义：“加固”是使更牢固，与“责任模糊”的因果相反，句子读不通。", "发芽": "搭配：“发芽”只用于种子或植物，监管链条不能发芽。", "歌唱": "搭配：“歌唱”只用于人或鸟，不能用于监管链条。"}, "sentence_index": 0, "correct_answer": "断裂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火堆因为雨而断裂了。", "explanation": "这里应该用〈熄灭〉。火焰停止燃烧要说熄灭；断裂指断开，或链条、联系等中断。"}, {"text": "他的希望因为失败而断裂了。", "explanation": "这里应该用〈破灭〉。希望、梦想化为泡影要说破灭，断裂多用于链条、联系或物体断开。"}, {"text": "美梦因为一声巨响而断裂了。", "explanation": "这里应该用〈破碎〉。美梦被打断、消失要说破碎，断裂不能用来形容梦境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断裂", "is_correct": true, "explanation": "断裂指家庭关系断开，才会让孩子难过，符合句子的因果关系。"}, {"text": "和好", "is_correct": false, "explanation": "语义：“和好”指重新和睦，与“让孩子很难过”的结果相反。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”用于生物，家庭关系不能说生长。"}, {"text": "闪烁", "is_correct": false, "explanation": "搭配：“闪烁”形容光亮，家庭关系不能闪烁。"}], "explanations": {"断裂": "断裂指家庭关系断开，才会让孩子难过，符合句子的因果关系。", "和好": "语义：“和好”指重新和睦，与“让孩子很难过”的结果相反。", "生长": "搭配：“生长”用于生物，家庭关系不能说生长。", "闪烁": "搭配：“闪烁”形容光亮，家庭关系不能闪烁。"}, "sentence_index": 6, "correct_answer": "断裂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蜡烛放在火边，断裂了。", "explanation": "这里应该用〈融化〉。蜡烛受热变软流下是融化，断裂不能描述这种变化。"}, {"text": "盐放进热水里，断裂了。", "explanation": "这里应该用〈溶解〉。盐在水中化开属于溶解，断裂不表示物质化开。"}, {"text": "雾气慢慢断裂了。", "explanation": "这里应该用〈散开〉。雾气向四周扩散要说散开，断裂指断开或联系、过程中断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "金融危机一来，两家银行的合作很断裂了。", "corrected_sentence": "金融危机一来，两家银行的合作就断裂了。", "error_description": "“断裂”是动词，不能受程度副词“很”修饰，“很断裂了”不成立；应说“就断裂了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国的联系突然被断裂了，谁也没想到。", "corrected_sentence": "两国的联系突然断裂了，谁也没想到。", "error_description": "“断裂”是不及物动词，前面不能加“被”，应说“联系突然断裂了”；加“被”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '640522d3-69fd-414e-8838-db7823a8e9d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
