INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13397, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "距离较远的一端或一侧。", "primary_collocate": null, "pronunciation": "yuǎn duān", "ipa": "ɥɛn˨˩˦ twan˥", "syllable_count": 2, "sentences": [{"text": "品牌方往往将环保义务推诿给远端供应商，而后者在成本压力下更倾向于牺牲环境标准以维持利润。", "target_word": "远端", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "桥的远端有一家小茶馆。", "target_word": "远端", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "走廊的远端有一扇红色的门。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把绳子的远端交给站在对岸的人。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖的近端水很浅，远端水很深。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从站台的远端走到出口要五分钟。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球滚到了球场的远端，没有人去捡。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子的远端放着一盆花，我够不到。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在隧道的远端，向我们挥手。", "target_word": "远端", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管子的远端连着水箱，近端连着水龙头。", "target_word": "远端", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遠端", "label": "繁体"}], "register": "书面", "sense_fingerprint": "远端：名词，距离较远的一端或一侧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0102e0d2-b138-4a6a-b645-d2d4ac74cec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13397, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远端", "is_correct": true, "explanation": "远端：距离较远的一端，句中指远离品牌方的那一端供应商。"}, {"text": "慈善", "is_correct": false, "explanation": "语义：慈善机构不以利润为目的，与“维持利润”的语境冲突。"}, {"text": "公益", "is_correct": false, "explanation": "语义：公益活动不追求利润，与“在成本压力下维持利润”不合。"}, {"text": "志愿", "is_correct": false, "explanation": "搭配：供应商需要以营利为目的，“志愿供应商”不能成立。"}], "explanations": {"远端": "远端：距离较远的一端，句中指远离品牌方的那一端供应商。", "慈善": "语义：慈善机构不以利润为目的，与“维持利润”的语境冲突。", "公益": "语义：公益活动不追求利润，与“在成本压力下维持利润”不合。", "志愿": "搭配：供应商需要以营利为目的，“志愿供应商”不能成立。"}, "sentence_index": 0, "correct_answer": "远端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段漫长的等待终于有了远端。", "explanation": "这里应该用〈尽头〉。远端指物体或空间上距离较远的一端，不指时间上的结束。"}, {"text": "这部电影的远端让人难忘。", "explanation": "这里应该用〈结局〉。远端只用于空间，不能指故事或电影的结局。"}, {"text": "我们的合作还停在远端，没有进展。", "explanation": "这里应该用〈初期〉。远端指空间上的一端，不指事情发展的阶段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ae974a3-c60f-47e3-a2f9-5004efbf8909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13397, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远端", "is_correct": true, "explanation": "远端：距离较远的一端，句中指球场远离球员的那一端。"}, {"text": "天花板", "is_correct": false, "explanation": "语义：球不可能滚到天花板上，与“滚到了”的动作不合。"}, {"text": "上空", "is_correct": false, "explanation": "搭配：“滚到”不能和“上空”搭配，球只能滚在地面上。"}, {"text": "心情", "is_correct": false, "explanation": "语义：球是滚到场地上的某个位置，“心情”不是球能滚到的地方，句意不通。"}], "explanations": {"远端": "远端：距离较远的一端，句中指球场远离球员的那一端。", "天花板": "语义：球不可能滚到天花板上，与“滚到了”的动作不合。", "上空": "搭配：“滚到”不能和“上空”搭配，球只能滚在地面上。", "心情": "语义：球是滚到场地上的某个位置，“心情”不是球能滚到的地方，句意不通。"}, "sentence_index": 6, "correct_answer": "远端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场争论的远端让大家松了口气。", "explanation": "这里应该用〈结束〉。远端只指空间上距离较远的一端，不能指事情的终结。"}, {"text": "这场比赛的远端出现在最后五分钟。", "explanation": "这里应该用〈高潮〉。远端只用于空间，不能指比赛中最精彩的部分。"}, {"text": "我们的见面已经到了远端，很快就要结束了。", "explanation": "这里应该用〈尾声〉。远端只指空间上的一端，不指时间上的最后阶段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ae974a3-c60f-47e3-a2f9-5004efbf8909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "操场的远端的有一个篮球架。", "corrected_sentence": "操场的远端有一个篮球架。", "error_description": "多出了一个“的”：“操场的远端”已作主语，后面直接接动词“有”，“远端”后的“的”应删去，说“操场的远端有一个篮球架”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ae974a3-c60f-47e3-a2f9-5004efbf8909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小船停在湖的很远端。", "corrected_sentence": "小船停在湖的远端。", "error_description": "修饰语错误：“远端”是名词，不能被“很”修饰。应说“湖的远端”或“很远的一端”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ae974a3-c60f-47e3-a2f9-5004efbf8909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
