INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13401, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过某种方法解开或解决被封闭、加密、限制的问题或事物。", "primary_collocate": null, "pronunciation": "pò jiě", "ipa": "pʰwo˥˩ tɕje˨˩˦", "syllable_count": 2, "sentences": [{"text": "要破解这一困局，必须从系统层面重构时尚产业的生态逻辑。", "target_word": "破解", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "警察终于破解了这起案件。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家们正在想办法破解这个难题。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了三天时间破解这个谜题。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们怎样才能破解交通拥堵？", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家破解了这种病的秘密。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个谜语太难，没人能破解。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公司很难破解资金不足的难题。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看完所有线索，终于破解了谜团。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "破解这个难题需要很多人合作。", "target_word": "破解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "破解了", "label": "完成体"}, {"form": "破解过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "想办法解开或解决难题、谜团等被困住的问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '598c31df-7b1e-444b-ae49-80c36c027b68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13401, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "破解", "is_correct": true, "explanation": "“破解”与“困局”搭配，表示设法解开困境，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赞赏美好的事物，“困局”是需要摆脱的困境，二者语义冲突。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”的对象是食物或滋味，“困局”是抽象处境，不能被品尝，句意不通。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”针对值得高兴的事情，“困局”是需要摆脱的难题，句意不通。"}], "explanations": {"破解": "“破解”与“困局”搭配，表示设法解开困境，符合句意。", "欣赏": "语义：“欣赏”指赞赏美好的事物，“困局”是需要摆脱的困境，二者语义冲突。", "品尝": "搭配：“品尝”的对象是食物或滋味，“困局”是抽象处境，不能被品尝，句意不通。", "庆祝": "语义：“庆祝”针对值得高兴的事情，“困局”是需要摆脱的难题，句意不通。"}, "sentence_index": 0, "correct_answer": "破解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于破解了这块饼干。", "explanation": "这里应该用〈吃〉。“吃”用于食物；“破解”用于密码、谜题等需要想办法解开的事物，不能用于饼干。"}, {"text": "医生正在破解这只青蛙。", "explanation": "这里应该用〈解剖〉。“解剖”指切开身体进行研究，“破解”不能用于具体的生物体。"}, {"text": "他终于破解了这项纪录。", "explanation": "这里应该用〈打破〉。“打破”用于纪录、沉默、局面等，“破解”只用于封闭、加密或受限制的问题，不能用于纪录。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13401, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "破解", "is_correct": true, "explanation": "“破解”表示解开谜题，与“谜语太难，没人能”连用，句意通顺。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”需要以人或某种行为为对象，“谜语”不能被原谅。"}, {"text": "绣", "is_correct": false, "explanation": "搭配：“绣”的对象是图案、花纹，不能用于谜语。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指愉快地得到，与“太难”的语意矛盾。"}], "explanations": {"破解": "“破解”表示解开谜题，与“谜语太难，没人能”连用，句意通顺。", "原谅": "配价：“原谅”需要以人或某种行为为对象，“谜语”不能被原谅。", "绣": "搭配：“绣”的对象是图案、花纹，不能用于谜语。", "享受": "语义：“享受”指愉快地得到，与“太难”的语意矛盾。"}, "sentence_index": 6, "correct_answer": "破解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵终于破解了这首歌。", "explanation": "这里应该用〈唱〉。“唱”用于歌曲；“破解”用于密码、谜题等，不能用于歌曲。"}, {"text": "警察破解了歹徒的武装。", "explanation": "这里应该用〈解除〉。“解除”指去掉对方的武装，“破解”指解开谜题或密码，不能用于武装。"}, {"text": "他们终于破解了这杯茶。", "explanation": "这里应该用〈喝〉。“喝”用于饮品；“破解”用于密码、谜题等，不能用于茶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13401, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于破解了出这组密码。", "corrected_sentence": "他终于破解出了这组密码。", "error_description": "补语位置错误：结果补语“出”应紧跟动词“破解”，“了”放在“出”之后，“破解了出”应为“破解出了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13401, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "程序员曾经破解了过这份加密文件。", "corrected_sentence": "程序员曾经破解过这份加密文件。", "error_description": "体貌错误：“过”表示经历，不能与“了”同时用在同一个动词后。正确应为“破解过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
