INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13404, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个能查看和验证产品生产过程信息的在线系统", "primary_collocate": null, "pronunciation": "píng tái", "ipa": "pʰiŋ˧˥ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "扫一下盒子上的码，就能进入产品信息平台。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个平台上，你可以查到牛奶是怎么生产的。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司做了一个平台，让客人看到每一步生产过程。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我登录平台，看了这袋米的生产日期。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平台上记着这批鸡蛋从农场到商店的每一步。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在平台上输入编号，马上看到了产品的来源。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个平台由政府管理，信息都是真的。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈先用手机在平台上查了这块肉的来源。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂每天把生产的数据放到平台上。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平台上查不到这个编号，说明产品可能是假的。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "网络平台", "label": "复合"}], "register": "中性", "sense_fingerprint": "可查询产品生产信息的在线系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42af6dd8-76df-4128-9f4d-41a929127788') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平台", "is_correct": true, "explanation": "平台指可以查看产品信息的在线系统，这里说「进入产品信息」，符合语境。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种花的地方，不能用来查产品信息，「进入产品信息花园」说不通。"}, {"text": "盒子", "is_correct": false, "explanation": "语义：盒子是装东西的容器，扫码后进入的是在线系统，不是盒子。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是在线信息系统，「进入产品信息厨房」说不通。"}], "explanations": {"平台": "平台指可以查看产品信息的在线系统，这里说「进入产品信息」，符合语境。", "花园": "语义：花园是种花的地方，不能用来查产品信息，「进入产品信息花园」说不通。", "盒子": "语义：盒子是装东西的容器，扫码后进入的是在线系统，不是盒子。", "厨房": "语义：厨房是做饭的地方，不是在线信息系统，「进入产品信息厨房」说不通。"}, "sentence_index": 0, "correct_answer": "平台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我扫了盒子上的平台，看到了这袋米的生产日期。", "explanation": "这里应该用「码」。扫的是二维码，平台是可以登录的系统，不能用「扫」。"}, {"text": "这个平台很甜，大家都想尝一尝。", "explanation": "这里应该用「糖」或「蛋糕」。平台是查询信息的系统，没有味道；「甜」只能形容食物。"}, {"text": "我把平台折成纸飞机，飞到了超市。", "explanation": "这里应该用「纸」。平台是电子系统，不能折成纸飞机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平台", "is_correct": true, "explanation": "平台指在线的信息系统，由政府管理，信息可靠，符合句中的语境。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是用来插花的，不能由政府管理发布产品信息。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是给孩子玩的，不是信息系统，不能说「信息都是真的」。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：帽子是戴在头上的物品，不是信息系统，「由政府管理，信息都是真的」说不通。"}], "explanations": {"平台": "平台指在线的信息系统，由政府管理，信息可靠，符合句中的语境。", "花瓶": "语义：花瓶是用来插花的，不能由政府管理发布产品信息。", "玩具": "语义：玩具是给孩子玩的，不是信息系统，不能说「信息都是真的」。", "帽子": "语义：帽子是戴在头上的物品，不是信息系统，「由政府管理，信息都是真的」说不通。"}, "sentence_index": 6, "correct_answer": "平台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在平台上养了很多鸡。", "explanation": "这里应该用「农场」。农场是养鸡的地方，平台是查询系统，不能养鸡。"}, {"text": "我用平台给猫盖了一床被子。", "explanation": "这里应该用「毯子」。平台是查询系统，不能当被子盖。"}, {"text": "我们在平台里刷了牙，然后去睡觉了。", "explanation": "这里应该用「浴室」或「洗手间」。平台不是房间，不能用来刷牙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我平台上登录，查到了这批鸡蛋的来源。", "corrected_sentence": "我在平台上登录，查到了这批鸡蛋的来源。", "error_description": "错误：「我平台上登录」，正确：「我在平台上登录」。表示在某个地方做动作时，地点前要加介词「在」，缺了「在」语句不通，本地人不会这样说。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条平台可以查到很多产品的信息。", "corrected_sentence": "一个平台可以查到很多产品的信息。", "error_description": "错误：「一条平台」，正确：「一个平台」。平台应用量词「个」，「条」用于细长的东西，不能用来数平台。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13405, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13405, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13405, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指所有的单个个体，强调没有例外。", "primary_collocate": null, "pronunciation": "měi yí jiàn", "ipa": "mei̯˨˩˦ i˧˥ tɕjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "首先，推动供应链透明化，建立可追溯的生产信息平台，使每一件纺织品的水足迹与污染排放数据可查可验，是实现问责制的基础。", "target_word": "每一件", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "当每一件廉价T恤背后都映射出干涸的河流与受污的土壤，我们不得不重新审视时尚的真正成本。", "target_word": "每一件", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家店的每一件衣服都很便宜。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我们的每一件礼物都包得很漂亮。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师检查了桌上的每一件作品。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里每一件旧家具都有一个故事。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很爱惜自己的每一件玩具。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人要仔细检查每一件产品。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家时，每一件行李都要写上名字。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里的每一件文物都很珍贵。", "target_word": "每一件", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每一件：逐个指称，强调无例外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '598c31df-7b1e-444b-ae49-80c36c027b68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13405, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "每一件", "is_correct": true, "explanation": "正确答案，指逐个指称的每一个事物，强调没有例外。"}, {"text": "没一件", "is_correct": false, "explanation": "没 méi（第二声）与 每 měi（第三声）声调不同，「没一件」意思是「没有一件」。"}, {"text": "每一间", "is_correct": false, "explanation": "间 jiān（第一声）与 件 jiàn（第四声）声调不同，「每一间」指每个房间。"}, {"text": "每一届", "is_correct": false, "explanation": "届 jiè 与 件 jiàn 读音相近但韵母不同（ie 与 ian），「每一届」指每一次或每一期。"}], "explanations": {"每一件": "正确答案，指逐个指称的每一个事物，强调没有例外。", "没一件": "没 méi（第二声）与 每 měi（第三声）声调不同，「没一件」意思是「没有一件」。", "每一间": "间 jiān（第一声）与 件 jiàn（第四声）声调不同，「每一间」指每个房间。", "每一届": "届 jiè 与 件 jiàn 读音相近但韵母不同（ie 与 ian），「每一届」指每一次或每一期。"}, "sentence_index": null, "correct_answer": "每一件"}, "level_3": {"options": [{"text": "每一件", "is_correct": true, "explanation": "代词，逐个指称纺织品，强调没有例外，与后文“每一件纺织品”相符。"}, {"text": "每一位", "is_correct": false, "explanation": "搭配：“位”用于人，不能修饰“纺织品”。"}, {"text": "每一杯", "is_correct": false, "explanation": "搭配：“杯”用于液体或容器，纺织品不能用它计量。"}, {"text": "每一辈", "is_correct": false, "explanation": "语义：“辈”指世代或辈分，与逐件说明纺织品水足迹的句意不合。"}], "explanations": {"每一件": "代词，逐个指称纺织品，强调没有例外，与后文“每一件纺织品”相符。", "每一位": "搭配：“位”用于人，不能修饰“纺织品”。", "每一杯": "搭配：“杯”用于液体或容器，纺织品不能用它计量。", "每一辈": "语义：“辈”指世代或辈分，与逐件说明纺织品水足迹的句意不合。"}, "sentence_index": 0, "correct_answer": "每一件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给我们的每一只礼物都包得很漂亮。", "explanation": "这里应该用〈件〉。「只」用于动物或成对的物品，「礼物」要用「件」。"}, {"text": "每一件同学都来参加了聚会。", "explanation": "这里应该用〈个〉。「件」用于物品，指人要用「个」或「位」。"}, {"text": "这家农场的每一件牛都很健康。", "explanation": "这里应该用〈头〉。「头」用于牛、猪等牲畜；「件」用于物品，不能用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13405, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每一件", "is_correct": true, "explanation": "代词，逐个指称他的玩具，强调没有例外，与“爱惜”的语境相符。"}, {"text": "每一株", "is_correct": false, "explanation": "搭配：“株”用于植物，玩具不能用它计量。"}, {"text": "每一场", "is_correct": false, "explanation": "语义：“场”指比赛或活动，句子说的是爱惜玩具，不成立。"}, {"text": "每一座", "is_correct": false, "explanation": "搭配：“座”用于山、建筑等大型物体，不用于玩具。"}], "explanations": {"每一件": "代词，逐个指称他的玩具，强调没有例外，与“爱惜”的语境相符。", "每一株": "搭配：“株”用于植物，玩具不能用它计量。", "每一场": "语义：“场”指比赛或活动，句子说的是爱惜玩具，不成立。", "每一座": "搭配：“座”用于山、建筑等大型物体，不用于玩具。"}, "sentence_index": 6, "correct_answer": "每一件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "博物馆里的每一本展品都很珍贵。", "explanation": "这里应该用〈件〉。「本」用于书籍，展品要用「件」。"}, {"text": "博物馆里的每一台文物都很珍贵。", "explanation": "这里应该用〈件〉。「台」用于机器、仪器等；文物要用「件」。"}, {"text": "博物馆里的每一株古董都很珍贵。", "explanation": "这里应该用〈件〉。「株」用于植物，古董要用「件」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每一件衣服们都要仔细检查。", "corrected_sentence": "每一件衣服都要仔细检查。", "error_description": "错误在于“衣服”后多加了“们”。“们”只用于指人，衣服不能加“们”。应说“每一件衣服都要仔细检查”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每一件行李要都检查。", "corrected_sentence": "每一件行李都要检查。", "error_description": "语序错误：副词“都”应放在“要”之前，说成“要都检查”不通顺。应说“每一件行李都要检查”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
