INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13406, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指能够被查询或核实。", "primary_collocate": null, "pronunciation": "kě chá", "ipa": "kʰɤ ʈʂʰa", "syllable_count": 2, "sentences": [{"text": "首先，推动供应链透明化，建立可追溯的生产信息平台，使每一件纺织品的水足迹与污染排放数据可查可验，是实现问责制的基础。", "target_word": "可查", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这些数据在网上都可查。", "target_word": "可查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名字在记录里可查。", "target_word": "可查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每笔钱的去向都可查。", "target_word": "可查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的信息可查，你不用担心。", "target_word": "可查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的旧档案现在都可查。", "target_word": "可查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药品的生产日期可查。", "target_word": "可查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的来源可查，不是假的。", "target_word": "可查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的成绩明天就可查。", "target_word": "可查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的作者可查。", "target_word": "可查", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "可查：信息能被查询核实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '598c31df-7b1e-444b-ae49-80c36c027b68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可查", "is_correct": true, "explanation": "可查：能够被查询、核实，与“可验”并列，说明数据可以追溯核实。"}, {"text": "可疑", "is_correct": false, "explanation": "语义：“可疑”指令人怀疑，与“透明化”“可验”的意思相反。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”形容人或事物讨人喜欢，不能用来说数据能否核实。"}, {"text": "可观", "is_correct": false, "explanation": "搭配：“可观”多用于收入、数量，不能修饰数据的可核实性。"}], "explanations": {"可查": "可查：能够被查询、核实，与“可验”并列，说明数据可以追溯核实。", "可疑": "语义：“可疑”指令人怀疑，与“透明化”“可验”的意思相反。", "可爱": "语义：“可爱”形容人或事物讨人喜欢，不能用来说数据能否核实。", "可观": "搭配：“可观”多用于收入、数量，不能修饰数据的可核实性。"}, "sentence_index": 0, "correct_answer": "可查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜很可查。", "explanation": "这里应该用〈可口〉。可查指能被查询核实，形容食物好吃要用“可口”。"}, {"text": "他的进步很可查。", "explanation": "这里应该用〈明显〉。可查指能被查询核实，形容进步很容易看出来要用“明显”。"}, {"text": "这只小猫很可查。", "explanation": "这里应该用〈可爱〉。可查指能被查询核实，形容小猫讨人喜欢要用“可爱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可查", "is_correct": true, "explanation": "可查：能够被查询、核实，句子说的是药品的生产日期可以查到。"}, {"text": "可口", "is_correct": false, "explanation": "语义：“可口”形容食物好吃，药品的生产日期不能是“可口”的。"}, {"text": "可怜", "is_correct": false, "explanation": "语义：“可怜”形容人或处境令人同情，不能用来形容生产日期。"}, {"text": "可观", "is_correct": false, "explanation": "搭配：“可观”多用于数量、收入，不能修饰药品的生产日期。"}], "explanations": {"可查": "可查：能够被查询、核实，句子说的是药品的生产日期可以查到。", "可口": "语义：“可口”形容食物好吃，药品的生产日期不能是“可口”的。", "可怜": "语义：“可怜”形容人或处境令人同情，不能用来形容生产日期。", "可观": "搭配：“可观”多用于数量、收入，不能修饰药品的生产日期。"}, "sentence_index": 6, "correct_answer": "可查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画很可查。", "explanation": "这里应该用〈好看〉。可查指能被查询核实，形容画作的美观要用“好看”。"}, {"text": "他一个人在家很可查。", "explanation": "这里应该用〈寂寞〉。可查指能被查询核实，形容人的心情要用“寂寞”。"}, {"text": "这次旅行很可查。", "explanation": "这里应该用〈愉快〉。可查指能被查询核实，形容旅行的感受要用“愉快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份名单在网上没可查。", "corrected_sentence": "这份名单在网上可查。", "error_description": "“可查”是形容词，不能受“没”修饰。表示否定应说“不可查”或“查不到”，此处多加了“没”，正确写法是“这份名单在网上可查”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司的账目都被可查。", "corrected_sentence": "公司的账目都可查。", "error_description": "错误在于“被”：“可查”是表示性质的形容词，不能用“被”引出，“被”字句须接动词。删去“被”，应说“公司的账目都可查”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a046013-a3b1-49ea-8fcc-41657599c097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13408, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13408, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13408, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指对工作或职责进行追究的制度，确保权责分明。", "primary_collocate": null, "pronunciation": "wèn zé zhì", "ipa": "wən˥˩ tsɤ˧˥ ʈʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "首先，推动供应链透明化，建立可追溯的生产信息平台，使每一件纺织品的水足迹与污染排放数据可查可验，是实现问责制的基础。", "target_word": "问责制", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司建立了问责制，每个人都要对工作负责。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校实行问责制，出了问题要找负责的人。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了问责制，大家做事就更认真了。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的问责制很严格。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府需要完善问责制，让权力和责任一致。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问责制能让每个部门都清楚自己的责任。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要加强问责制，防止没人负责的情况。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有问责制，错误就没人承担。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，问责制不是为了处罚，而是为了改进。", "target_word": "问责制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "问责制度", "label": "复合"}], "register": "正式", "sense_fingerprint": "对工作职责追究责任的制度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e5a7ef-e0a6-4733-bdef-e9d65403888e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "问责制", "is_correct": true, "explanation": "正确：问责制指明确责任、追究责任的制度，“实现…的基础”指向它，与“透明化、可查可验”的语境一致。"}, {"text": "保密制", "is_correct": false, "explanation": "语义：“保密制”与句中的“透明化”“可查可验”要求相反，不能作透明的基础。"}, {"text": "黑箱", "is_correct": false, "explanation": "语义：“黑箱”指内情不公开，与句中的“透明化”直接矛盾。"}, {"text": "腐败", "is_correct": false, "explanation": "搭配：“实现”搭配的应是目标或成果，“腐败”是消极现象，不能说“实现腐败”。"}], "explanations": {"问责制": "正确：问责制指明确责任、追究责任的制度，“实现…的基础”指向它，与“透明化、可查可验”的语境一致。", "保密制": "语义：“保密制”与句中的“透明化”“可查可验”要求相反，不能作透明的基础。", "黑箱": "语义：“黑箱”指内情不公开，与句中的“透明化”直接矛盾。", "腐败": "搭配：“实现”搭配的应是目标或成果，“腐败”是消极现象，不能说“实现腐败”。"}, "sentence_index": 0, "correct_answer": "问责制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是个问责制很强的人，遇事总是主动承担。", "explanation": "这里应该用〈责任心〉。问责制是追究责任的制度，不能用来形容人的态度；形容人要说责任心强。"}, {"text": "我们每个月都有问责制，成绩好的人会得到表扬。", "explanation": "这里应该用〈考核制度〉。问责制是出错后追究责任，评定成绩要用考核制度；“表扬”与问责制不搭。"}, {"text": "这次事故的问责制是司机，他要负全部责任。", "explanation": "这里应该用〈责任人〉。问责制是追究责任的制度，不是指某个人；要负责的人叫责任人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "问责制", "is_correct": true, "explanation": "正确：问责制是明确责任的制度，能让各部门清楚自己的责任，句意通顺。"}, {"text": "潜规则", "is_correct": false, "explanation": "语义：“潜规则”指不公开的隐性规矩，无法让部门清楚自己的责任。"}, {"text": "混乱", "is_correct": false, "explanation": "语义：“混乱”与“清楚自己的责任”直接矛盾。"}, {"text": "失职", "is_correct": false, "explanation": "搭配：“能让…清楚”的主语应是制度或措施，“失职”指行为，不能作这一结构的主语。"}], "explanations": {"问责制": "正确：问责制是明确责任的制度，能让各部门清楚自己的责任，句意通顺。", "潜规则": "语义：“潜规则”指不公开的隐性规矩，无法让部门清楚自己的责任。", "混乱": "语义：“混乱”与“清楚自己的责任”直接矛盾。", "失职": "搭配：“能让…清楚”的主语应是制度或措施，“失职”指行为，不能作这一结构的主语。"}, "sentence_index": 6, "correct_answer": "问责制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警方终于抓获了问责制。", "explanation": "这里应该用〈责任人〉。“抓获”只用于人，问责制是制度，不能被抓获；应抓的是责任人。"}, {"text": "公司新来了一位问责制，专门负责检查工作。", "explanation": "这里应该用〈一套〉计量。量词“位”只用于人，问责制是制度，应说“一套”或“一项”问责制。"}, {"text": "他承担了全部问责制，所以必须辞职。", "explanation": "这里应该用〈责任〉。问责制是制度，不能被“承担”，应说“承担责任”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司建立了一只问责制。", "corrected_sentence": "我们公司建立了一项问责制。", "error_description": "量词错误：错误形式为“一只问责制”，正确形式为“一项问责制”。“只”用于动物或成对物品中的一个，问责制是制度，应用“项”或“套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们终于问责制建立起来了。", "corrected_sentence": "我们终于把问责制建立起来了。", "error_description": "把字句错误：错误形式为“我们终于问责制建立起来了”，正确形式为“我们终于把问责制建立起来了”。“建立起来”是把字句的动补结构，问责制作宾语，需要用“把”提到动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
