INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13409, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指设计或功能上能够节约用水的类型。", "primary_collocate": null, "pronunciation": "jié shuǐ xíng", "ipa": "tɕjɛ˧˥ ʂweɪ˨˩ ɕiŋ˧˥", "syllable_count": 3, "sentences": [{"text": "其次，推广节水型印染技术、闭环水循环系统与无水染色工艺，能在不牺牲效率的前提下显著降低单位产出的水资源消耗。", "target_word": "节水型", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们家换了节水型马桶。", "target_word": "节水型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市正在建设节水型社会。", "target_word": "节水型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "节水型洗衣机能省很多水。", "target_word": "节水型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校里的水龙头都是节水型。", "target_word": "节水型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新房子要用节水型的设备。", "target_word": "节水型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民们开始使用节水型灌溉方法。", "target_word": "节水型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买洗衣机时，我选了节水型。", "target_word": "节水型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "节水型产品上常常有绿色标志。", "target_word": "节水型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把工厂改成节水型。", "target_word": "节水型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "设计或功能上能节约用水的类型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b47580-90f5-4a9a-ab97-6f640ec498d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13409, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "节水型", "is_correct": true, "explanation": "正确。节水型指设计上能节约用水的类型，与句中“降低水资源消耗”一致。"}, {"text": "耗水型", "is_correct": false, "explanation": "语义：耗水型指耗费水量多，推广它会增加水资源消耗，与句意相反。"}, {"text": "防水型", "is_correct": false, "explanation": "语义：防水型强调防止水渗入，与句中为节约水资源的目标不符。"}, {"text": "耐旱型", "is_correct": false, "explanation": "搭配：“耐旱”多用于植物或作物，不说“耐旱型印染技术”。"}], "explanations": {"节水型": "正确。节水型指设计上能节约用水的类型，与句中“降低水资源消耗”一致。", "耗水型": "语义：耗水型指耗费水量多，推广它会增加水资源消耗，与句意相反。", "防水型": "语义：防水型强调防止水渗入，与句中为节约水资源的目标不符。", "耐旱型": "搭配：“耐旱”多用于植物或作物，不说“耐旱型印染技术”。"}, "sentence_index": 0, "correct_answer": "节水型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台节水型电风扇转起来几乎没有声音。", "explanation": "这里应该用〈静音型〉。节水型说的是节约用水，不说噪音，描述转动安静要用〈静音型〉。"}, {"text": "这个节水型背包下雨天也不会进水。", "explanation": "这里应该用〈防水型〉。节水型说的是节约用水，说防雨、不进水要用〈防水型〉。"}, {"text": "这款节水型台灯用的是无铅材料。", "explanation": "这里应该用〈环保型〉。节水型指节约用水，说材料无铅、不含有害物质要用〈环保型〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13409, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节水型", "is_correct": true, "explanation": "正确。节水型指能节约用水的类型，修饰灌溉方法，语义通顺。"}, {"text": "室内型", "is_correct": false, "explanation": "语义：室内型指适合在室内使用，与农民在田间的灌溉场景不符。"}, {"text": "无水型", "is_correct": false, "explanation": "语义：无水型意为不用水，与“灌溉”需要用水的目的相矛盾。"}, {"text": "密封型", "is_correct": false, "explanation": "搭配：“密封”多用于容器或部件，不修饰“灌溉方法”。"}], "explanations": {"节水型": "正确。节水型指能节约用水的类型，修饰灌溉方法，语义通顺。", "室内型": "语义：室内型指适合在室内使用，与农民在田间的灌溉场景不符。", "无水型": "语义：无水型意为不用水，与“灌溉”需要用水的目的相矛盾。", "密封型": "搭配：“密封”多用于容器或部件，不修饰“灌溉方法”。"}, "sentence_index": 6, "correct_answer": "节水型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台节水型笔记本很好带。", "explanation": "这里应该用〈轻便型〉。节水型强调省水，说携带方便要用〈轻便型〉。"}, {"text": "这台节水型相机拍照很稳。", "explanation": "这里应该用〈防震型〉。节水型不描述拍摄稳定，说机器不易晃动要用〈防震型〉。"}, {"text": "这台节水型冰箱会自动报警。", "explanation": "这里应该用〈智能型〉。节水型说的是省水，说有自动报警功能要用〈智能型〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13409, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款马桶很节水型。", "corrected_sentence": "这款马桶是节水型的。", "error_description": "错误形式：“很节水型”；正确形式：“是节水型的”。“节水型”表示类别，不能受程度副词“很”修饰，要用“是……的”说明属于这一类型。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13409, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司决定把老工厂改节水型。", "corrected_sentence": "公司决定把老工厂改成节水型。", "error_description": "错误形式：“改节水型”；正确形式：“改成节水型”。“把……改成……”需要补语“成”连接结果，缺少“成”结构不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
