INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13411, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "用染料使纤维或其他材料着色。", "primary_collocate": null, "pronunciation": "rǎn sè", "ipa": "ʐan˨˩˦ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "其次，推广节水型印染技术、闭环水循环系统与无水染色工艺，能在不牺牲效率的前提下显著降低单位产出的水资源消耗。", "target_word": "染色", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "染色是布料生产中很重要的一步。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的染色技术很先进。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "染色以后，白布变成了漂亮的蓝色。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的染色能让衣服的颜色保持很久。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "染色用的染料要符合环保标准。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传统染色常用植物做染料。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工厂学习布料染色。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "染色过程中会用掉很多水。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的染色不均匀，有深有浅。", "target_word": "染色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "染色剂", "label": "复合"}], "register": "中性", "sense_fingerprint": "用染料给纤维等材料上色的工序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e5a7ef-e0a6-4733-bdef-e9d65403888e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13411, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "染色", "is_correct": true, "explanation": "“无水染色工艺”指不用水的染色加工，与前后文的节水、循环语境吻合。"}, {"text": "冶金", "is_correct": false, "explanation": "语义：冶金指金属冶炼，与前文的印染技术、水循环系统不属于同一领域。"}, {"text": "染料", "is_correct": false, "explanation": "搭配：染料是材料，不能用“无水”修饰后接“工艺”组成“无水染料工艺”。"}, {"text": "染坊", "is_correct": false, "explanation": "语义：染坊指作坊场所，不是加工方法，无法与“工艺”组成并列的加工方式。"}], "explanations": {"染色": "“无水染色工艺”指不用水的染色加工，与前后文的节水、循环语境吻合。", "冶金": "语义：冶金指金属冶炼，与前文的印染技术、水循环系统不属于同一领域。", "染料": "搭配：染料是材料，不能用“无水”修饰后接“工艺”组成“无水染料工艺”。", "染坊": "语义：染坊指作坊场所，不是加工方法，无法与“工艺”组成并列的加工方式。"}, "sentence_index": 0, "correct_answer": "染色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他讲的故事染色很精彩。", "explanation": "这里应该用〈情节〉。染色指用染料给布料、纤维等材料着色，故事的内容要说“情节”。"}, {"text": "这首诗的染色很优美。", "explanation": "这里应该用〈语言〉。染色指用染料给材料着色，诗的文字之美要说“语言”。"}, {"text": "这种病毒会通过伤口染色人体。", "explanation": "这里应该用〈感染〉。病毒侵入人体致病要说“感染”；染色指用染料使材料着色，与此无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "染色", "is_correct": true, "explanation": "“传统染色常用植物做染料”指用植物染料给材料着色的传统方法，语义吻合。"}, {"text": "电镀", "is_correct": false, "explanation": "语义：电镀是利用电解在金属表面镀层的工艺，与用植物做染料无关。"}, {"text": "陶瓷", "is_correct": false, "explanation": "搭配：陶瓷是材料，“传统陶瓷常用植物做染料”搭配不当。"}, {"text": "冶炼", "is_correct": false, "explanation": "语义：冶炼指从矿石中提取金属，与植物染料的使用毫无关系。"}], "explanations": {"染色": "“传统染色常用植物做染料”指用植物染料给材料着色的传统方法，语义吻合。", "电镀": "语义：电镀是利用电解在金属表面镀层的工艺，与用植物做染料无关。", "陶瓷": "搭配：陶瓷是材料，“传统陶瓷常用植物做染料”搭配不当。", "冶炼": "语义：冶炼指从矿石中提取金属，与植物染料的使用毫无关系。"}, "sentence_index": 6, "correct_answer": "染色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的染色很动听。", "explanation": "这里应该用〈旋律〉。染色指用染料给材料着色，歌曲好听要说“旋律”。"}, {"text": "她每天早上在脸上染色。", "explanation": "这里应该用〈化妆〉。染色用于布料、纤维等材料着色，给脸部上妆要说“化妆”。"}, {"text": "这份报告的染色很清楚。", "explanation": "这里应该用〈表述〉。染色指用染料给材料着色，报告的清楚程度要说“表述”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们给布了染色。", "corrected_sentence": "我们给布染色。", "error_description": "“了”位置错误：“了”不能放在动词“染色”之前，说“给布了染色”不成立；这句陈述不需要“了”，应说“我们给布染色。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂地染色设备很先进。", "corrected_sentence": "这家工厂的染色设备很先进。", "error_description": "结构助词错误：错误形式为“工厂地染色设备”，正确形式为“工厂的染色设备”。“工厂”修饰名词“设备”，要用“的”；“地”用在动词前作状语，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
