INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13412, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "将原材料或半成品加工成产品的方法、技术或过程。", "primary_collocate": null, "pronunciation": "gōng yì", "ipa": "kʊŋ˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "其次，推广节水型印染技术、闭环水循环系统与无水染色工艺，能在不牺牲效率的前提下显著降低单位产出的水资源消耗。", "target_word": "工艺", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家工厂的陶瓷工艺很先进。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的印染工艺减少了用水量。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种茶叶的加工工艺有三十多个步骤。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师正在改进钢铁的生产工艺。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条生产线用的是最新的工艺。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酿酒的工艺不同，味道也不同。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种布料的染色工艺很环保。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂换了新工艺，成本下降了。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师傅按传统工艺烧制瓷器。", "target_word": "工艺", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "工艺品", "label": "复合"}, {"form": "工藝", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "把原料加工成产品的生产方法、技术和流程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e5a7ef-e0a6-4733-bdef-e9d65403888e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工艺", "is_correct": true, "explanation": "“无水染色工艺”指不用水的染色加工方法，与前后文的节水、循环语境吻合。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器与印染、节水的生产技术毫不相关，无法接在“无水染色”之后。"}, {"text": "食品", "is_correct": false, "explanation": "语义：食品不是印染领域的内容，与前文的印染技术、闭环水循环系统语境不符。"}, {"text": "人才", "is_correct": false, "explanation": "搭配：“染色”修饰的是加工方法类名词，不能修饰“人才”。"}], "explanations": {"工艺": "“无水染色工艺”指不用水的染色加工方法，与前后文的节水、循环语境吻合。", "乐器": "语义：乐器与印染、节水的生产技术毫不相关，无法接在“无水染色”之后。", "食品": "语义：食品不是印染领域的内容，与前文的印染技术、闭环水循环系统语境不符。", "人才": "搭配：“染色”修饰的是加工方法类名词，不能修饰“人才”。"}, "sentence_index": 0, "correct_answer": "工艺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种工艺有五十公斤重。", "explanation": "这里应该用〈材料〉。工艺指加工方法或过程，没有重量；有重量的是材料等实物。"}, {"text": "这种茶叶的加工有三十多只工艺。", "explanation": "这里应该用〈道〉。工艺作为加工步骤，量词用“道”或“种”；“只”多用于动物，不能用于工艺。"}, {"text": "加工这种茶叶要三天工艺。", "explanation": "这里应该用〈时间〉。工艺是加工方法，不能表示所需的时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工艺", "is_correct": true, "explanation": "“酿酒的工艺不同，味道也不同”指酿造方法不同导致味道不同，语义吻合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与酿造过程无关，“酿酒的价格不同”说不通，味道不由价格决定。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体貌特征，不能用来说酿酒的方式或条件。"}, {"text": "关系", "is_correct": false, "explanation": "语义：关系指事物之间的联系，不能作为酿酒的加工要素，与味道不同的因果不符。"}], "explanations": {"工艺": "“酿酒的工艺不同，味道也不同”指酿造方法不同导致味道不同，语义吻合。", "价格": "语义：价格与酿造过程无关，“酿酒的价格不同”说不通，味道不由价格决定。", "身高": "体貌：身高是人的体貌特征，不能用来说酿酒的方式或条件。", "关系": "语义：关系指事物之间的联系，不能作为酿酒的加工要素，与味道不同的因果不符。"}, "sentence_index": 6, "correct_answer": "工艺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂每天消耗很多工艺。", "explanation": "这里应该用〈原料〉。工艺是加工方法，不能被消耗；消耗的是原料。"}, {"text": "这间车间的工艺很大。", "explanation": "这里应该用〈空间〉。工艺指加工方法，不能说大小；形容车间的大小要用“空间”。"}, {"text": "这个工艺每天都要吃午饭。", "explanation": "这里应该用〈工人〉。工艺是加工方法，不会吃午饭；吃午饭的是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂把这种工艺改进。", "corrected_sentence": "这家工厂把这种工艺改进了。", "error_description": "了缺失：“把”字句中动词后面必须带“了”、补语等成分，不能只说“把这种工艺改进”，应说“把这种工艺改进了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家厂采用了一张新工艺。", "corrected_sentence": "这家厂采用了一种新工艺。", "error_description": "量词错误：错误形式为“一张新工艺”，正确形式为“一种新工艺”。“工艺”是加工方法，应用量词“种”；“张”用于平面物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
