INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13415, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "废弃的、陈旧的。", "primary_collocate": null, "pronunciation": "fèi jiù", "ipa": "feɪ˥˩ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "同时，发展生物可降解纤维、提升废旧纺织品回收再利用技术，亦是缓解资源压力的重要路径。", "target_word": "废旧", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他们把废旧电池送到回收站。", "target_word": "废旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "废旧衣服可以捐给需要的人。", "target_word": "废旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司专门回收废旧塑料。", "target_word": "废旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "废旧轮胎也可以做成新产品。", "target_word": "废旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校门口有废旧报纸的回收箱。", "target_word": "废旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把废旧金属送进工厂。", "target_word": "废旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用废旧布料做了一个小包。", "target_word": "废旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要乱扔废旧手机，要集中回收。", "target_word": "废旧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "废旧家具堆在院子里，占了很大地方。", "target_word": "废旧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "废旧物资", "label": "复合"}, {"form": "废旧物品", "label": "复合"}, {"form": "廢舊", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "已经废弃、陈旧不用的（多修饰物品）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7e5a7ef-e0a6-4733-bdef-e9d65403888e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13415, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废旧", "is_correct": true, "explanation": "废旧：废弃的旧东西，修饰“纺织品”，符合“回收再利用”的语境。"}, {"text": "全新", "is_correct": false, "explanation": "语义：全新纺织品无需回收，与“回收再利用”的语境矛盾。"}, {"text": "天然", "is_correct": false, "explanation": "语义：天然纤维做的纺织品并非废弃物，与“回收再利用”不合。"}, {"text": "优质", "is_correct": false, "explanation": "语义：优质纺织品不是需要回收再利用的废弃物，与句意不合。"}], "explanations": {"废旧": "废旧：废弃的旧东西，修饰“纺织品”，符合“回收再利用”的语境。", "全新": "语义：全新纺织品无需回收，与“回收再利用”的语境矛盾。", "天然": "语义：天然纤维做的纺织品并非废弃物，与“回收再利用”不合。", "优质": "语义：优质纺织品不是需要回收再利用的废弃物，与句意不合。"}, "sentence_index": 0, "correct_answer": "废旧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很废旧，早就该退休了。", "explanation": "这里应该用〈年迈〉。废旧只用于废弃或陈旧的物品，不能用来形容人。"}, {"text": "这双鞋刚买回来，很废旧。", "explanation": "这里应该用〈崭新〉。废旧指废弃或陈旧不用的东西，刚买的鞋应说崭新。"}, {"text": "这台机器已经很废旧了，但每天都在用。", "explanation": "这里应该用〈老旧〉。废旧指已废弃不用，与“每天都在用”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13415, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废旧", "is_correct": true, "explanation": "废旧：废弃的旧东西，修饰“金属”，符合“送进工厂”回收的语境。"}, {"text": "憨厚", "is_correct": false, "explanation": "体貌：“憨厚”形容人的外貌或性情，不能用来修饰金属。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：金属不能称作“温暖”，与“送进工厂”的语境不合。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：金属没有“甜美”的样貌或味道，与句意矛盾。"}], "explanations": {"废旧": "废旧：废弃的旧东西，修饰“金属”，符合“送进工厂”回收的语境。", "憨厚": "体貌：“憨厚”形容人的外貌或性情，不能用来修饰金属。", "温暖": "语义：金属不能称作“温暖”，与“送进工厂”的语境不合。", "甜美": "语义：金属没有“甜美”的样貌或味道，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "废旧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑刚买回来，还很废旧。", "explanation": "这里应该用〈崭新〉。废旧指废弃或陈旧不用的东西，刚买的电脑应说崭新。"}, {"text": "他这次考试考得很废旧，成绩很差。", "explanation": "这里应该用〈糟糕〉。废旧只用于废弃或陈旧的物品，不能用来形容考试的表现。"}, {"text": "这家店的新款手机很废旧，没人想买。", "explanation": "这里应该用〈先进〉。废旧指废弃或陈旧不用的东西，新款手机应说先进或新颖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13415, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些很废旧电池要集中处理。", "corrected_sentence": "这些废旧电池要集中处理。", "error_description": "错误形式：很废旧电池；正确形式：废旧电池。“很”是程度副词，不能直接修饰作定语的“废旧”，两者之间要去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13415, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子里的很废旧家具占了很大地方。", "corrected_sentence": "院子里的废旧家具占了很大地方。", "error_description": "错误形式：很废旧家具；正确形式：废旧家具。“废旧”是区别性的定语，不受程度副词“很”修饰，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '441452a0-d9b4-41ee-8edf-38af5f33103c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
