INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13416, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指对原有的技术或方法进行改进，使其更高效、更先进。", "primary_collocate": null, "pronunciation": "jì shù gé xīn", "ipa": "tɕi˥˩ ʂu˥˩ kɤ˧˥ ɕin˥", "syllable_count": 4, "sentences": [{"text": "然而，技术革新若无消费观念的同步转变，终将举步维艰。", "target_word": "技术革新", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这家工厂靠技术革新，生产快了很多。", "target_word": "技术革新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "技术革新让工人的工作更轻松。", "target_word": "技术革新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司每年都搞技术革新。", "target_word": "技术革新", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们的技术革新使成本降低了。", "target_word": "技术革新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项技术革新节约了一半的时间。", "target_word": "技术革新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厂长鼓励大家提出技术革新的想法。", "target_word": "技术革新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有技术革新，旧机器就会越来越慢。", "target_word": "技术革新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过技术革新，这台机器的效率更高了。", "target_word": "技术革新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农业也需要技术革新，才能多打粮食。", "target_word": "技术革新", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "技術革新", "label": "繁体"}], "register": "中性", "sense_fingerprint": "改进原有技术或方法，使之更高效、更先进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b47580-90f5-4a9a-ab97-6f640ec498d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13416, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人为改进技术或方法的活动，无法与“消费观念”同步转变"}, {"text": "技术革新", "is_correct": true, "explanation": "“技术革新”指改进原有技术或方法，与句中“同步转变”相呼应，语义通顺"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这句书面语的语体不协调"}, {"text": "讲座", "is_correct": false, "explanation": "语义：“讲座”是讲授活动，不能与消费观念同步转变，句子语义不通"}], "explanations": {"天气": "语义：“天气”不是人为改进技术或方法的活动，无法与“消费观念”同步转变", "技术革新": "“技术革新”指改进原有技术或方法，与句中“同步转变”相呼应，语义通顺", "玩意儿": "语域：“玩意儿”是口语说法，与这句书面语的语体不协调", "讲座": "语义：“讲座”是讲授活动，不能与消费观念同步转变，句子语义不通"}, "sentence_index": 0, "correct_answer": "技术革新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他经过技术革新，不再乱花钱了。", "explanation": "这里应该用〈改造〉。技术革新指改进技术或方法，改变人的想法和习惯要用〈改造〉"}, {"text": "这座老楼经过技术革新，外墙重新刷了漆。", "explanation": "这里应该用〈粉刷〉。技术革新指改进技术或方法，给墙面重新刷漆要用〈粉刷〉"}, {"text": "厂里完成了一台技术革新。", "explanation": "量词错误：技术革新应搭配〈项〉，〈台〉用于机器等实体器械。这里应该用〈项〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：厂长“鼓励”大家提出的应是改进工作的想法，“体重”与之无关，语义不通"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语化的闲话，与这句正式的工作语境不协调"}, {"text": "技术革新", "is_correct": true, "explanation": "“技术革新”指改进原有技术或方法，与“提出想法”的工作语境相符"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“想法”的内容应是可以提出的方案，不能说“心情”的想法"}], "explanations": {"体重": "语义：厂长“鼓励”大家提出的应是改进工作的想法，“体重”与之无关，语义不通", "八卦": "语域：“八卦”是口语化的闲话，与这句正式的工作语境不协调", "技术革新": "“技术革新”指改进原有技术或方法，与“提出想法”的工作语境相符", "心情": "搭配：“想法”的内容应是可以提出的方案，不能说“心情”的想法"}, "sentence_index": 6, "correct_answer": "技术革新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一个很厉害的技术革新。", "explanation": "这里把技术革新当作人来用，指人应说〈革新者〉或〈能工巧匠〉；技术革新只指改进技术或方法的活动"}, {"text": "他用技术革新的办法安慰了失恋的朋友。", "explanation": "这里把技术革新误当作一般的处理办法来用。安慰人应说〈劝慰〉；技术革新只指改进技术或方法"}, {"text": "他把这项技术革新装进了箱子里。", "explanation": "这里把抽象的技术革新当作实物来用。能装进箱子的应是〈图纸〉或〈样品〉，技术革新只指改进技术或方法的活动"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个车间靠一台技术革新，产量提高了不少。", "corrected_sentence": "这个车间靠一项技术革新，产量提高了不少。", "error_description": "量词错误：“技术革新”是改进技术或方法的活动，不是机器，不能用“台”，应搭配量词“项”，说“一项技术革新”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂对老机器技术革新，效率高了不少。", "corrected_sentence": "工厂对老机器进行技术革新，效率高了不少。", "error_description": "结构错误：“技术革新”是名词，不能直接作谓语。“对老机器……”后面需要动词，应说“对老机器进行技术革新”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
