INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13422, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13422, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "培养、教育，使生物或事物成长、发展。", "primary_collocate": null, "pronunciation": "péi yù", "ipa": "pʰeɪ˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "唯有通过教育与公共政策引导，培育“少而精”的理性消费文化，抵制过度消费的符号化冲动，方能在需求侧为资源减负创造空间。", "target_word": "培育", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农业专家成功培育了新的水稻品种。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校应该培育学生的创新精神。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学培育了许多优秀的科学家。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想培育更多的高新技术企业。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在大棚里培育蔬菜的新品种。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用爱心培育着每一个孩子。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司重视培育年轻的技术人才。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家培育出了一种抗旱的小麦。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的家庭环境有助于培育孩子的品格。", "target_word": "培育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "培育了", "label": "体标"}, {"form": "培育过", "label": "体标"}, {"form": "培育着", "label": "体标"}], "register": "书面语", "sense_fingerprint": "培养教育，使生物或事物（人才、品种、风气）成长发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc02ac77-f897-4891-b52f-1733019e3215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "培育", "is_correct": true, "explanation": "“唯有通过…引导”的语境要求用“培育”，表示使文化逐步形成，符合句意。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：句中说通过教育与政策“引导”，“摧毁”与此语义相反。"}, {"text": "驱散", "is_correct": false, "explanation": "搭配：“驱散”多用于阴霾、疑虑，不说驱散“文化”。"}, {"text": "消失", "is_correct": false, "explanation": "配价：“消失”是不及物动词，不能带“文化”作宾语。"}], "explanations": {"培育": "“唯有通过…引导”的语境要求用“培育”，表示使文化逐步形成，符合句意。", "摧毁": "语义：句中说通过教育与政策“引导”，“摧毁”与此语义相反。", "驱散": "搭配：“驱散”多用于阴霾、疑虑，不说驱散“文化”。", "消失": "配价：“消失”是不及物动词，不能带“文化”作宾语。"}, "sentence_index": 0, "correct_answer": "培育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都培育一杯热咖啡。", "explanation": "语义：“培育”只用于使生物或人才成长，此处误用为“冲泡、制作”的意思，咖啡不能这样培育。"}, {"text": "这家工厂培育了大量的螺丝钉。", "explanation": "语义：“培育”只用于使生物或人才成长，此处误用为“批量生产”的意思，把工业产品当作可以培育的对象。"}, {"text": "我们今天培育了一场大雨。", "explanation": "语义：“培育”只用于使生物或人才成长，此处误用为“人为促成、造出”的意思，天气不能这样培育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "培育", "is_correct": true, "explanation": "老师用爱心培养孩子，符合“培育”使人成长的语义，与句意吻合。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”指赶走，与“用爱心”的积极语境相反。"}, {"text": "消耗", "is_correct": false, "explanation": "搭配：“消耗”多指精力、资源，不用于“消耗孩子”。"}, {"text": "扑灭", "is_correct": false, "explanation": "搭配：“扑灭”多用于火、疫情，不能用于孩子。"}], "explanations": {"培育": "老师用爱心培养孩子，符合“培育”使人成长的语义，与句意吻合。", "驱赶": "语义：“驱赶”指赶走，与“用爱心”的积极语境相反。", "消耗": "搭配：“消耗”多指精力、资源，不用于“消耗孩子”。", "扑灭": "搭配：“扑灭”多用于火、疫情，不能用于孩子。"}, "sentence_index": 6, "correct_answer": "培育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在考场上培育了很高的分数。", "explanation": "语义：此处误用为“取得、获得”的意思，“培育”只用于使生物或人才成长，成绩不能这样培育。"}, {"text": "这家公司每月都培育大量的资金。", "explanation": "语义：此处误用为“积累、筹集”的意思，“培育”只用于使生物或人才成长，钱款不能这样培育。"}, {"text": "这座城市培育了一座新的大桥。", "explanation": "语义：此处误用为“建造、修建”的意思，“培育”只表示使生物或人才成长，不能用于建筑工程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "园艺师培育了出一种抗病的月季。", "corrected_sentence": "园艺师培育出了一种抗病的月季。", "error_description": "错误：“培育了出”。正确：“培育出了”。结果补语“出”应紧跟动词，“了”置于“出”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他花了五年时间，终于培育出着一种抗虫的玉米。", "corrected_sentence": "他花了五年时间，终于培育出了一种抗虫的玉米。", "error_description": "错误：“培育出着”。正确：“培育出了”。“培育出”表示动作完成，应用“了”，“着”表示持续状态，不能用于此处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
