INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13423, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容数量虽少，但质量很高。", "primary_collocate": null, "pronunciation": "shǎo ér jīng", "ipa": "ʂaʊ˨˩˦ aɚ˧˥ tɕiŋ˥˥", "syllable_count": 3, "sentences": [{"text": "唯有通过教育与公共政策引导，培育“少而精”的理性消费文化，抵制过度消费的符号化冲动，方能在需求侧为资源减负创造空间。", "target_word": "少而精", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家餐厅的菜单少而精，每道菜都很好吃。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所小学的师资少而精，每位老师都很有经验。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学习词语要少而精，不要贪多。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个书店的书少而精，本本都值得读。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的广告应该少而精，不能太啰嗦。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的产品少而精，每款都设计得很用心。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览的作品少而精，件件都有特点。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的课程少而精，学生学得很轻松。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买衣服只买少而精的，不乱花钱。", "target_word": "少而精", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "数量少但质量高，强调宁少勿滥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc02ac77-f897-4891-b52f-1733019e3215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13423, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "少而精", "is_correct": true, "explanation": "原句中的词，指数量少而质量高，与“培育理性消费”的要求一致。"}, {"text": "奢侈", "is_correct": false, "explanation": "语义：“奢侈”与“理性消费”相反，放在这里语义矛盾。"}, {"text": "铺张", "is_correct": false, "explanation": "语义：“铺张”指浪费排场，与“理性消费文化”的培育目标冲突。"}, {"text": "盲目", "is_correct": false, "explanation": "搭配：“盲目”可以修饰消费，但与“理性”并用自相矛盾，不能修饰“理性消费文化”。"}], "explanations": {"少而精": "原句中的词，指数量少而质量高，与“培育理性消费”的要求一致。", "奢侈": "语义：“奢侈”与“理性消费”相反，放在这里语义矛盾。", "铺张": "语义：“铺张”指浪费排场，与“理性消费文化”的培育目标冲突。", "盲目": "搭配：“盲目”可以修饰消费，但与“理性”并用自相矛盾，不能修饰“理性消费文化”。"}, "sentence_index": 0, "correct_answer": "少而精"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的年龄少而精，今年才二十岁。", "explanation": "这里把“少而精”误当成了“年轻”的意思，但它只用于形容数量少而质量高的事物，年龄是客观数字，没有“精”与否之分。"}, {"text": "这场比赛我们输了两局，真是少而精。", "explanation": "这里把“少”理解成“输得少”，但“少而精”的“精”要求质量高，输球属于负面结果，不能用来夸赞。"}, {"text": "这座城市的人口少而精，去年又增加了五十万。", "explanation": "这里误把“少而精”当成了只说数量少的“少”，用在人口这类总量上。“精”指质量高，人口并不存在这种评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "少而精", "is_correct": true, "explanation": "原句中的词，描述产品数量少而质量高，与“每款都设计得很用心”一致。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”与“每款都设计得很用心”矛盾。"}, {"text": "随意", "is_correct": false, "explanation": "语义：“随意”与“每款都设计得很用心”矛盾。"}, {"text": "低劣", "is_correct": false, "explanation": "语义：“低劣”与“每款都设计得很用心”矛盾。"}], "explanations": {"少而精": "原句中的词，描述产品数量少而质量高，与“每款都设计得很用心”一致。", "粗糙": "语义：“粗糙”与“每款都设计得很用心”矛盾。", "随意": "语义：“随意”与“每款都设计得很用心”矛盾。", "低劣": "语义：“低劣”与“每款都设计得很用心”矛盾。"}, "sentence_index": 6, "correct_answer": "少而精"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的感冒少而精，已经病了一周。", "explanation": "这里把“少而精”误当成了“病情轻”的意思，但它只说数量少而质量高，不能用来形容疾病。"}, {"text": "这次旅行我们走马观花，去了二十个城市，真是少而精。", "explanation": "这里误把“少而精”当成了“广泛、数量多”的意思，但它只表示数量少而质量高，不能用于走马观花式的旅行。"}, {"text": "这家公司的亏损少而精，去年一年亏了两亿。", "explanation": "这里把“少”理解成“亏得少”，但“精”指质量高，亏损两亿是负面结果，不能用“少而精”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家面包店的品种很少而精，每款都很好吃。", "corrected_sentence": "这家面包店的品种少而精，每款都很好吃。", "error_description": "错误：“很少而精”。正确：“少而精”。“少而精”是固定格式，中间不能插入程度副词“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司只做被少而精的产品，每款都设计得很用心。", "corrected_sentence": "这家公司只做少而精的产品，每款都设计得很用心。", "error_description": "错误：“被少而精”。正确：删去“被”，作“少而精的产品”。“少而精”是形容词，不能用“被”构成被动式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13424, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "支持", "is_correct": true, "explanation": "反义：“支持”与“抵制”相对，表示赞同、拥护。"}, {"text": "修建", "is_correct": false, "explanation": "修建是建造、修造，与“抵制”没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "研究是探求、考察，与“抵制”没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "整理是使有条理，与“抵制”没有反义关系。"}], "correct_answer": "支持", "explanations": {"支持": "反义：“支持”与“抵制”相对，表示赞同、拥护。", "修建": "修建是建造、修造，与“抵制”没有反义关系。", "研究": "研究是探求、考察，与“抵制”没有反义关系。", "整理": "整理是使有条理，与“抵制”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
