INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13424, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示拒绝接受或反对某种行为、商品、活动等。", "primary_collocate": null, "pronunciation": "dǐ zhì", "ipa": "ti˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "唯有通过教育与公共政策引导，培育“少而精”的理性消费文化，抵制过度消费的符号化冲动，方能在需求侧为资源减负创造空间。", "target_word": "抵制", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "很多人抵制这家公司的产品。", "target_word": "抵制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要抵制不良的网络游戏。", "target_word": "抵制", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消费者联合起来抵制涨价。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校号召学生抵制考试作弊。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直抵制着垃圾食品的诱惑。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民抵制过这种不文明的行为。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人坚决抵制虚假广告。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都抵制在公共场所吸烟的行为。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教孩子抵制坏习惯的影响。", "target_word": "抵制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抵制了", "label": "体标"}, {"form": "抵制着", "label": "体标"}, {"form": "抵制过", "label": "体标"}], "register": "中性", "sense_fingerprint": "拒绝并反对不良行为、商品或活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc02ac77-f897-4891-b52f-1733019e3215') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13424, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抵制", "is_correct": true, "explanation": "本词，读作 dǐ zhì，表示拒绝或反对某种行为、商品或活动。"}, {"text": "地质", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，意思是地球的构造与变化，即地质。"}, {"text": "体制", "is_correct": false, "explanation": "tǐ 与 dǐ 声母不同（t 与 d），意思是组织的结构或制度，即体制。"}, {"text": "地支", "is_correct": false, "explanation": "dì 与 dǐ 声调不同，zhī 与 zhì 声调也不同，意思是地支，即十二地支。"}], "explanations": {"抵制": "本词，读作 dǐ zhì，表示拒绝或反对某种行为、商品或活动。", "地质": "dì（第四声）与 dǐ（第三声）声调不同，意思是地球的构造与变化，即地质。", "体制": "tǐ 与 dǐ 声母不同（t 与 d），意思是组织的结构或制度，即体制。", "地支": "dì 与 dǐ 声调不同，zhī 与 zhì 声调也不同，意思是地支，即十二地支。"}, "sentence_index": null, "correct_answer": "抵制"}, "level_3": {"options": [{"text": "抵制", "is_correct": true, "explanation": "原句中的词，表示拒绝、反对过度消费的冲动，与前后的目的一致。"}, {"text": "放纵", "is_correct": false, "explanation": "语义：“放纵”与“培育理性消费”的目标相反。"}, {"text": "助长", "is_correct": false, "explanation": "语义：“助长”是促使不良倾向发展，与“方能……创造空间”的语义相矛盾。"}, {"text": "迎合", "is_correct": false, "explanation": "搭配：“迎合”的对象是他人的喜好或市场需求，不用于内在的符号化冲动。"}], "explanations": {"抵制": "原句中的词，表示拒绝、反对过度消费的冲动，与前后的目的一致。", "放纵": "语义：“放纵”与“培育理性消费”的目标相反。", "助长": "语义：“助长”是促使不良倾向发展，与“方能……创造空间”的语义相矛盾。", "迎合": "搭配：“迎合”的对象是他人的喜好或市场需求，不用于内在的符号化冲动。"}, "sentence_index": 0, "correct_answer": "抵制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题我们必须尽快抵制。", "explanation": "这里应该用〈应对〉。“抵制”用于拒绝不良行为或商品，问题要说“应对”。"}, {"text": "为了安全，我们要抵制火灾的发生。", "explanation": "这里应该用〈防止〉。“抵制”用于拒绝不良行为或商品，火灾这类事故应说“防止”。"}, {"text": "这份合同需要用房子来抵制贷款。", "explanation": "这里应该用〈抵押〉。“抵制”表示拒绝、反对，不表示用财物作担保。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13424, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "抵制", "is_correct": true, "explanation": "本词，读作 dǐ zhì，表示拒绝或反对某种行为、商品或活动。"}, {"text": "地址", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，zhǐ 与 zhì 声调也不同，意思是地址。"}, {"text": "体质", "is_correct": false, "explanation": "tǐ 与 dǐ 声母不同（t 与 d），意思是人的身体素质，即体质。"}, {"text": "地质", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，zhì 相同，意思是地球的构造与变化。"}], "explanations": {"抵制": "本词，读作 dǐ zhì，表示拒绝或反对某种行为、商品或活动。", "地址": "dì（第四声）与 dǐ（第三声）声调不同，zhǐ 与 zhì 声调也不同，意思是地址。", "体质": "tǐ 与 dǐ 声母不同（t 与 d），意思是人的身体素质，即体质。", "地质": "dì（第四声）与 dǐ（第三声）声调不同，zhì 相同，意思是地球的构造与变化。"}, "sentence_index": null, "correct_answer": "抵制"}, "level_3": {"options": [{"text": "抵制", "is_correct": true, "explanation": "原句中的词，表示反对不文明的行为，与句子的评价一致。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”与“不文明的行为”的评价相反。"}, {"text": "赞赏", "is_correct": false, "explanation": "语义：“赞赏”与“不文明”的评价矛盾。"}, {"text": "配合", "is_correct": false, "explanation": "搭配：“配合”的对象多为工作、活动，不接“行为”这类对象。"}], "explanations": {"抵制": "原句中的词，表示反对不文明的行为，与句子的评价一致。", "欢迎": "语义：“欢迎”与“不文明的行为”的评价相反。", "赞赏": "语义：“赞赏”与“不文明”的评价矛盾。", "配合": "搭配：“配合”的对象多为工作、活动，不接“行为”这类对象。"}, "sentence_index": 6, "correct_answer": "抵制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿坏了，一口气抵制了三碗米饭。", "explanation": "这里应该用〈吃〉。“抵制”表示拒绝、反对，不表示进食。"}, {"text": "他用汽车抵制了一笔欠款。", "explanation": "这里应该用〈抵偿〉。“抵制”表示拒绝、反对，不表示用财物还债。"}, {"text": "列车终于抵制了目的地。", "explanation": "这里应该用〈抵达〉。“抵制”表示拒绝、反对，不表示到达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该抵制于浪费粮食的做法。", "corrected_sentence": "我们应该抵制浪费粮食的做法。", "error_description": "错误形式：多加介词“于”。正确形式：“抵制”是及物动词，后面直接接宾语，不说“抵制于……”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们抵制把虚假信息，不转发。", "corrected_sentence": "学生们抵制虚假信息，不转发。", "error_description": "错误形式：在“虚假信息”前多加“把”。正确形式：“抵制虚假信息”。“抵制”可直接接宾语，不能再加“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73cd28fe-ce5f-4225-ba7a-536b52a5ff8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
