INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13428, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使身体或头偏向一边。", "primary_collocate": null, "pronunciation": "cè", "ipa": "tsʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "他侧着头，认真听老师说话。", "target_word": "侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门太窄了，我只好侧着身子走进去。", "target_word": "侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她侧过脸，看了看窗外的雪。", "target_word": "侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫侧着头，好奇地看着鱼缸。", "target_word": "侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车来了，他侧过身让老人先上去。", "target_word": "侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "躺着看书太累，他侧着身子睡了。", "target_word": "侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈侧着脸，轻轻地亲了亲孩子。", "target_word": "侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走廊很窄，两个人要侧着身才能过。", "target_word": "侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让我侧着躺，检查后背。", "target_word": "侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他侧过头，小声对我说了几句话。", "target_word": "侧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "側", "label": "繁体"}, {"form": "侧着", "label": "体标"}, {"form": "侧过", "label": "体标"}, {"form": "侧身", "label": "复合"}], "register": "中性", "sense_fingerprint": "侧：使身体或头偏向一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11fef44c-77a9-473d-bd53-ecd3ab0c912e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摇", "is_correct": false, "explanation": "语义：摇头表示否定，与“认真听老师说话”的状态相矛盾。"}, {"text": "侧", "is_correct": true, "explanation": "正确。“侧”表示头偏向一边，与“着头”搭配，符合句意。"}, {"text": "抱", "is_correct": false, "explanation": "语义：抱头多表示烦恼或疼痛，与认真听讲的状态不符。"}, {"text": "拍", "is_correct": false, "explanation": "语义：“拍头”是用手打头部，与“认真听老师说话”的姿态不符。"}], "explanations": {"摇": "语义：摇头表示否定，与“认真听老师说话”的状态相矛盾。", "侧": "正确。“侧”表示头偏向一边，与“着头”搭配，符合句意。", "抱": "语义：抱头多表示烦恼或疼痛，与认真听讲的状态不符。", "拍": "语义：“拍头”是用手打头部，与“认真听老师说话”的姿态不符。"}, "sentence_index": 0, "correct_answer": "侧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天侧着书包去上学。", "explanation": "这里应该用〈背〉。“侧”表示使身体或头偏向一边，不能表示把书包放在背上携带。"}, {"text": "他把杯子侧得很正，水一滴也没洒。", "explanation": "这里应该用〈端〉。“侧”表示偏向一边，与“很正”相矛盾；把杯子端平要说“端”。"}, {"text": "他的发言侧重经济问题。", "explanation": "这里的“侧重”是另一个词，意思是着重，与本词“使身体或头偏向一边”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捂", "is_correct": false, "explanation": "语义：捂脸多表示难过或害羞，与“轻轻地亲了亲孩子”的画面不符。"}, {"text": "板", "is_correct": false, "explanation": "语义：板着脸表示严肃或生气，与“轻轻地亲了亲孩子”的温柔语气矛盾。"}, {"text": "侧", "is_correct": true, "explanation": "正确。“侧着脸”描述脸偏向一边，与后面的动作相合。"}, {"text": "晃", "is_correct": false, "explanation": "搭配：“晃”多指身体或物体摇动，不说“晃着脸”。"}], "explanations": {"捂": "语义：捂脸多表示难过或害羞，与“轻轻地亲了亲孩子”的画面不符。", "板": "语义：板着脸表示严肃或生气，与“轻轻地亲了亲孩子”的温柔语气矛盾。", "侧": "正确。“侧着脸”描述脸偏向一边，与后面的动作相合。", "晃": "搭配：“晃”多指身体或物体摇动，不说“晃着脸”。"}, "sentence_index": 6, "correct_answer": "侧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把相框侧得很平，挂在墙上。", "explanation": "这里应该用〈摆〉。“侧”表示偏向一边，与“很平”相矛盾；把相框摆平要说“摆”。"}, {"text": "这份报告侧重于数据分析。", "explanation": "这里的“侧重”是另一个词，意思是着重，与本词“使身体或头偏向一边”无关。"}, {"text": "他侧开门，走了进去。", "explanation": "这里应该用〈推〉。“侧”只表示偏向，不能表示用力推门；推开门要说“推”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她侧了着身子，从人群里挤过去。", "corrected_sentence": "她侧着身子，从人群里挤过去。", "error_description": "体标错误：“侧”后面用“着”表示状态，不能同时加“了”。“侧了着”不通，应说“侧着身子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把头侧，听我说话。", "corrected_sentence": "他把头侧过来，听我说话。", "error_description": "补语缺失：“把”字句中动词“侧”后需要补语，“把头侧”不完整。应说“把头侧过来”，补上“过来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
