INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13429, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13429, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指减轻负担，通常用于减少学生课业或工作压力。", "primary_collocate": null, "pronunciation": "jiǎn fù", "ipa": "tɕjɛn˨˩ fu˥˩", "syllable_count": 2, "sentences": [{"text": "唯有通过教育与公共政策引导，培育“少而精”的理性消费文化，抵制过度消费的符号化冲动，方能在需求侧为资源减负创造空间。", "target_word": "减负", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "学校今年决定给学生减负。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们都在想办法为孩子减负。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司推出新制度，为员工减负。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减负以后，学生有了更多休息时间。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多家长盼着学校早点减负。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新办法能帮医生减负。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减负不是不学习，而是学得更轻松。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师少布置作业，就是在给学生减负。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了给工人减负，工厂买了新机器。", "target_word": "减负", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减负了", "label": "体标"}, {"form": "减负增效", "label": "复合"}], "register": "中性", "sense_fingerprint": "动宾式动词，减轻学生、员工等的课业或工作负担，常说“给／为……减负”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fc57a-06de-4b32-86c6-7fa8c22896d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13429, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减负", "is_correct": true, "explanation": "正确：「减负」指减轻负担，与前文“抵制过度消费”的意图一致。"}, {"text": "设限", "is_correct": false, "explanation": "语义：「设限」指设置限制，与「创造空间」的意思相反。"}, {"text": "加压", "is_correct": false, "explanation": "语义：「加压」指增加压力，与「创造空间」的意思相反。"}, {"text": "加码", "is_correct": false, "explanation": "语义：「加码」指增加数量或任务，与「减负」的减轻之意相反，且「为资源加码」在此句中不成立。"}], "explanations": {"减负": "正确：「减负」指减轻负担，与前文“抵制过度消费”的意图一致。", "设限": "语义：「设限」指设置限制，与「创造空间」的意思相反。", "加压": "语义：「加压」指增加压力，与「创造空间」的意思相反。", "加码": "语义：「加码」指增加数量或任务，与「减负」的减轻之意相反，且「为资源加码」在此句中不成立。"}, "sentence_index": 0, "correct_answer": "减负"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请把空调温度减负两度。", "explanation": "这里应该用〈调低〉。「减负」指减轻课业或工作负担，不能用于温度，降低温度要用「调低」。"}, {"text": "他通过节食减负十斤。", "explanation": "这里应该用〈减重〉。「减负」指减轻负担，不用于体重，减轻体重要用「减重」。"}, {"text": "学校减负学费。", "explanation": "这里应该用〈减免〉。「减负」用于负担，不能直接带“学费”这类费用，免除费用要用「减免」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13429, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减负", "is_correct": true, "explanation": "正确：「减负」指减轻负担，与「能帮医生」的积极作用一致。"}, {"text": "加班", "is_correct": false, "explanation": "语义：「加班」是增加工作时间，与「帮」的积极作用相反。"}, {"text": "添堵", "is_correct": false, "explanation": "语义：「添堵」指给人添麻烦、使人不痛快，与「帮」的积极作用相反。"}, {"text": "加码", "is_correct": false, "explanation": "搭配：「加码」指提高指标或数量，不能用于「帮医生」这类表示帮助的语境。"}], "explanations": {"减负": "正确：「减负」指减轻负担，与「能帮医生」的积极作用一致。", "加班": "语义：「加班」是增加工作时间，与「帮」的积极作用相反。", "添堵": "语义：「添堵」指给人添麻烦、使人不痛快，与「帮」的积极作用相反。", "加码": "搭配：「加码」指提高指标或数量，不能用于「帮医生」这类表示帮助的语境。"}, "sentence_index": 6, "correct_answer": "减负"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车在路口减负。", "explanation": "这里应该用〈减速〉。「减负」指减轻负担，不能用于速度，汽车慢下来要用「减速」。"}, {"text": "商场为了促销减负。", "explanation": "这里应该用〈降价〉。「减负」指减轻负担，价格下降要用「降价」。"}, {"text": "工厂因为效益差而减负人数。", "explanation": "这里应该用〈减员〉。「减负」的对象是负担，不能直接带“人数”作宾语，减少人数要用「减员」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校向学生减负。", "corrected_sentence": "学校为学生减负。", "error_description": "错误：「减负」的对象前应用「为」或「给」，不能用「向」。正确：「学校为学生减负。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂为工人减负负担，买了新机器。", "corrected_sentence": "工厂为工人减负，买了新机器。", "error_description": "错误：「减负」本身已含“减轻负担”的意思，后面不能再加宾语「负担」，多余。正确：「工厂为工人减负，买了新机器。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
