INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13430, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13430, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可以发展或行动的余地或机会", "primary_collocate": null, "pronunciation": "kōng jiān", "ipa": "kʰʊŋ˥ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "唯有通过教育与公共政策引导，培育“少而精”的理性消费文化，抵制过度消费的符号化冲动，方能在需求侧为资源减负创造空间。", "target_word": "空间", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司要给年轻人更多成长的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司还有很大的发展空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格已经很低，没有再降的空间了。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你给了我自己选择的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他觉得在这里没有进步的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个行业的上升空间很大。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理给了新人犯错的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作让我有很多学习的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行说利率还有调整的空间。", "target_word": "空间", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "空間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "发展或行动的余地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b63a2c7-7b4b-4b6e-a491-5467c19626e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空间", "is_correct": true, "explanation": "正确。“空间”指可以发展或行动的余地，这里说为资源减负留出余地。"}, {"text": "眼神", "is_correct": false, "explanation": "搭配：“创造”不接“眼神”，“创造眼神”说不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：为资源减负不能“创造性格”，与句意无关。"}, {"text": "体重", "is_correct": false, "explanation": "语义：资源减负与体重无关，“创造体重”说不通。"}], "explanations": {"空间": "正确。“空间”指可以发展或行动的余地，这里说为资源减负留出余地。", "眼神": "搭配：“创造”不接“眼神”，“创造眼神”说不通。", "性格": "语义：为资源减负不能“创造性格”，与句意无关。", "体重": "语义：资源减负与体重无关，“创造体重”说不通。"}, "sentence_index": 0, "correct_answer": "空间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆列车的空间很快。", "explanation": "这里应该用〈速度〉。空间指可以行动的余地，不能用来形容快慢；说列车快要用“速度”。"}, {"text": "他终于等到了这次空间。", "explanation": "这里应该用〈机会〉。空间指可以行动的余地，不能说“这次空间”；指一次难得的时机要用“机会”。"}, {"text": "他的空间很低落。", "explanation": "这里应该用〈心情〉。空间指可以发展或行动的余地，不能用来形容人的情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空间", "is_correct": true, "explanation": "正确。“空间”指可以发展的余地，这里说行业的上升余地大。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：行业的上升不能用“颜色”来衡量，“上升颜色很大”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：行业的上升与气味无关，“上升味道很大”说不通。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“上升”不搭配“寿命”，“上升寿命”不是常见说法。"}], "explanations": {"空间": "正确。“空间”指可以发展的余地，这里说行业的上升余地大。", "颜色": "语义：行业的上升不能用“颜色”来衡量，“上升颜色很大”说不通。", "味道": "语义：行业的上升与气味无关，“上升味道很大”说不通。", "寿命": "搭配：“上升”不搭配“寿命”，“上升寿命”不是常见说法。"}, "sentence_index": 6, "correct_answer": "空间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这朵花的空间很鲜艳。", "explanation": "这里应该用〈颜色〉。空间不能用来形容颜色的鲜艳程度；说花的颜色鲜艳要用“颜色”。"}, {"text": "这台机器的空间还很长。", "explanation": "这里应该用〈寿命〉。空间不表示使用年限，说机器还能用多久要用“寿命”。"}, {"text": "她的空间已经三十岁了。", "explanation": "这里应该用〈年龄〉。空间指可以行动的余地或机会，不能用来说人的岁数；说人多大了要用“年龄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事情还有一张商量的空间。", "corrected_sentence": "这件事情还有一点商量的空间。", "error_description": "量词错误：“张”用于纸张、桌子等平面的东西，不用于抽象的“余地”义，这里应说“一点商量的空间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的发展空间很高。", "corrected_sentence": "这家公司的发展空间很大。", "error_description": "搭配错误：“空间”说大小，不说高低。应为“发展空间很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13431, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13431, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13431, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容资源丰富，用不完。", "primary_collocate": null, "pronunciation": "qǔ zhī bù jìn", "ipa": "tɕʰy˨˩˦ ʈʂɻ̩˥ pu˥˩ tɕin˥˩", "syllable_count": 4, "sentences": [{"text": "水资源并非取之不尽的背景性资源，而是维系文明存续的流动命脉。", "target_word": "取之不尽", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "大海里的宝藏好像取之不尽。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳能是一种取之不尽的能源。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前人们以为森林是取之不尽的。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风能取之不尽，用起来也很干净。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "潮汐能取之不尽，是一种清洁的能源。", "target_word": "取之不尽", "complexity_tier": "T3", "furigana": "cháo xī néng qǔ zhī bú jìn, shì yì zhǒng qīng jié de néng yuán.", "sentence_source": "generated"}, {"text": "这座图书馆的藏书取之不尽，足够几代人阅读。", "target_word": "取之不尽", "complexity_tier": "T3", "furigana": "zhè zuò tú shū guǎn de cáng shū qǔ zhī bú jìn, zú gòu jǐ dài rén yuè dú.", "sentence_source": "generated"}, {"text": "大自然给我们的资源并不是取之不尽的。", "target_word": "取之不尽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的水取之不尽，村里人从来不缺水。", "target_word": "取之不尽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的想象力好像取之不尽。", "target_word": "取之不尽", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "取之不尽的", "label": "定语形式"}, {"form": "取之不尽，用之不竭", "label": "固定搭配"}], "register": "书面语", "sense_fingerprint": "资源丰富，怎么用都用不完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11fef44c-77a9-473d-bd53-ecd3ab0c912e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13431, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取之不尽", "is_correct": true, "explanation": "正确：与“并非……而是……”的否定结构相合，句意是水资源并非用不完的背景资源。"}, {"text": "易碎", "is_correct": false, "explanation": "语义：“易碎”形容物品，不能修饰“水资源”，句意不通。"}, {"text": "快乐", "is_correct": false, "explanation": "搭配：“快乐”形容人的情绪，不能修饰“背景性资源”。"}, {"text": "木制", "is_correct": false, "explanation": "语义：“水资源”不是木材，“木制”与“水”冲突。"}], "explanations": {"取之不尽": "正确：与“并非……而是……”的否定结构相合，句意是水资源并非用不完的背景资源。", "易碎": "语义：“易碎”形容物品，不能修饰“水资源”，句意不通。", "快乐": "搭配：“快乐”形容人的情绪，不能修饰“背景性资源”。", "木制": "语义：“水资源”不是木材，“木制”与“水”冲突。"}, "sentence_index": 0, "correct_answer": "取之不尽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个箱子取之不尽。", "explanation": "这里应该用〈装不下〉。取之不尽只形容资源用不完，不能用来形容箱子之类的容器。"}, {"text": "他的话取之不尽。", "explanation": "这里应该用〈滔滔不绝〉。取之不尽只形容资源丰富，不用于形容说话连续不断。"}, {"text": "这些学生取之不尽。", "explanation": "这里应该用〈很多〉。取之不尽形容物资，指人数多时不说“取之不尽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13431, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取之不尽", "is_correct": true, "explanation": "正确：与后句“足够几代人阅读”呼应，说明藏书用不完。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：“稀少”与“足够几代人阅读”相矛盾，藏书不可能既少又够用。"}, {"text": "残缺", "is_correct": false, "explanation": "语义：“残缺”说明藏书不完整，与“足够几代人阅读”相悖。"}, {"text": "寂静", "is_correct": false, "explanation": "搭配：“寂静”形容环境或声音，不能修饰“藏书”。"}], "explanations": {"取之不尽": "正确：与后句“足够几代人阅读”呼应，说明藏书用不完。", "稀少": "语义：“稀少”与“足够几代人阅读”相矛盾，藏书不可能既少又够用。", "残缺": "语义：“残缺”说明藏书不完整，与“足够几代人阅读”相悖。", "寂静": "搭配：“寂静”形容环境或声音，不能修饰“藏书”。"}, "sentence_index": 6, "correct_answer": "取之不尽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对你的感激取之不尽。", "explanation": "这里应该用〈感激不尽〉。取之不尽形容资源用不完，不用于表达情感；对别人的帮助感谢到极点应说“感激不尽”。"}, {"text": "她的性情取之不尽。", "explanation": "这里应该用〈善变〉。取之不尽只用于资源，不用于形容性格或性情。"}, {"text": "他的不幸取之不尽。", "explanation": "这里应该用〈接二连三〉。取之不尽形容资源用不完，不能用来说不幸的事；不幸接连出现应说“接二连三”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13431, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片森林里有取之不尽木材。", "corrected_sentence": "这片森林里有取之不尽的木材。", "error_description": "错误形式：“取之不尽木材”，漏掉定语标记“的”。正确形式：“取之不尽的木材”。取之不尽作定语修饰名词时必须加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13431, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片海域的鱼很取之不尽，渔民常年打不完。", "corrected_sentence": "这片海域的鱼取之不尽，渔民常年打不完。", "error_description": "错误形式：“很取之不尽”，给取之不尽加了程度副词“很”。正确形式：“取之不尽”直接作谓语，不加“很”。取之不尽是四字格，一般不接“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
