INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13432, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "命脉指维持生命或事物生存、发展的最关键部分或因素。", "primary_collocate": null, "pronunciation": "mìng mài", "ipa": "miŋ˥˩ mai˥˩", "syllable_count": 2, "sentences": [{"text": "水资源并非取之不尽的背景性资源，而是维系文明存续的流动命脉。", "target_word": "命脉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "电力是现代工厂的命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河是当地人的命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油曾是这个国家的经济命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交通是城市发展的命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "诚信是做生意的命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这家公司来说，技术就是命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路是山区通向外面的命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们牢牢把握着国家的经济命脉。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦切断了命脉，工厂就无法生产。", "target_word": "命脉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "经济命脉", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，决定国家、行业、事物生存与发展的最关键部分，如经济命脉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fc57a-06de-4b32-86c6-7fa8c22896d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "命脉", "is_correct": true, "explanation": "正确：“流动的命脉”指维系文明存续的关键，与前文“维系文明存续”的语境吻合。"}, {"text": "风景", "is_correct": false, "explanation": "语义：“风景”不能维系文明存续，与“维系文明存续”的语境矛盾。"}, {"text": "窍门", "is_correct": false, "explanation": "语域：“窍门”是口语词，与这句书面语的论述语体不合，且不指维系存续的关键。"}, {"text": "盲点", "is_correct": false, "explanation": "搭配：“盲点”指看不到的地方，不能被“流动”修饰，也不能用来说维系文明的存续。"}], "explanations": {"命脉": "正确：“流动的命脉”指维系文明存续的关键，与前文“维系文明存续”的语境吻合。", "风景": "语义：“风景”不能维系文明存续，与“维系文明存续”的语境矛盾。", "窍门": "语域：“窍门”是口语词，与这句书面语的论述语体不合，且不指维系存续的关键。", "盲点": "搭配：“盲点”指看不到的地方，不能被“流动”修饰，也不能用来说维系文明的存续。"}, "sentence_index": 0, "correct_answer": "命脉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的命脉比我高一头。", "explanation": "这里应该用〈个子〉。命脉指事物生存、发展的关键部分，不用来形容身高。"}, {"text": "这座古桥的命脉已经两百岁了。", "explanation": "这里应该用〈寿命〉。命脉指事物生存、发展的关键部分，不用来说事物存在的年限。"}, {"text": "医生按着他的手腕，数着他的命脉。", "explanation": "这里应该用〈脉搏〉。命脉指关键部分，不是可以用手指测量的脉搏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "命脉", "is_correct": true, "explanation": "正确：“技术就是命脉”说明技术是公司存续的关键，与语境吻合。"}, {"text": "午餐", "is_correct": false, "explanation": "语义：“午餐”是一顿饭，不能作为公司存续的判断对象，与“技术就是”的论断不合。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“窗帘”是室内陈设，不能与“技术就是”构成对公司根本作用的判断。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：“篮球”是体育用品，无法表达技术对公司生存的关键作用。"}], "explanations": {"命脉": "正确：“技术就是命脉”说明技术是公司存续的关键，与语境吻合。", "午餐": "语义：“午餐”是一顿饭，不能作为公司存续的判断对象，与“技术就是”的论断不合。", "窗帘": "搭配：“窗帘”是室内陈设，不能与“技术就是”构成对公司根本作用的判断。", "篮球": "语义：“篮球”是体育用品，无法表达技术对公司生存的关键作用。"}, "sentence_index": 6, "correct_answer": "命脉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对她的命脉很深。", "explanation": "这里应该用〈感情〉。命脉指关键部分，不用来形容人的情感。"}, {"text": "这场比赛的命脉很精彩。", "explanation": "这里应该用〈过程〉。命脉指关键部分，不用来形容比赛的精彩程度。"}, {"text": "这场会议的命脉持续了两个小时。", "explanation": "这里应该用〈时长〉。命脉指维持生存的关键，不用来说活动持续的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农业是这个村子的一把命脉。", "corrected_sentence": "农业是这个村子的一条命脉。", "error_description": "量词错误：“命脉”的正确量词是〈条〉，〈把〉用于有柄的器具。应改为“一条命脉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电网是这座城市的一棵命脉。", "corrected_sentence": "电网是这座城市的一条命脉。", "error_description": "量词错误：“命脉”的正确量词是〈条〉，〈棵〉用于树木。应改为“一条命脉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13433, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昂贵", "is_correct": true, "explanation": "反义：廉价 与 昂贵 指价钱的低与高，两者相对。"}, {"text": "干净", "is_correct": false, "explanation": "与「廉价」的价钱意义无关，是形容洁净的词，不是反义词。"}, {"text": "宽敞", "is_correct": false, "explanation": "形容空间大，与「廉价」的价钱意义无关，不构成反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "形容光线充足，与「廉价」的价钱意义无关，不构成反义关系。"}], "correct_answer": "昂贵", "explanations": {"昂贵": "反义：廉价 与 昂贵 指价钱的低与高，两者相对。", "干净": "与「廉价」的价钱意义无关，是形容洁净的词，不是反义词。", "宽敞": "形容空间大，与「廉价」的价钱意义无关，不构成反义关系。", "明亮": "形容光线充足，与「廉价」的价钱意义无关，不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13433, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "昂贵", "is_correct": true, "explanation": "反义：廉价 与 昂贵 指价钱的低与高，两者相对。"}, {"text": "清楚", "is_correct": false, "explanation": "形容明白、不模糊，与「廉价」的价钱意义无关，不构成反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "形容温度或感觉，与「廉价」的价钱意义无关，不构成反义关系。"}, {"text": "轻便", "is_correct": false, "explanation": "形容分量轻、便于携带，与「廉价」的价钱意义无关，不构成反义关系。"}], "correct_answer": "昂贵", "explanations": {"昂贵": "反义：廉价 与 昂贵 指价钱的低与高，两者相对。", "清楚": "形容明白、不模糊，与「廉价」的价钱意义无关，不构成反义关系。", "温暖": "形容温度或感觉，与「廉价」的价钱意义无关，不构成反义关系。", "轻便": "形容分量轻、便于携带，与「廉价」的价钱意义无关，不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13433, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "价钱低，相比一般水平花费更少。", "primary_collocate": null, "pronunciation": "lián jià", "ipa": "li̯ɛn˧˥ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "当每一件廉价T恤背后都映射出干涸的河流与受污的土壤，我们不得不重新审视时尚的真正成本。", "target_word": "廉价", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种廉价的衣服质量不错，适合学生穿。", "target_word": "廉价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一部廉价的手机。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店卖的都是廉价的东西。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "廉价机票让很多人去旅行。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想用廉价的杯子喝茶。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "廉价的玩具容易坏。", "target_word": "廉价", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种廉价的笔一块钱一支。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生常常住在廉价的小房子里。", "target_word": "廉价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在路边买了一条廉价的围巾送给妈妈。", "target_word": "廉价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "廉價", "label": "繁体"}], "register": "中性", "sense_fingerprint": "商品或服务价格低于一般水平，常暗含质量一般或成本被压低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e30e707f-e868-41d3-92c0-29d881cfc989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13433, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "廉价", "is_correct": true, "explanation": "正确答案。廉价 lián jià 指价钱低，相比一般水平花费更少。"}, {"text": "年假", "is_correct": false, "explanation": "nián（n）与 lián（l）声母不同，年假 nián jià 意思是一年一度的假期，不是廉价。"}, {"text": "粮价", "is_correct": false, "explanation": "liáng 与 lián 韵母不同（ang 与 an），粮价 liáng jià 指粮食的价格。"}, {"text": "连接", "is_correct": false, "explanation": "jiē 与 jià 的韵母和声调都不同，连接 lián jiē 意思是把两者接在一起。"}], "explanations": {"廉价": "正确答案。廉价 lián jià 指价钱低，相比一般水平花费更少。", "年假": "nián（n）与 lián（l）声母不同，年假 nián jià 意思是一年一度的假期，不是廉价。", "粮价": "liáng 与 lián 韵母不同（ang 与 an），粮价 liáng jià 指粮食的价格。", "连接": "jiē 与 jià 的韵母和声调都不同，连接 lián jiē 意思是把两者接在一起。"}, "sentence_index": null, "correct_answer": "廉价"}, "level_3": {"options": [{"text": "廉价", "is_correct": true, "explanation": "正确：廉价修饰T恤，指价钱低、成本被压低，与句中「真正成本」的批判相合。"}, {"text": "慢慢", "is_correct": false, "explanation": "词性：“慢慢”是副词，不能直接修饰名词“T恤”。"}, {"text": "已经", "is_correct": false, "explanation": "词性：“已经”是副词，不能直接修饰名词“T恤”。"}, {"text": "赶紧", "is_correct": false, "explanation": "词性：“赶紧”是副词，不能直接修饰名词“T恤”。"}], "explanations": {"廉价": "正确：廉价修饰T恤，指价钱低、成本被压低，与句中「真正成本」的批判相合。", "慢慢": "词性：“慢慢”是副词，不能直接修饰名词“T恤”。", "已经": "词性：“已经”是副词，不能直接修饰名词“T恤”。", "赶紧": "词性：“赶紧”是副词，不能直接修饰名词“T恤”。"}, "sentence_index": 0, "correct_answer": "廉价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次体检的结果很廉价，医生说一切都正常。", "explanation": "这里应该用〈良好〉。廉价主要形容价钱低的东西，不用来评价体检结果；良好可用于评价情况、结果。"}, {"text": "这位老人的记性很廉价，几十年前的事都记得。", "explanation": "这里应该用〈好〉。好可用于记性、能力；廉价主要形容价钱低的东西，不能用来形容记性。"}, {"text": "这次考试他的分数很廉价，还要多努力。", "explanation": "这里应该用〈低〉。低可用于分数、成绩；廉价只形容价钱低的东西，不用于分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13433, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "廉价", "is_correct": true, "explanation": "正确：廉价修饰玩具，说明它价钱低、质量一般，所以容易坏。"}, {"text": "结实", "is_correct": false, "explanation": "语义：「结实」说质量好、不易坏，与「容易坏」矛盾。"}, {"text": "耐用", "is_correct": false, "explanation": "语义：「耐用」说能长时间使用，与「容易坏」矛盾。"}, {"text": "坚固", "is_correct": false, "explanation": "搭配：「坚固」多用于建筑、结构，说玩具不如「结实」自然，且与「容易坏」矛盾。"}], "explanations": {"廉价": "正确：廉价修饰玩具，说明它价钱低、质量一般，所以容易坏。", "结实": "语义：「结实」说质量好、不易坏，与「容易坏」矛盾。", "耐用": "语义：「耐用」说能长时间使用，与「容易坏」矛盾。", "坚固": "搭配：「坚固」多用于建筑、结构，说玩具不如「结实」自然，且与「容易坏」矛盾。"}, "sentence_index": 6, "correct_answer": "廉价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的身高很廉价，班里没人比他高。", "explanation": "这里应该用〈高〉。高用于身高、个子；廉价只形容价钱低的东西，不能用来说人的身高。"}, {"text": "这道题他讲得很廉价，我还是不会做。", "explanation": "这里应该用〈清楚〉。清楚指讲解明白、易懂；廉价只形容价钱低的东西，不用来评价讲解。"}, {"text": "这条街很廉价，到处都是人。", "explanation": "这里应该用〈热闹〉。热闹形容场面、气氛；廉价只形容价钱低的东西，不能用于街道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在路边买了一把廉价地伞。", "corrected_sentence": "我在路边买了一把廉价的伞。", "error_description": "「廉价」修饰名词「伞」时应用「的」，不能用「地」。「地」用于修饰动词，所以应说「一把廉价的伞」，不能说「廉价地伞」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13433, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个包比那个包很廉价。", "corrected_sentence": "这个包比那个包廉价。", "error_description": "「比」字句中，「廉价」前不能加「很」。应说「比那个包廉价」，或说「廉价得多」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
