INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13434, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指水分完全消失，变得没有水。", "primary_collocate": null, "pronunciation": "gān hé", "ipa": "kan˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "当每一件廉价T恤背后都映射出干涸的河流与受污的土壤，我们不得不重新审视时尚的真正成本。", "target_word": "干涸", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "河水干涸，鱼没有水。", "target_word": "干涸", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天太热，小河慢慢干涸了。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这口井已经干涸很多年了。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长期没有下雨，田边的水塘全都干涸了。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙漠里的泉水干涸后，动物只好离开。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为过度用水，这条河每年春天都会干涸。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他蹲在干涸的池塘边，想找几条小鱼。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "干涸的土地上，一棵草也没有。", "target_word": "干涸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大湖干涸过两次，现在又有水了。", "target_word": "干涸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干涸了", "label": "体标（了）"}, {"form": "干涸过", "label": "体标（过）"}, {"form": "乾涸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "河湖、水井、水塘等的水分完全消失，变得没有水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e30e707f-e868-41d3-92c0-29d881cfc989') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干涸", "is_correct": true, "explanation": "正确：干涸修饰河流，指水分完全消失，与句中「映射出」的环境破坏相合。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」说人或物的体形，不用来形容河流。"}, {"text": "繁茂", "is_correct": false, "explanation": "搭配：「繁茂」多用于草木，不用来形容河流。"}, {"text": "挺拔", "is_correct": false, "explanation": "体貌：「挺拔」说树木或人的身形，不用来形容河流。"}], "explanations": {"干涸": "正确：干涸修饰河流，指水分完全消失，与句中「映射出」的环境破坏相合。", "高大": "体貌：「高大」说人或物的体形，不用来形容河流。", "繁茂": "搭配：「繁茂」多用于草木，不用来形容河流。", "挺拔": "体貌：「挺拔」说树木或人的身形，不用来形容河流。"}, "sentence_index": 0, "correct_answer": "干涸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这束花放了一周，慢慢干涸了。", "explanation": "这里应该用〈枯萎〉。枯萎用于花草失去生机；干涸只用于河、湖、井等水体没有水。"}, {"text": "衣服在外面晒了一天，已经干涸了。", "explanation": "这里应该用〈干〉。衣服没有水了说「干了」；干涸只用于河、湖、井等水体没有水。"}, {"text": "这块蛋糕放了两天，已经干涸了。", "explanation": "这里应该用〈干硬〉。干硬说食物失去水分变硬；干涸只用于河、湖、井等水体没有水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干涸", "is_correct": true, "explanation": "正确：「每年春天都会」说明这条河的情况，与「因为过度用水」的因果相合，干涸最合适。"}, {"text": "上涨", "is_correct": false, "explanation": "语义：「过度用水」会让水减少，「每年春天都会上涨」与句中的因果矛盾。"}, {"text": "充盈", "is_correct": false, "explanation": "语域：「充盈」偏书面，与这句口语化的叙述不协调，且与「过度用水」的因果不符。"}, {"text": "沸腾", "is_correct": false, "explanation": "搭配：「沸腾」指液体受热翻滚，不用来描述河流在春天的状况。"}], "explanations": {"干涸": "正确：「每年春天都会」说明这条河的情况，与「因为过度用水」的因果相合，干涸最合适。", "上涨": "语义：「过度用水」会让水减少，「每年春天都会上涨」与句中的因果矛盾。", "充盈": "语域：「充盈」偏书面，与这句口语化的叙述不协调，且与「过度用水」的因果不符。", "沸腾": "搭配：「沸腾」指液体受热翻滚，不用来描述河流在春天的状况。"}, "sentence_index": 6, "correct_answer": "干涸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火慢慢干涸了，屋里越来越冷。", "explanation": "这里应该用〈熄灭〉。熄灭说火、光失去光亮或热；干涸只用于水分完全消失的水体。"}, {"text": "他的听力已经干涸了。", "explanation": "这里应该用〈减退〉。听力等能力逐渐变弱用减退；干涸只说水分完全消失。"}, {"text": "这座城市的路灯已经干涸了。", "explanation": "这里应该用〈坏了〉。坏可用于机器、设备；干涸只用于水分完全消失的水体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天太热，河水干涸的很快。", "corrected_sentence": "夏天太热，河水干涸得很快。", "error_description": "错误在于补语标记。表示程度的补语要用「得」，不能用「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条河前年就被干涸了。", "corrected_sentence": "那条河前年就干涸了。", "error_description": "错误在于使用了「被」字被动句。干涸是不及物动词，没有受事者，不能用「被」，应说「干涸了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c38b26c-bcfd-4c05-b256-f08815080b14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
