INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13435, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "受到污染或玷污", "primary_collocate": null, "pronunciation": "shòu wū", "ipa": "ʂou˥˩ u˥", "syllable_count": 2, "sentences": [{"text": "当每一件廉价T恤背后都映射出干涸的河流与受污的土壤，我们不得不重新审视时尚的真正成本。", "target_word": "受污", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂排出废水，河水很快就受污了。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受污的土壤种不出好粮食。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河受污多年，鱼都死光了。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的河流受污以后，鱼虾越来越少。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水受污，岸边再也没有人游泳。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家检查了受污的井水。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的沙滩受污后，游客少了很多。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名声因为那件事而受污。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一旦水源受污，全城的人都会生病。", "target_word": "受污", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "受到污染或玷污，指环境或名声受损", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fc57a-06de-4b32-86c6-7fa8c22896d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13435, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受污", "is_correct": true, "explanation": "正确：“受污的土壤”指被污染的土壤，与“干涸的河流”“时尚的真正成本”的批判语境吻合。"}, {"text": "灌溉", "is_correct": false, "explanation": "语义：“灌溉的土壤”指被浇水的土地，与污染成本的批判语境相反。"}, {"text": "施肥", "is_correct": false, "explanation": "搭配：“施肥”针对田地或庄稼，不能与“映射出干涸的河流与”对举构成这一批判语境。"}, {"text": "净化", "is_correct": false, "explanation": "语义：“净化”与“受污”意思相反，“净化的土壤”会与整句的污染批判矛盾。"}], "explanations": {"受污": "正确：“受污的土壤”指被污染的土壤，与“干涸的河流”“时尚的真正成本”的批判语境吻合。", "灌溉": "语义：“灌溉的土壤”指被浇水的土地，与污染成本的批判语境相反。", "施肥": "搭配：“施肥”针对田地或庄稼，不能与“映射出干涸的河流与”对举构成这一批判语境。", "净化": "语义：“净化”与“受污”意思相反，“净化的土壤”会与整句的污染批判矛盾。"}, "sentence_index": 0, "correct_answer": "受污"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子吃了变质的食物，受污了。", "explanation": "这里应该用〈中毒〉。受污指物体或环境被污染，不用来指人吃了坏东西而中毒。"}, {"text": "听到这个消息，他的心情受污了。", "explanation": "这里应该用〈受影响〉。受污指受到污染，不用来指心情被影响。"}, {"text": "他的体重这几个月明显受污了。", "explanation": "这里应该用〈增加〉或〈减轻〉。受污指受到污染，不用来说体重的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13435, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受污", "is_correct": true, "explanation": "正确：“受污的井水”指被污染的井水，与“专家检查”的语境吻合。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”是人的动作，不能修饰井水，句子无法成立。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是人发出的声音，不能修饰井水，与“检查”的对象不合。"}, {"text": "熬夜", "is_correct": false, "explanation": "搭配：“熬夜”是不及物的动作，不能修饰井水，与“检查了”之后的名词搭配不当。"}], "explanations": {"受污": "正确：“受污的井水”指被污染的井水，与“专家检查”的语境吻合。", "哭泣": "语义：“哭泣”是人的动作，不能修饰井水，句子无法成立。", "咳嗽": "语义：“咳嗽”是人发出的声音，不能修饰井水，与“检查”的对象不合。", "熬夜": "搭配：“熬夜”是不及物的动作，不能修饰井水，与“检查了”之后的名词搭配不当。"}, "sentence_index": 6, "correct_answer": "受污"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片湿地受污后变得更干净了。", "explanation": "这里应该用〈净化〉。受污指受到污染，句中“变得更干净”与它的意思相反。"}, {"text": "他的表情这次明显受污了。", "explanation": "这里应该用〈变化〉。受污指受到污染或玷污，不用来说表情的变化。"}, {"text": "他的收入这个月受污了不少。", "explanation": "这里应该用〈减少〉或〈增加〉。受污指受到污染，不用来说收入的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片湿地受污了水，鸟类都飞走了。", "corrected_sentence": "这片湿地受污了，鸟类都飞走了。", "error_description": "错误：「受污」是不及物动词，后面不能带宾语「水」。正确：「这片湿地受污了，鸟类都飞走了。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条小溪被受污了，鱼虾都不见了。", "corrected_sentence": "这条小溪受污了，鱼虾都不见了。", "error_description": "错误：「受」本身已表被动，前面不能再加「被」，属于赘余。正确：「这条小溪受污了，鱼虾都不见了。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
