INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13437, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "除去旧的，创立新的；指这样的变革。", "primary_collocate": null, "pronunciation": "gé xīn", "ipa": "kɤ˧˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "然而，技术革新若无消费观念的同步转变，终将举步维艰。", "target_word": "革新", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这不仅是一场关于清洁技术的革新，更是一场涉及伦理、经济学与生态哲学的深层对话：在增长的极限与美的短暂性之间，人类是否能够构建一种既尊重自然律动又不失审美尊严的可持续美学？", "target_word": "革新", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家工厂的技术革新很成功。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年要进行一次大革新。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育革新需要老师和家长一起努力。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项革新让工人的工作轻松多了。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出的革新得到了大家的支持。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有制度革新，企业很难发展。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的每一次革新都改变生活。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场革新持续了十几年。", "target_word": "革新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "技术革新", "label": "复合"}], "register": "书面语", "sense_fingerprint": "革除旧事物、创造新事物的变革", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fc57a-06de-4b32-86c6-7fa8c22896d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13437, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "把戏", "is_correct": false, "explanation": "语域：“把戏”口语色彩浓、带贬义，与这段书面论述的语域不符，“技术把戏”也不成立。"}, {"text": "香料", "is_correct": false, "explanation": "搭配：“技术香料”不成词，与句中的技术变革语境无关。"}, {"text": "革新", "is_correct": true, "explanation": "“革新”指革除旧的、创造新的，与“技术”组合后接“同步转变”，正合句意。"}, {"text": "外形", "is_correct": false, "explanation": "体貌：“外形”指物体的外观，不能与“技术”构成本句所需的抽象变革概念。"}], "explanations": {"把戏": "语域：“把戏”口语色彩浓、带贬义，与这段书面论述的语域不符，“技术把戏”也不成立。", "香料": "搭配：“技术香料”不成词，与句中的技术变革语境无关。", "革新": "“革新”指革除旧的、创造新的，与“技术”组合后接“同步转变”，正合句意。", "外形": "体貌：“外形”指物体的外观，不能与“技术”构成本句所需的抽象变革概念。"}, "sentence_index": 0, "correct_answer": "革新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国家正在推进革新开放，经济发展很快。", "explanation": "这里应该用〈改革〉。“改革开放”是固定搭配，“革新”不能与“开放”组合。"}, {"text": "这家工厂这次进行了一台大革新。", "explanation": "这里应该用〈次〉或〈场〉。“台”用于机器，不能用来计量“革新”这类行动。"}, {"text": "他们今年推进了一只革新。", "explanation": "这里应该用〈项〉或〈次〉。“只”用于动物或成对的物品，不能计量“革新”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13437, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能被提出，也不能得到支持，句意不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”是器具，不是可以提出的方案或建议，句子意义不通。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”口语色彩强、多指闲话，与“提出”并“得到支持”的正式语境不协调。"}, {"text": "革新", "is_correct": true, "explanation": "“革新”指变革的做法或成果，可以被提出并获得大家的支持，符合句意。"}], "explanations": {"身材": "体貌：“身材”指人的体形，不能被提出，也不能得到支持，句意不通。", "闹钟": "语义：“闹钟”是器具，不是可以提出的方案或建议，句子意义不通。", "八卦": "语域：“八卦”口语色彩强、多指闲话，与“提出”并“得到支持”的正式语境不协调。", "革新": "“革新”指变革的做法或成果，可以被提出并获得大家的支持，符合句意。"}, "sentence_index": 6, "correct_answer": "革新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们厂今年推出了一座大革新，效果很好。", "explanation": "这里应该用〈场〉或〈次〉。“座”用于建筑、山等大型固定之物，不能计量“革新”。"}, {"text": "公司这次设计了一把大革新。", "explanation": "这里应该用〈场〉或〈次〉。“把”用于有柄的器具，不能用来计量“革新”。"}, {"text": "这位经理提出了一张革新。", "explanation": "这里应该用〈项〉或〈次〉。“张”用于纸、桌子等平面之物，不能计量“革新”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只技术革新让产品质量提高了不少。", "corrected_sentence": "这次技术革新让产品质量提高了不少。", "error_description": "量词错误：“革新”前应用“次”，不能用“只”。“只”用于动物或成对的物品，不能计量“革新”这类行动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对这场革新们的效果很满意。", "corrected_sentence": "她对这场革新的效果很满意。", "error_description": "词缀错误：“革新”是抽象名词，不能加“们”表示复数；应说“这场革新的效果”，不说“这场革新们的效果”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '784b3956-115e-44d1-bbd7-261e3d192ff3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
