INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13445, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指有节奏地运动或变化，常用来形容音乐、舞蹈或身体动作的韵律感。", "primary_collocate": null, "pronunciation": "lǜ dòng", "ipa": "ly˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这不仅是一场关于清洁技术的革新，更是一场涉及伦理、经济学与生态哲学的深层对话：在增长的极限与美的短暂性之间，人类是否能够构建一种既尊重自然律动又不失审美尊严的可持续美学？", "target_word": "律动", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这首歌的律动很强。", "target_word": "律动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢海浪的律动。", "target_word": "律动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "音乐的律动让人想跳舞。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天里，大自然充满了律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用身体表现出音乐的律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市的夜晚有自己的律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这幅画里有一种安静的律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鼓声给这段音乐带来了律动。", "target_word": "律动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "舞者随着鼓点起伏，身体的律动十分自然。", "target_word": "律动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞蹈老师说要先感受音乐的律动。", "target_word": "律动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "律动感", "label": "复合"}], "register": "书面", "sense_fingerprint": "音乐、舞蹈或自然中有节奏的运动与变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b47580-90f5-4a9a-ab97-6f640ec498d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13445, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "律动", "is_correct": true, "explanation": "正确：“自然律动”指自然界有节奏的运动与变化，与“生态哲学”“审美尊严”的语境相呼应。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是嘈杂杂乱的声音，与“审美尊严”“美学”的语境相抵触，“尊重自然噪音”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“尊重”的对象可以是自然，但“价格”是经济上的标价，“尊重自然价格”搭配不当。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这句书面语体及学术语境不相称，“尊重自然玩意儿”也不通。"}], "explanations": {"律动": "正确：“自然律动”指自然界有节奏的运动与变化，与“生态哲学”“审美尊严”的语境相呼应。", "噪音": "语义：噪音是嘈杂杂乱的声音，与“审美尊严”“美学”的语境相抵触，“尊重自然噪音”说不通。", "价格": "搭配：“尊重”的对象可以是自然，但“价格”是经济上的标价，“尊重自然价格”搭配不当。", "玩意儿": "语域：“玩意儿”是口语说法，与这句书面语体及学术语境不相称，“尊重自然玩意儿”也不通。"}, "sentence_index": 0, "correct_answer": "律动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在台上露出一个漂亮的律动，大家都看呆了。", "explanation": "这里应该用〈笑容〉。“露出”搭配的是表情或神色，律动指有节奏的运动或韵律感，不能被“露出”。"}, {"text": "这把椅子的律动很牢固。", "explanation": "这里应该用〈结构〉。律动指有节奏的运动或韵律感，说椅子是否牢固要用〈结构〉。"}, {"text": "这段音乐有一块律动。", "explanation": "这里应该用〈种〉。“块”用于有形的块状物，不能用来数抽象的律动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13445, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "律动", "is_correct": true, "explanation": "正确：“有自己的律动”指夜晚城市特有的节奏与起伏，与“城市的夜晚”的语境吻合。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体貌特征，不能用来描述城市的夜晚。"}, {"text": "户口", "is_correct": false, "explanation": "语义：“户口”是户籍登记，与夜晚的城市氛围无关，句子说不通。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“有自己的”后接的是属性或特点，“考试”是活动，搭配不当。"}], "explanations": {"律动": "正确：“有自己的律动”指夜晚城市特有的节奏与起伏，与“城市的夜晚”的语境吻合。", "身高": "体貌：“身高”是人的体貌特征，不能用来描述城市的夜晚。", "户口": "语义：“户口”是户籍登记，与夜晚的城市氛围无关，句子说不通。", "考试": "搭配：“有自己的”后接的是属性或特点，“考试”是活动，搭配不当。"}, "sentence_index": 6, "correct_answer": "律动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鼓手一直在打律动。", "explanation": "这里应该用〈节拍〉。“打节拍”是常见搭配，律动指有节奏的运动，不能被“打”。"}, {"text": "他是一个很高大的律动。", "explanation": "这里应该用〈人〉。律动指有节奏的运动或韵律感，是抽象的，不能用来指人。"}, {"text": "这段旋律里有一根律动。", "explanation": "这里应该用〈种〉。“根”用于细长的东西，不能用来数抽象的律动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海浪有一朵独特的律动。", "corrected_sentence": "海浪有一种独特的律动。", "error_description": "量词错误：“律动”是抽象的韵律，不能用“朵”（“朵”用于花、云等）来数，应说“一种独特的律动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段低音让歌曲有了清晰的律动们。", "corrected_sentence": "这段低音让歌曲有了清晰的律动。", "error_description": "“律动”是抽象名词，不能加复数词尾“们”（“们”只用于指人）。应改为“清晰的律动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13446, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13446, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13446, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示不会失去或没有丧失", "primary_collocate": null, "pronunciation": "bù shī", "ipa": "pu˥˩ ʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "这不仅是一场关于清洁技术的革新，更是一场涉及伦理、经济学与生态哲学的深层对话：在增长的极限与美的短暂性之间，人类是否能够构建一种既尊重自然律动又不失审美尊严的可持续美学？", "target_word": "不失", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他输了比赛，但是不失风度。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拒绝了我，可是说话不失礼貌。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师批评学生时，态度仍不失耐心。", "target_word": "不失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然很忙，却不失幽默。", "target_word": "不失", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她换了新工作，还是不失热情。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店很小，但服务不失水准。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人经历过很多事，依然不失童心。", "target_word": "不失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对失败，他依然不失信心。", "target_word": "不失", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当了经理，却不失普通人的本色。", "target_word": "不失", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不失为", "label": "复合"}], "register": "书面语", "sense_fingerprint": "不失：后接风度、礼貌等好品质，表示保持着，没有丧失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88438421-1dc5-4dd6-abb9-54560972ac87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13446, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不失", "is_correct": true, "explanation": "bù shī：没有丧失，保持着某种好品质，是本题的目标词。"}, {"text": "不时", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是常常、时常。"}, {"text": "不是", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是否定判断，并非如此。"}, {"text": "不适", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，意思是身体或感觉不舒服。"}, {"text": "不使", "is_correct": false, "explanation": "shǐ（第三声）与 shī（第一声）声调不同，意思是不用、不让。"}], "explanations": {"不失": "bù shī：没有丧失，保持着某种好品质，是本题的目标词。", "不时": "shí（第二声）与 shī（第一声）声调不同，意思是常常、时常。", "不是": "shì（第四声）与 shī（第一声）声调不同，意思是否定判断，并非如此。", "不适": "shì（第四声）与 shī（第一声）声调不同，意思是身体或感觉不舒服。", "不使": "shǐ（第三声）与 shī（第一声）声调不同，意思是不用、不让。"}, "sentence_index": null, "correct_answer": "不失"}, "level_3": {"options": [{"text": "不失", "is_correct": true, "explanation": "“不失”表示保持着好品质，与“既尊重…又…”的并列结构相合。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”是不重视，与“既尊重自然律动”的并列语义相反，说“又忽视审美尊严”会与可持续美学的理想冲突。"}, {"text": "违背", "is_correct": false, "explanation": "搭配：“违背”多接原则、规律，接“审美尊严”别扭，且与“可持续”的追求相反。"}, {"text": "失去", "is_correct": false, "explanation": "语义：“失去”表示丢掉，与“可持续美学”的目标相悖，整句读来不成立。"}], "explanations": {"不失": "“不失”表示保持着好品质，与“既尊重…又…”的并列结构相合。", "忽视": "语义：“忽视”是不重视，与“既尊重自然律动”的并列语义相反，说“又忽视审美尊严”会与可持续美学的理想冲突。", "违背": "搭配：“违背”多接原则、规律，接“审美尊严”别扭，且与“可持续”的追求相反。", "失去": "语义：“失去”表示丢掉，与“可持续美学”的目标相悖，整句读来不成立。"}, "sentence_index": 0, "correct_answer": "不失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很不失，大家都喜欢和他交朋友。", "explanation": "这里是词性错误：“不失”是动词，不能用“很”修饰作谓语来形容人；形容人应说“很有风度”。"}, {"text": "会议上他的不失让大家都很佩服。", "explanation": "这里是词性错误：“不失”是动词，不能加“的”变成名词作主语；应说“他的风度让大家都很佩服”。"}, {"text": "我们不失得很远。", "explanation": "这里是补语错误：“不失”是动词，不接程度补语“得”；说走得远要用“走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13446, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不失", "is_correct": true, "explanation": "bù shī：没有丧失，保持着某种好品质，是本题的目标词。"}, {"text": "不知", "is_correct": false, "explanation": "zhī（第一声）与 shī（第一声）声母不同（zh 对 sh），意思是不晓得。"}, {"text": "不吃", "is_correct": false, "explanation": "chī（第一声）与 shī（第一声）声母不同（ch 对 sh），意思是不进食。"}, {"text": "不思", "is_correct": false, "explanation": "sī（第一声）与 shī（第一声）声母不同（s 对 sh），意思是不去想。"}, {"text": "不识", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，意思是不认识。"}], "explanations": {"不失": "bù shī：没有丧失，保持着某种好品质，是本题的目标词。", "不知": "zhī（第一声）与 shī（第一声）声母不同（zh 对 sh），意思是不晓得。", "不吃": "chī（第一声）与 shī（第一声）声母不同（ch 对 sh），意思是不进食。", "不思": "sī（第一声）与 shī（第一声）声母不同（s 对 sh），意思是不去想。", "不识": "shí（第二声）与 shī（第一声）声调不同，意思是不认识。"}, "sentence_index": null, "correct_answer": "不失"}, "level_3": {"options": [{"text": "不失", "is_correct": true, "explanation": "“不失水准”表示没有降低标准，与“但”后面的正面转折相合。"}, {"text": "丢掉", "is_correct": false, "explanation": "语义：“丢掉”表示失去，与“但”引出的正面转折相反，句意不通。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：“忽略”是不注意，与“服务”后面的评价不相符，无法体现转折语义。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”表示主动舍去，与“但”引出的正面转折相反，句意不通。"}], "explanations": {"不失": "“不失水准”表示没有降低标准，与“但”后面的正面转折相合。", "丢掉": "语义：“丢掉”表示失去，与“但”引出的正面转折相反，句意不通。", "忽略": "语义：“忽略”是不注意，与“服务”后面的评价不相符，无法体现转折语义。", "放弃": "语义：“放弃”表示主动舍去，与“但”引出的正面转折相反，句意不通。"}, "sentence_index": 6, "correct_answer": "不失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支球队很不失，球迷都很满意。", "explanation": "这里是词性错误：“不失”是动词，不能用“很”修饰作谓语来评价球队；评价球队可说“很稳定”。"}, {"text": "这位医生很仔细，他的不失很让病人放心。", "explanation": "这里是词性错误：“不失”是动词，不能加“的”变成名词作主语；应说“他的态度很让病人放心”。"}, {"text": "他坚持每天跑步，心率很不失。", "explanation": "这里是词性错误：“不失”是动词，不能用“很”修饰心率；描述心率应说“很稳定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在争论中败下阵来，仍然不失了风度。", "corrected_sentence": "他在争论中败下阵来，仍然不失风度。", "error_description": "“不失”表示持续保持某种品质，后面不加动态助词“了”，此处多出“了”，应删去，写作“仍然不失风度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老人见过大风大浪，仍不失了童心。", "corrected_sentence": "这位老人见过大风大浪，仍不失童心。", "error_description": "“不失”表示持续保持某种品质，是状态动词，后面不接动态助词“了”；此处多出“了”，应删去，写作“仍不失童心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13447, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13447, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13447, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指对美的欣赏、鉴别和判断的能力或活动。", "primary_collocate": null, "pronunciation": "shěn měi", "ipa": "ʂən˨˩ meɪ˨˩", "syllable_count": 2, "sentences": [{"text": "这不仅是一场关于清洁技术的革新，更是一场涉及伦理、经济学与生态哲学的深层对话：在增长的极限与美的短暂性之间，人类是否能够构建一种既尊重自然律动又不失审美尊严的可持续美学？", "target_word": "审美", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "每个人的审美都不一样。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的审美要从小培养。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的审美很特别，穿衣服总是很好看。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的设计符合年轻人的审美。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个时代都有不同的审美。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个国家的审美差别很大。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的审美和我的完全不同，所以我们常常吵架。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的审美变化得很快。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买衣服时，我更相信自己的审美。", "target_word": "审美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种颜色不合我的审美。", "target_word": "审美", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "审美观", "label": "复合"}, {"form": "审美疲劳", "label": "复合"}], "register": "书面", "sense_fingerprint": "对美的欣赏、鉴别和判断的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b47580-90f5-4a9a-ab97-6f640ec498d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13447, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审美", "is_correct": true, "explanation": "正确：“审美尊严”指在鉴赏美的活动中应有的尊重与价值，与“美学”的语境吻合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“尊严”前接的是人或文化的属性，“价格”是经济标价，“不失价格尊严”搭配不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指气象状况，与“尊严”“美学”的语义不相关，句子说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体貌特征，与美学、尊严的语境不相容。"}], "explanations": {"审美": "正确：“审美尊严”指在鉴赏美的活动中应有的尊重与价值，与“美学”的语境吻合。", "价格": "搭配：“尊严”前接的是人或文化的属性，“价格”是经济标价，“不失价格尊严”搭配不通。", "天气": "语义：“天气”指气象状况，与“尊严”“美学”的语义不相关，句子说不通。", "身高": "体貌：“身高”是人的体貌特征，与美学、尊严的语境不相容。"}, "sentence_index": 0, "correct_answer": "审美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的审美是画画和弹钢琴。", "explanation": "这里应该用〈爱好〉。“审美”指对美的鉴赏能力或标准，不指具体做的事，不能说“审美是画画”。"}, {"text": "她在审美一张发票，看看金额对不对。", "explanation": "这里应该用〈核对〉。审美指感受和判断美，不是核对票据的意思，不能用于发票。"}, {"text": "他的审美很好，跑完十公里也不觉得累。", "explanation": "这里应该用〈体力〉。“审美”指对美的鉴赏能力，跑步不累靠的是体力，不能用“审美”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13447, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审美", "is_correct": true, "explanation": "正确：“审美”指对美的鉴赏标准或能力，两国之间可以比较其差别，与语境吻合。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：“心跳”是人体的生理活动，用来比较两个国家的差异不合逻辑。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”属于人的身体特征，不能用来比较国家之间的差别。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，与国家之间的差异无关，句子说不通。"}], "explanations": {"审美": "正确：“审美”指对美的鉴赏标准或能力，两国之间可以比较其差别，与语境吻合。", "心跳": "语义：“心跳”是人体的生理活动，用来比较两个国家的差异不合逻辑。", "体重": "体貌：“体重”属于人的身体特征，不能用来比较国家之间的差别。", "体温": "语义：“体温”指身体的温度，与国家之间的差异无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "审美"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的审美很灵敏，一尝就能分出菜里的盐。", "explanation": "这里应该用〈味觉〉。审美指对美的鉴赏能力，分辨咸淡靠的是味觉，不能用“审美”。"}, {"text": "他的审美很好，电话号码听一遍就能记住。", "explanation": "这里应该用〈记忆力〉。“审美”指对美的鉴赏能力，记住号码靠的是记忆力，不能用“审美”。"}, {"text": "她挑选朋友的审美很准。", "explanation": "这里应该用〈眼光〉。“审美”指对美的鉴赏能力，挑选朋友看的是识人的眼力，不能用“审美”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13447, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一条细腻的审美。", "corrected_sentence": "她有一种细腻的审美。", "error_description": "“审美”是抽象名词，量词应用“种”，不用“条”。应改为“一种细腻的审美”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13447, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一代年轻人有自己的审美们。", "corrected_sentence": "这一代年轻人有自己的审美。", "error_description": "“审美”是抽象名词，不能加复数词尾“们”（“们”只用于指人）。应改为“自己的审美”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
