INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13448, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13448, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指值得尊敬的身份或地位。", "primary_collocate": null, "pronunciation": "zūn yán", "ipa": "tsuən˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这不仅是一场关于清洁技术的革新，更是一场涉及伦理、经济学与生态哲学的深层对话：在增长的极限与美的短暂性之间，人类是否能够构建一种既尊重自然律动又不失审美尊严的可持续美学？", "target_word": "尊严", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老人虽然很穷，但是他很有尊严。", "target_word": "尊严", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想低头，要保住自己的尊严。", "target_word": "尊严", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官的尊严来自公正，不是来自权力。", "target_word": "尊严", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军人的尊严来自他们对国家的责任。", "target_word": "尊严", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教师有教师的尊严，不应该受到侮辱。", "target_word": "尊严", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他丢了工作，却没有丢掉尊严。", "target_word": "尊严", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都应该受到尊重，都有做人的尊严。", "target_word": "尊严", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，穷人也有自己的尊严。", "target_word": "尊严", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说话很客气，是为了保护病人的尊严。", "target_word": "尊严", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人格尊严", "label": "复合"}, {"form": "尊嚴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "值得尊敬的身份或地位；人或职业应有的庄严与体面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b47580-90f5-4a9a-ab97-6f640ec498d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尊严", "is_correct": true, "explanation": "正确。“审美尊严”指审美上的庄严与体面，与“不失”的语境相合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：审美不说“审美价格”，“审美”后不接价格。"}, {"text": "电压", "is_correct": false, "explanation": "语义：电压与美学无关，句中讲的是美的品格，不是电学概念。"}, {"text": "产量", "is_correct": false, "explanation": "语义：产量指生产数量，与“可持续美学”的审美语境不符。"}], "explanations": {"尊严": "正确。“审美尊严”指审美上的庄严与体面，与“不失”的语境相合。", "价格": "搭配：审美不说“审美价格”，“审美”后不接价格。", "电压": "语义：电压与美学无关，句中讲的是美的品格，不是电学概念。", "产量": "语义：产量指生产数量，与“可持续美学”的审美语境不符。"}, "sentence_index": 0, "correct_answer": "尊严"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他手中握有很大的尊严，可以决定大家的命运。", "explanation": "这里应该用〈权力〉。尊严指值得尊敬的身份或地位，握在手里、决定他人命运的是权力，要用〈权力〉。"}, {"text": "这台老机器的尊严很稳定，三年没出过故障。", "explanation": "这里应该用〈性能〉。尊严指值得尊敬的身份或地位，不能用来形容机器的运行状况，要用〈性能〉。"}, {"text": "这台电脑的尊严是三千元。", "explanation": "这里应该用〈价格〉。尊严指值得尊敬的身份或地位，不能用来标价，说多少钱要用〈价格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尊严", "is_correct": true, "explanation": "正确。“没有丢掉尊严”指即使失业，人的体面与身份仍在，语义通顺。"}, {"text": "体重", "is_correct": false, "explanation": "语义：丢工作与体重无关，“没有丢掉体重”不符合句中的对比。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能与“丢工作”形成对比，句意荒谬。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：年龄只说增长或增加，不说“丢掉年龄”。"}], "explanations": {"尊严": "正确。“没有丢掉尊严”指即使失业，人的体面与身份仍在，语义通顺。", "体重": "语义：丢工作与体重无关，“没有丢掉体重”不符合句中的对比。", "颜色": "语义：颜色不能与“丢工作”形成对比，句意荒谬。", "年龄": "搭配：年龄只说增长或增加，不说“丢掉年龄”。"}, "sentence_index": 6, "correct_answer": "尊严"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的尊严是一名律师。", "explanation": "这里应该用〈身份〉。“是……”后接身份或职业，尊严指值得尊敬的地位，不能用来说他是哪种职业。"}, {"text": "他每个月的尊严是五千元。", "explanation": "这里应该用〈收入〉。尊严指身份或地位，不能用来计算金额，说每月赚多少要用〈收入〉。"}, {"text": "这张旧桌子的尊严很结实，用了十年也没坏。", "explanation": "这里应该用〈质量〉。尊严指值得尊敬的身份或地位，不能用来形容家具的结实程度，要用〈质量〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他保住了一个尊严。", "corrected_sentence": "他保住了自己的尊严。", "error_description": "错误形式：“一个尊严”；正确形式：“自己的尊严”。尊严是抽象名词，不宜用个体量词“个”计量，应说“自己的尊严”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他丢掉了尊严们，大家都替他着急。", "corrected_sentence": "他丢掉了尊严，大家都替他着急。", "error_description": "错误形式：“尊严们”；正确形式：“尊严”。“们”只用于指人的复数，不能加在抽象名词“尊严”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
