INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13449, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对问题或题目给出的解答。", "primary_collocate": null, "pronunciation": "dá àn", "ipa": "tɑ˧˥ ɑn˥˩", "syllable_count": 2, "sentences": [{"text": "答案，或许就藏在对消费主义惯性的反思与对供应链正义的执着追求之中。", "target_word": "答案", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这道题的答案是三。", "target_word": "答案", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师问了我一个问题，我知道答案。", "target_word": "答案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道数学题的答案是错的。", "target_word": "答案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想了很久，还是没有找到答案。", "target_word": "答案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试后，老师把正确答案写在黑板上。", "target_word": "答案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题有两个答案，你觉得哪个对？", "target_word": "答案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把你的答案告诉我，好吗？", "target_word": "答案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着我，等我给他答案。", "target_word": "答案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们一直在找这个谜语的答案。", "target_word": "答案", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "标准答案", "label": "复合"}, {"form": "正确答案", "label": "复合"}], "register": "中性", "sense_fingerprint": "答案：对问题或题目给出的解答", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88438421-1dc5-4dd6-abb9-54560972ac87') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13449, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "答案", "is_correct": true, "explanation": "正确：“答案”是对问题的解答，可以“藏在”某种抽象的内容之中，句意通顺。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是具体物件，句中的反思与追求是抽象内容，不能说“手机藏在……之中”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能藏在对消费主义的反思之中。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”不与“藏在……之中”搭配，句中的抽象追求里不会有脚步可藏。"}], "explanations": {"答案": "正确：“答案”是对问题的解答，可以“藏在”某种抽象的内容之中，句意通顺。", "手机": "语义：“手机”是具体物件，句中的反思与追求是抽象内容，不能说“手机藏在……之中”。", "天气": "语义：“天气”是自然现象，不能藏在对消费主义的反思之中。", "脚步": "搭配：“脚步”不与“藏在……之中”搭配，句中的抽象追求里不会有脚步可藏。"}, "sentence_index": 0, "correct_answer": "答案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座建筑的答案有四十层。", "explanation": "这里应该用〈层数〉。“答案”指对问题的解答，不能用来数楼层；建筑的层数要说“层数”。"}, {"text": "这家公司的答案每年都要交税。", "explanation": "这里应该用〈税款〉。“答案”指对问题的解答，不能用来纳税；公司纳税要说“税款”。"}, {"text": "这部电影的答案卖得很好。", "explanation": "这里应该用〈票房〉。“答案”指对问题的解答，不能用“卖得很好”来说；电影的销售成绩要说“票房”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13449, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "答案", "is_correct": true, "explanation": "正确：“两个答案”可以“哪个对”，与句意相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有对错，不能问“你觉得哪个对”。"}, {"text": "房间", "is_correct": false, "explanation": "语义：问题不能说有两个房间，句意不通。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“座位”不与“这个问题有两个……”搭配，问题没有座位可数。"}], "explanations": {"答案": "正确：“两个答案”可以“哪个对”，与句意相合。", "颜色": "语义：颜色没有对错，不能问“你觉得哪个对”。", "房间": "语义：问题不能说有两个房间，句意不通。", "座位": "搭配：“座位”不与“这个问题有两个……”搭配，问题没有座位可数。"}, "sentence_index": 6, "correct_answer": "答案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们修好了新答案，准备出发。", "explanation": "这里应该用〈车〉。“答案”指对问题的解答，不能用“修好”来说；准备出发时要修好的是交通工具，应说“车”。"}, {"text": "这次旅行的答案很贵，花了两万块。", "explanation": "这里应该用〈费用〉。“答案”指对问题的解答，不能用“贵”来形容；旅行的花费要说“费用”。"}, {"text": "他是一个善良的答案。", "explanation": "这里应该用〈人〉。答案指问题的解答，不指人；形容善良的主体要用“人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找到了一只答案。", "corrected_sentence": "我找到了一个答案。", "error_description": "量词错误：“答案”的量词应为“个”，不说“只”（“只”多用于动物或成对的物件）。应说“我找到了一个答案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于找到着答案。", "corrected_sentence": "他终于找到了答案。", "error_description": "体标错误：“找到”表示动作已经完成，应用“了”，不说“找到着”。应说“他终于找到了答案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee6f3f6-09ef-4ab8-a313-672a51aeb997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
