INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13452, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "坚持不懈，不轻易改变目标或想法。", "primary_collocate": null, "pronunciation": "zhí zhuó", "ipa": "ʈʂɻ̩˧˥ ʈʂwo˧˥", "syllable_count": 2, "sentences": [{"text": "答案，或许就藏在对消费主义惯性的反思与对供应链正义的执着追求之中。", "target_word": "执着", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他对梦想非常执着。", "target_word": "执着", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她执着地寻找失散多年的哥哥。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做研究需要一种执着的精神。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他执着于自己的想法，谁的话也不听。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人几十年来一直执着地保护这片森林。", "target_word": "执着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对音乐的执着让大家很佩服。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很执着，一定要把这件事做完。", "target_word": "执着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正是因为执着，他才取得了成功。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都很佩服她执着的态度。", "target_word": "执着", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "执着地", "label": "状语形式"}, {"form": "执着的", "label": "定语形式"}, {"form": "执著", "label": "异体"}], "register": "中性", "sense_fingerprint": "对目标或想法坚持不懈、不轻易改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11fef44c-77a9-473d-bd53-ecd3ab0c912e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轻浮", "is_correct": false, "explanation": "语义：“轻浮”与“反思”“正义”的严肃语境不符，不能修饰“追求”。"}, {"text": "执着", "is_correct": true, "explanation": "正确。“执着”修饰“追求”，表示坚持不懈，与“反思”“正义”的语境相合。"}, {"text": "散漫", "is_correct": false, "explanation": "语义：“散漫”指不集中、不坚持，与“追求正义”的意思相矛盾。"}, {"text": "草率", "is_correct": false, "explanation": "搭配：“草率”多修饰决定、处理等，不说“草率的追求”。"}], "explanations": {"轻浮": "语义：“轻浮”与“反思”“正义”的严肃语境不符，不能修饰“追求”。", "执着": "正确。“执着”修饰“追求”，表示坚持不懈，与“反思”“正义”的语境相合。", "散漫": "语义：“散漫”指不集中、不坚持，与“追求正义”的意思相矛盾。", "草率": "搭配：“草率”多修饰决定、处理等，不说“草率的追求”。"}, "sentence_index": 0, "correct_answer": "执着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做事很执着，每件事都只做一半就丢下。", "explanation": "这里应该用〈三心二意〉。“执着”指坚持不放弃，与“每件事都只做一半就丢下”相矛盾；做事不专一应说“三心二意”。"}, {"text": "他的想法很执着，今天一个样，明天又一个样。", "explanation": "这里应该用〈善变〉。“执着”指不轻易改变想法，与“今天一个样，明天又一个样”的变化相矛盾。"}, {"text": "他做事很执着，三天就换了一份工作。", "explanation": "这里应该用〈浮躁〉。“执着”指坚持不放弃，与“三天就换了一份工作”相矛盾；做事没有耐心、坚持不下去，应说“浮躁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷淡", "is_correct": false, "explanation": "语义：对音乐冷淡不会让人佩服，与句子的赞赏语气矛盾。"}, {"text": "执着", "is_correct": true, "explanation": "正确。“执着”作定语，指对音乐的坚持，与“让大家很佩服”相合。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：懒散与“让大家很佩服”的赞赏相矛盾。"}, {"text": "随便", "is_correct": false, "explanation": "搭配：“对……的随便”不成立，不说“对音乐的随便”。"}], "explanations": {"冷淡": "语义：对音乐冷淡不会让人佩服，与句子的赞赏语气矛盾。", "执着": "正确。“执着”作定语，指对音乐的坚持，与“让大家很佩服”相合。", "懒散": "语义：懒散与“让大家很佩服”的赞赏相矛盾。", "随便": "搭配：“对……的随便”不成立，不说“对音乐的随便”。"}, "sentence_index": 6, "correct_answer": "执着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很执着，一会儿想学画画，一会儿又想学跳舞。", "explanation": "这里应该用〈善变〉。“执着”指不轻易改变目标，与“一会儿学画画，一会儿学跳舞”的反复相矛盾；此处应说“善变”。"}, {"text": "他很执着，对什么事都是一时兴起，过两天就忘了。", "explanation": "这里应该用〈浮躁〉。“执着”指坚持不放弃，与“一时兴起、过两天就忘了”的态度相矛盾；此处应说“浮躁”。"}, {"text": "他性格执着，一遇到困难就放弃。", "explanation": "这里应该用〈软弱〉。“执着”指坚持不放弃，与“一遇到困难就放弃”的态度相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他执着了坚持训练，从不间断。", "corrected_sentence": "他执着地坚持训练，从不间断。", "error_description": "状语标记错误：“执着”修饰动词作状语时要用“地”，不能用“了”。“执着了坚持”不通，应说“执着地坚持训练”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一种执着地精神，从不轻易放弃。", "corrected_sentence": "他有一种执着的精神，从不轻易放弃。", "error_description": "定语错误：“执着”修饰名词“精神”时要用“的”，不能用“地”。应说“执着的精神”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13457, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
