INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13457, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指体型微小的昆虫或其他节肢动物。", "primary_collocate": null, "pronunciation": "xiǎo chóng", "ipa": "ɕjɑʊ̯˨˩˦ ʈʂʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小鸟和小虫会来树上住。", "target_word": "小虫", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "叶子上有一只绿色的小虫。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟飞下来，吃了树上的小虫。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天晚上，灯旁边有很多小虫在飞。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在地上看到一条小虫，它慢慢地爬。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜叶上有小虫，妈妈洗了很久。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸡在地里找小虫吃。", "target_word": "小虫", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "花园里的小虫晚上会叫。", "target_word": "小虫", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用手轻轻把小虫放到草地上。", "target_word": "小虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们蹲在地上，看小虫搬东西。", "target_word": "小虫", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只小虫", "label": "量词（只）"}, {"form": "一条小虫", "label": "量词（条）"}, {"form": "小虫子", "label": "复合"}, {"form": "小蟲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "体型微小的昆虫或节肢动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9396a7ad-604e-4eae-9004-ebab4a4f74bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13457, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小虫", "is_correct": true, "explanation": "正确答案：小虫（xiǎo chóng），指体型微小的昆虫。"}, {"text": "小钟", "is_correct": false, "explanation": "chóng 与 zhōng 声母不同（ch 与 zh）且声调不同，意思是小钟（小型的钟）。"}, {"text": "小城", "is_correct": false, "explanation": "chóng 与 chéng 韵母不同（ong 与 eng），意思是小城（规模较小的城市）。"}, {"text": "小肠", "is_correct": false, "explanation": "chóng 与 cháng 韵母不同（ong 与 ang），意思是小肠（人体消化器官）。"}], "explanations": {"小虫": "正确答案：小虫（xiǎo chóng），指体型微小的昆虫。", "小钟": "chóng 与 zhōng 声母不同（ch 与 zh）且声调不同，意思是小钟（小型的钟）。", "小城": "chóng 与 chéng 韵母不同（ong 与 eng），意思是小城（规模较小的城市）。", "小肠": "chóng 与 cháng 韵母不同（ong 与 ang），意思是小肠（人体消化器官）。"}, "sentence_index": null, "correct_answer": "小虫"}, "level_3": {"options": [{"text": "小虫", "is_correct": true, "explanation": "正确答案：小虫，与“小鸟”并列，都是能住在树上的小生物。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象体型庞大，不能与小鸟并列住到树上。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是生物，不会来树上住。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“住”的主语应是生物，“汽车”不能说“来树上住”。"}], "explanations": {"小虫": "正确答案：小虫，与“小鸟”并列，都是能住在树上的小生物。", "大象": "体貌：大象体型庞大，不能与小鸟并列住到树上。", "石头": "语义：石头不是生物，不会来树上住。", "汽车": "搭配：“住”的主语应是生物，“汽车”不能说“来树上住”。"}, "sentence_index": 0, "correct_answer": "小虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子上停着一朵小虫。", "explanation": "这里应该用〈只〉。〈朵〉用于花，小虫应说“一只小虫”。"}, {"text": "草地上爬着一棵小虫。", "explanation": "这里应该用〈只〉。〈棵〉用于树和植物，小虫应说“一只小虫”。"}, {"text": "墙上趴着一头小虫。", "explanation": "这里应该用〈只〉。〈头〉用于牛、猪等大型牲畜，小虫应说“一只小虫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13457, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小虫", "is_correct": true, "explanation": "正确答案：小虫，是小鸡在地里找来吃的东西。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是食物，小鸡不会在地里找它来吃。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能吃，与“找……吃”的语义冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，“冰箱”不能与“吃”搭配。"}], "explanations": {"小虫": "正确答案：小虫，是小鸡在地里找来吃的东西。", "手机": "语义：手机不是食物，小鸡不会在地里找它来吃。", "电脑": "语义：电脑不能吃，与“找……吃”的语义冲突。", "冰箱": "搭配：“吃”的宾语应是食物，“冰箱”不能与“吃”搭配。"}, "sentence_index": 6, "correct_answer": "小虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小虫体型很大，像一头大象。", "explanation": "这里应该用〈大动物〉。小虫指体型微小的昆虫，不能说体型很大、像大象一样。"}, {"text": "这只小虫高得快碰到屋顶了。", "explanation": "这里应该用〈大树〉。小虫体型微小，不会高到碰屋顶，这样形容的是大树。"}, {"text": "这只小虫高得像一座塔。", "explanation": "这里应该用〈高楼〉。小虫体型微小，不能说高得像塔一样，高楼才这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13457, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "叶子下面藏着一块小虫。", "corrected_sentence": "叶子下面藏着一只小虫。", "error_description": "量词用错：“小虫”应说“一只小虫”，不能说“一块小虫”。“块”多用于成块的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13457, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "草地上爬着一张小虫。", "corrected_sentence": "草地上爬着一只小虫。", "error_description": "量词用错：“小虫”应说“一只小虫”，不能说“一张小虫”。“张”用于纸、桌子等平面的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13460, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "填土", "is_correct": true, "explanation": "正确：“填土”是把土填回去，与“挖土”的动作正相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：唱歌与挖土的动作没有相反关系。"}, {"text": "跑步", "is_correct": false, "explanation": "无反义关系：跑步与挖土不构成相反的动作。"}, {"text": "睡觉", "is_correct": false, "explanation": "无反义关系：睡觉与挖土不是相对的动作。"}], "correct_answer": "填土", "explanations": {"填土": "正确：“填土”是把土填回去，与“挖土”的动作正相反。", "唱歌": "无反义关系：唱歌与挖土的动作没有相反关系。", "跑步": "无反义关系：跑步与挖土不构成相反的动作。", "睡觉": "无反义关系：睡觉与挖土不是相对的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13460, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "填土", "is_correct": true, "explanation": "正确：“填土”是把土填回去，与“挖土”的动作相反。"}, {"text": "上课", "is_correct": false, "explanation": "无反义关系：上课与挖土没有相反的对应关系。"}, {"text": "爬山", "is_correct": false, "explanation": "无反义关系：爬山与挖土不是相对的动作。"}, {"text": "洗澡", "is_correct": false, "explanation": "无反义关系：洗澡与挖土不构成反义。"}], "correct_answer": "填土", "explanations": {"填土": "正确：“填土”是把土填回去，与“挖土”的动作相反。", "上课": "无反义关系：上课与挖土没有相反的对应关系。", "爬山": "无反义关系：爬山与挖土不是相对的动作。", "洗澡": "无反义关系：洗澡与挖土不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13460, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用工具或手把土从地面或地下取出。", "primary_collocate": null, "pronunciation": "wā tǔ", "ipa": "wa˥ tʰu˨˩", "syllable_count": 2, "sentences": [{"text": "大家挖土，放小树，浇水。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "爸爸在院子里挖土种花。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在路边挖土。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用小铲子挖土，不用手。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先挖土，再放种子。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在花园里挖土玩儿。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "挖土很累，他出了一身汗。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民伯伯早上五点就起床挖土。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来帮我挖土，好吗？", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要种树，先要挖土。", "target_word": "挖土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挖了土", "label": "体标"}, {"form": "挖过土", "label": "体标"}, {"form": "挖土机", "label": "复合"}], "register": "中性", "sense_fingerprint": "用工具或手把土取出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f270e504-0a47-4d31-b06d-9aa60be4a027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挖土", "is_correct": true, "explanation": "正确：“挖土”指用工具把土取出来，与后面的“放小树、浇水”构成种树的步骤。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与种树无关，句子讲的是园艺劳动的步骤。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”用于庄稼等成熟的作物，不能用在种树的准备步骤中。"}, {"text": "写字", "is_correct": false, "explanation": "语义：写字与园艺劳动不符，句子讲的是栽树前后的动作。"}], "explanations": {"挖土": "正确：“挖土”指用工具把土取出来，与后面的“放小树、浇水”构成种树的步骤。", "唱歌": "语义：唱歌与种树无关，句子讲的是园艺劳动的步骤。", "收割": "搭配：“收割”用于庄稼等成熟的作物，不能用在种树的准备步骤中。", "写字": "语义：写字与园艺劳动不符，句子讲的是栽树前后的动作。"}, "sentence_index": 0, "correct_answer": "挖土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最近总在背后挖土，大家都不爱跟他说话。", "explanation": "这里不能用〈挖土〉。挖土指用工具取出泥土，不能表示说别人的坏话，那要用〈说坏话〉。"}, {"text": "他在暗地里挖土，想让我们公司倒闭。", "explanation": "这里不能用〈挖土〉。挖土是用工具取土，不能表示暗中破坏别人，那要用〈挖墙脚〉。"}, {"text": "他最近很爱挖土，什么事都要打听一下。", "explanation": "这里不能用〈挖土〉。挖土指取出泥土，不能表示打听消息，那要用〈打听〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挖土", "is_correct": true, "explanation": "正确：“挖土”是体力劳动，做起来会累、出汗，与句意相符。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：下棋不耗费体力，一般不会出一身汗，与“很累，出了一身汗”不符。"}, {"text": "看书", "is_correct": false, "explanation": "语义：看书不会让人出一身汗，与句中的劳累不相称。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”需要宾语，不能单独作“很累”的主语。"}], "explanations": {"挖土": "正确：“挖土”是体力劳动，做起来会累、出汗，与句意相符。", "下棋": "语义：下棋不耗费体力，一般不会出一身汗，与“很累，出了一身汗”不符。", "看书": "语义：看书不会让人出一身汗，与句中的劳累不相称。", "喝": "配价：“喝”需要宾语，不能单独作“很累”的主语。"}, "sentence_index": 6, "correct_answer": "挖土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在公司里挖土，想把同事都挤走。", "explanation": "这里不能用〈挖土〉。挖土指取出泥土，不能表示排挤别人，那要用〈排挤〉。"}, {"text": "他最近在挖土，想提高自己的成绩。", "explanation": "这里不能用〈挖土〉。挖土只指取出泥土的劳动，不能表示学习或考试的结果。"}, {"text": "孩子们在教室里挖土背课文。", "explanation": "这里不能用〈挖土〉。挖土是劳动动作，不能用来表示背诵课文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天了挖土，种了一棵树。", "corrected_sentence": "他昨天挖了土，种了一棵树。", "error_description": "了的位置错误：「了」不能放在动词「挖」前面，应放在「挖」和「土」中间，说「挖了土」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前挖土过，所以知道很累。", "corrected_sentence": "我们以前挖过土，所以知道很累。", "error_description": "过的位置错误：「挖土」是动宾结构，「过」要放在「挖」和「土」中间，应说「挖过土」，不能放在词末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
