INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13461, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指幼小的树木，通常高度和粗细都较小。", "primary_collocate": null, "pronunciation": "xiǎo shù", "ipa": "ɕjɑʊ˨˩˦ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "大家挖土，放小树，浇水。", "target_word": "小树", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "小树慢慢长大，我们会很开心。", "target_word": "小树", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "院子里有一棵小树。", "target_word": "小树", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "风一吹，小树就摇来摇去。", "target_word": "小树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，小树长出了新叶子。", "target_word": "小树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸给小树绑了一根木棍。", "target_word": "小树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这棵小树是去年种的。", "target_word": "小树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，小树变得更绿了。", "target_word": "小树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每天放学都去看看小树。", "target_word": "小树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小树旁边有一只小鸟。", "target_word": "小树", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "小樹", "label": "繁体"}], "register": "中性", "sense_fingerprint": "幼小的树木", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f270e504-0a47-4d31-b06d-9aa60be4a027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13461, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小树", "is_correct": true, "explanation": "正确答案：小树，指幼小的树木。"}, {"text": "小暑", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是二十四节气之一的小暑。"}, {"text": "小叔", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是父亲的弟弟。"}, {"text": "小鼠", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是小老鼠。"}, {"text": "小书", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是小本的书。"}], "explanations": {"小树": "正确答案：小树，指幼小的树木。", "小暑": "shǔ（第三声）与 shù（第四声）声调不同，意思是二十四节气之一的小暑。", "小叔": "shū（第一声）与 shù（第四声）声调不同，意思是父亲的弟弟。", "小鼠": "shǔ（第三声）与 shù（第四声）声调不同，意思是小老鼠。", "小书": "shū（第一声）与 shù（第四声）声调不同，意思是小本的书。"}, "sentence_index": null, "correct_answer": "小树"}, "level_3": {"options": [{"text": "小树", "is_correct": true, "explanation": "正确：“小树”是要放进土里种的幼树，与“挖土、浇水”的园艺步骤相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不能种进土里，与园艺步骤无关。"}, {"text": "老师", "is_correct": false, "explanation": "配价：“放”的宾语应是物品，不能是人。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是要种进土里的东西，与句意不符。"}], "explanations": {"小树": "正确：“小树”是要放进土里种的幼树，与“挖土、浇水”的园艺步骤相符。", "书包": "语义：书包不能种进土里，与园艺步骤无关。", "老师": "配价：“放”的宾语应是物品，不能是人。", "电脑": "语义：电脑不是要种进土里的东西，与句意不符。"}, "sentence_index": 0, "correct_answer": "小树"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小树底下好乘凉。", "explanation": "这里应该用〈大树〉。“大树底下好乘凉”的大树枝叶茂密、能遮阴，小树树冠小，遮不住阴，不能说“小树底下好乘凉”。"}, {"text": "那棵小树已经长成了参天大树，高过了房顶。", "explanation": "这里应该用〈大树〉。“小树”指幼小、还没长大的树，已经长成参天大树就不能再叫小树。"}, {"text": "这棵小树的树冠大得能遮住整个操场。", "explanation": "这里应该用〈大树〉。小树还没长大，树冠很小，遮不住整个操场，树冠这么大的只能是大树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13461, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小树", "is_correct": true, "explanation": "正确：“这棵小树”指一棵幼小的树，与“去年种的”相符。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“棵”用于植物，不能用来数书。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是种的，与“去年种的”不符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是种出来的，与句意不符。"}], "explanations": {"小树": "正确：“这棵小树”指一棵幼小的树，与“去年种的”相符。", "书": "搭配：“棵”用于植物，不能用来数书。", "汽车": "语义：汽车不是种的，与“去年种的”不符。", "房子": "语义：房子不是种出来的，与句意不符。"}, "sentence_index": 6, "correct_answer": "小树"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵小树粗得要两个人才能抱住。", "explanation": "这里应该用〈老树〉。小树的粗细通常较小，粗得要两人合抱不符合“小树”的意思。"}, {"text": "我家门口有一棵小树，已经高得能碰到二楼的窗户了。", "explanation": "这里应该用〈大树〉。小树还没长大，不会高到够着二楼窗户，这样的高度应说〈大树〉。"}, {"text": "这家超市每天卖很多新鲜的小树，给顾客炒菜吃。", "explanation": "这里应该用〈蔬菜〉。小树是树，不是食材，不能拿来卖或炒着吃，应说〈蔬菜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13461, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口的花坛旁边种着一只小树。", "corrected_sentence": "门口的花坛旁边种着一棵小树。", "error_description": "量词错误：树要用“棵”，应说“一棵小树”，“只”用于动物等，不能用来数树。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13461, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟在河边种了一棵很小树。", "corrected_sentence": "弟弟在河边种了一棵小树。", "error_description": "多出了“很”：“一棵小树”中“小”直接修饰名词，不能加“很”；要说“很小的树”才能加“很”，“一棵很小树”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
