INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13468, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "随身拿着或提着东西去某个地方", "primary_collocate": null, "pronunciation": "dài", "ipa": "tai˥˩", "syllable_count": 1, "sentences": [{"text": "出门别忘了带伞。", "target_word": "带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今天没带手机。", "target_word": "带", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她带着一个大书包去学校。", "target_word": "带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请带好你的身份证。", "target_word": "带", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "旅行时我带过很多衣服。", "target_word": "带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你带钱了吗？", "target_word": "带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天都带午饭去公司。", "target_word": "带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，你带雨伞没有？", "target_word": "带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去海边玩，要带帽子和水。", "target_word": "带", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把水果带到了办公室。", "target_word": "带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带着", "label": "着体标"}, {"form": "带过", "label": "过体标"}, {"form": "带了", "label": "了体标"}, {"form": "帶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "随身拿着东西去某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616a40b2-ff1d-4894-b98c-a82aa79ff0f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13468, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带", "is_correct": true, "explanation": "带（dài）即本词，意为随身拿着东西去某处。"}, {"text": "太", "is_correct": false, "explanation": "tài 与 dài 声母不同（t/d），意思是太，是副词。"}, {"text": "大", "is_correct": false, "explanation": "dà 与 dài 韵母不同（a/ai），声调相同，意思是大。"}, {"text": "呆", "is_correct": false, "explanation": "dāi（第一声）与 dài（第四声）声调不同，意思是呆。"}], "explanations": {"带": "带（dài）即本词，意为随身拿着东西去某处。", "太": "tài 与 dài 声母不同（t/d），意思是太，是副词。", "大": "dà 与 dài 韵母不同（a/ai），声调相同，意思是大。", "呆": "dāi（第一声）与 dài（第四声）声调不同，意思是呆。"}, "sentence_index": null, "correct_answer": "带"}, "level_3": {"options": [{"text": "带", "is_correct": true, "explanation": "带：出门时随身拿着伞，与“出门别忘了”相合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”配衣物，不能说“穿伞”。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与“别忘了”要随身拿着伞的意思相反。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指吹气，与“伞”搭配不通，句子不成立。"}], "explanations": {"带": "带：出门时随身拿着伞，与“出门别忘了”相合。", "穿": "搭配：“穿”配衣物，不能说“穿伞”。", "扔": "语义：“扔”是丢弃，与“别忘了”要随身拿着伞的意思相反。", "吹": "语义：“吹”指吹气，与“伞”搭配不通，句子不成立。"}, "sentence_index": 0, "correct_answer": "带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把钥匙带在了桌子上。", "explanation": "这里应该用“放”。“带”表示随身拿着或提着东西去某个地方，不表示把东西放在某处。"}, {"text": "妈妈把外套带在了墙上。", "explanation": "这里应该用“挂”。“带”表示随身拿着或提着东西去某个地方，不能表示把衣服挂在墙上。"}, {"text": "她把花带在了花瓶里。", "explanation": "这里应该用“插”。“带”表示随身拿着或提着东西去某个地方，不能表示把花插进瓶中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13468, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "带", "is_correct": true, "explanation": "带（dài）即本词，意为随身拿着东西去某处。"}, {"text": "耐", "is_correct": false, "explanation": "nài 与 dài 声母不同（n/d），意思是耐，即忍耐。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 dài 声母不同（b/d），意思是拜，如拜访。"}, {"text": "蛋", "is_correct": false, "explanation": "dàn 与 dài 韵母不同（an/ai），声调相同，意思是蛋。"}], "explanations": {"带": "带（dài）即本词，意为随身拿着东西去某处。", "耐": "nài 与 dài 声母不同（n/d），意思是耐，即忍耐。", "拜": "bài 与 dài 声母不同（b/d），意思是拜，如拜访。", "蛋": "dàn 与 dài 韵母不同（an/ai），声调相同，意思是蛋。"}, "sentence_index": null, "correct_answer": "带"}, "level_3": {"options": [{"text": "带", "is_correct": true, "explanation": "带：随身拿着午饭去公司，与“每天都”和“去公司”相合。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”指悬挂，不能说“挂午饭”。"}, {"text": "锁", "is_correct": false, "explanation": "语义：“锁”指上锁，与带着午饭去公司的意思不符。"}, {"text": "磨", "is_correct": false, "explanation": "语义：“磨”指研磨，与午饭随身携带无关，句子不通。"}], "explanations": {"带": "带：随身拿着午饭去公司，与“每天都”和“去公司”相合。", "挂": "搭配：“挂”指悬挂，不能说“挂午饭”。", "锁": "语义：“锁”指上锁，与带着午饭去公司的意思不符。", "磨": "语义：“磨”指研磨，与午饭随身携带无关，句子不通。"}, "sentence_index": 6, "correct_answer": "带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请把桌子带干净。", "explanation": "这里应该用“擦”。“带”表示随身拿着或提着东西去某个地方，没有“擦拭”的意思，“擦干净”不能说成“带干净”。"}, {"text": "他在纸上带了一幅画。", "explanation": "这里应该用“画”。“带”表示随身拿着或提着东西去某个地方，不能表示在纸上作画。"}, {"text": "她把碗带干净了。", "explanation": "这里应该用“洗”。“带”表示随身拿着或提着东西去某个地方，没有“清洗”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他带着了两把伞去了办公室。", "corrected_sentence": "他带着两把伞去了办公室。", "error_description": "体标错误：“带着”之后不能再加“了”，着与了不能叠用，应删去“了”；正确形式是“他带着两把伞去了办公室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈正在带过两把伞出门。", "corrected_sentence": "妈妈正在带两把伞出门。", "error_description": "体标错误：“过”表示曾有过的经历，不能与“正在”所表示的进行中动作连用，应删去“过”；正确形式是“妈妈正在带两把伞出门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
