INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13469, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指幼小的树木，通常用于比喻孩子或新生事物。", "primary_collocate": null, "pronunciation": "xiǎo shù miáo", "ipa": "ɕiau˨˩˦ ʂu˥˩ miau˧˥", "syllable_count": 3, "sentences": [{"text": "每天早上，人们带着小树苗和水桶来到公园，挖坑、种树、浇水。", "target_word": "小树苗", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "院子里有一棵小树苗。", "target_word": "小树苗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小树苗需要多浇水。", "target_word": "小树苗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在门口种了一棵小树苗。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风很大，小树苗站不稳。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天来了，小树苗长出新叶子。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们像小树苗一样慢慢长大。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们给小树苗搭了一个架子。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些小树苗是学校送给我们的。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下了雨，小树苗长得很快。", "target_word": "小树苗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "小樹苗", "label": "繁体"}], "register": "中性", "sense_fingerprint": "幼小的树，也比喻孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616a40b2-ff1d-4894-b98c-a82aa79ff0f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13469, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小树苗", "is_correct": true, "explanation": "小树苗：幼小的树，正是挖坑、种树、浇水的对象。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴与“挖坑、种树、浇水”的情境完全不符，句子不通。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球与“挖坑、种树、浇水”的情境不符，句子不通。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：“挖坑、种树”的对象是植物，不能与小猫搭配。"}], "explanations": {"小树苗": "小树苗：幼小的树，正是挖坑、种树、浇水的对象。", "钢琴": "语义：钢琴与“挖坑、种树、浇水”的情境完全不符，句子不通。", "篮球": "语义：篮球与“挖坑、种树、浇水”的情境不符，句子不通。", "小猫": "搭配：“挖坑、种树”的对象是植物，不能与小猫搭配。"}, "sentence_index": 0, "correct_answer": "小树苗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "池塘里放了一批小树苗。", "explanation": "这里应该用“鱼苗”。“小树苗”指树木的幼苗，不能用来指鱼苗。"}, {"text": "农场里有一窝小树苗。", "explanation": "这里应该用“猪仔”。“小树苗”指树木的幼苗，不能用来指猪仔等动物。"}, {"text": "这位老教授已经是一棵小树苗了。", "explanation": "这里应该用“老前辈”。“小树苗”只指幼小的树木，比喻幼小、新生的事物，不能用来形容年长的老教授。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13469, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小树苗", "is_correct": true, "explanation": "小树苗：幼小的树，比喻慢慢长大的孩子，与“慢慢长大”相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会长大，与“慢慢长大”的意思矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“长大”用于生命体，不能说电脑“长大”。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“长大”用于生命体，不能说钢笔“长大”。"}], "explanations": {"小树苗": "小树苗：幼小的树，比喻慢慢长大的孩子，与“慢慢长大”相合。", "石头": "语义：石头不会长大，与“慢慢长大”的意思矛盾。", "电脑": "搭配：“长大”用于生命体，不能说电脑“长大”。", "钢笔": "搭配：“长大”用于生命体，不能说钢笔“长大”。"}, "sentence_index": 6, "correct_answer": "小树苗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鸡妈妈带着一群小树苗在院子里找虫子吃。", "explanation": "这里应该用“小鸡”。“小树苗”指幼小的树木，不能用来指小鸡等动物。"}, {"text": "厨房里放着一盘小树苗。", "explanation": "这里应该用“豆芽”。“小树苗”指树木的幼苗，不能用来指豆芽这类蔬菜。"}, {"text": "院子里那棵大树其实是一棵小树苗。", "explanation": "这里应该用“老树”。“小树苗”指幼小的树，不能用来形容已经长成的大树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在院子里种了一只小树苗。", "corrected_sentence": "我们在院子里种了一棵小树苗。", "error_description": "错误形式是“一只小树苗”，“只”用于动物；正确形式是“一棵小树苗”，树苗应用量词“棵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在花园里栽了三头小树苗。", "corrected_sentence": "妈妈在花园里栽了三棵小树苗。", "error_description": "错误形式是“三头小树苗”，“头”多用于牲畜；正确形式是“三棵小树苗”，树苗应用量词“棵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
