INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13474, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "树木是木本植物的总称，包括各种乔木、灌木和木质藤本植物。", "primary_collocate": null, "pronunciation": "shù mù", "ipa": "ʂu˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "树木可以净化空气，减少噪音，还能帮助小动物和小鸟找到家。", "target_word": "树木", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "山上有很多高大的树木。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，树木都变绿了。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里的树木长得很好。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大风把一些树木吹倒了。", "target_word": "树木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该保护城市里的树木。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天，树木的叶子慢慢变黄。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河边种着很多树木，夏天很凉快。", "target_word": "树木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去认识不同的树木。", "target_word": "树木", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下大雪以后，树木上都是白色的雪。", "target_word": "树木", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "木本植物的总称，泛指各种树", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7aa7a4f-1236-4805-b7d4-46fc3a94a1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "树木", "is_correct": true, "explanation": "正确：“树木”作主语，能净化空气、帮助小动物，符合句意。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：“钢铁”是金属，不能净化空气，也帮不了小动物。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”没有生命，不能净化空气或帮助小鸟找家。"}, {"text": "公路", "is_correct": false, "explanation": "配价：“净化”“帮助”需要能动的主语，公路做主语不成立。"}], "explanations": {"树木": "正确：“树木”作主语，能净化空气、帮助小动物，符合句意。", "钢铁": "语义：“钢铁”是金属，不能净化空气，也帮不了小动物。", "石头": "语义：“石头”没有生命，不能净化空气或帮助小鸟找家。", "公路": "配价：“净化”“帮助”需要能动的主语，公路做主语不成立。"}, "sentence_index": 0, "correct_answer": "树木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们院子里有一棵树木。", "explanation": "这里应该用〈树〉。“树木”是总称，不能用量词“棵”计数，单株的树应说“一棵树”。"}, {"text": "这张桌子是用树木做的。", "explanation": "这里应该用〈木头〉。“树木”指长在地上的植物，做家具的材料要说“木头”。"}, {"text": "小羊在草地上吃树木。", "explanation": "这里应该用〈青草〉或〈树叶〉。“树木”指整棵植物，不能说“吃树木”，羊吃的是草或树叶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "树木", "is_correct": true, "explanation": "正确：“树木的叶子”指树的叶子会在秋天变黄，符合句意。"}, {"text": "房屋", "is_correct": false, "explanation": "语义：“房屋”不是植物，没有叶子，句子不成立。"}, {"text": "河水", "is_correct": false, "explanation": "语义：“河水”是液体，不会长叶子，句子矛盾。"}, {"text": "砖块", "is_correct": false, "explanation": "搭配：“叶子”只和植物搭配，不说“砖块的叶子”。"}], "explanations": {"树木": "正确：“树木的叶子”指树的叶子会在秋天变黄，符合句意。", "房屋": "语义：“房屋”不是植物，没有叶子，句子不成立。", "河水": "语义：“河水”是液体，不会长叶子，句子矛盾。", "砖块": "搭配：“叶子”只和植物搭配，不说“砖块的叶子”。"}, "sentence_index": 6, "correct_answer": "树木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把树木钉在墙上。", "explanation": "这里应该用〈木板〉。“树木”是长在地上的植物，不能钉在墙上，钉的是木板。"}, {"text": "奶奶每天去山上捡树木当柴火。", "explanation": "这里应该用〈树枝〉。“树木”指整棵植物，捡来当柴火的是树枝。"}, {"text": "秋天，树木一片片地落下来。", "explanation": "这里应该用〈树叶〉。一片片落下来的是树叶，“树木”是整棵植物，不会这样落下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些树木们都长得很高。", "corrected_sentence": "这些树木都长得很高。", "error_description": "错误：“树木们”；正确：“树木”。“树木”本身已经是总称，不能再加“们”表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台风把路边的树木倒吹了。", "corrected_sentence": "台风把路边的树木吹倒了。", "error_description": "错误：“倒吹了”；正确：“吹倒了”。结果补语“倒”要紧跟动词“吹”之后，不能放在“吹”前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
