INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13475, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "噪音指杂乱刺耳、影响正常生活或工作的声音。", "primary_collocate": null, "pronunciation": "zào yīn", "ipa": "tsɑʊ˥˩ in˥", "syllable_count": 2, "sentences": [{"text": "树木可以净化空气，减少噪音，还能帮助小动物和小鸟找到家。", "target_word": "噪音", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "马路上的噪音太大，我睡不着。", "target_word": "噪音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工地的噪音影响了附近的居民。", "target_word": "噪音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请关上窗户，外面有噪音。", "target_word": "噪音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器的噪音很小。", "target_word": "噪音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在机场附近，每天都能听到噪音。", "target_word": "噪音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间听噪音对耳朵不好。", "target_word": "噪音", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他戴着耳机，听不到周围的噪音。", "target_word": "噪音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边在修路，上课时噪音很大。", "target_word": "噪音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上请不要制造噪音，邻居要休息。", "target_word": "噪音", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一阵噪音", "label": "量词"}], "register": "中性", "sense_fingerprint": "杂乱刺耳、影响生活或工作的声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7aa7a4f-1236-4805-b7d4-46fc3a94a1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13475, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "噪音", "is_correct": true, "explanation": "正确：“减少噪音”是常见说法，噪音是要减少的对象。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“减少”用于数量或噪音、污染等，颜色不能说“减少”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高一般不说“减少”，与句中环境语境也不合，句子读来不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不能被“减少”，句子读来不通。"}], "explanations": {"噪音": "正确：“减少噪音”是常见说法，噪音是要减少的对象。", "颜色": "搭配：“减少”用于数量或噪音、污染等，颜色不能说“减少”。", "身高": "搭配：身高一般不说“减少”，与句中环境语境也不合，句子读来不通。", "年龄": "语义：年龄不能被“减少”，句子读来不通。"}, "sentence_index": 0, "correct_answer": "噪音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的噪音很好听。", "explanation": "这里应该用〈声音〉。噪音指杂乱刺耳、让人不舒服的声音，不能用来形容好听的歌。"}, {"text": "医生说我的心脏有噪音。", "explanation": "这里应该用〈杂音〉。噪音指环境或设备发出的刺耳声响，心脏的异常声音在医学上要说杂音。"}, {"text": "门口传来清脆的噪音。", "explanation": "这里应该用〈响声〉。噪音指刺耳的杂音，清脆悦耳的声响不能称作噪音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13475, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "噪音", "is_correct": true, "explanation": "正确：“听噪音”指听到让人不舒服的声音，句中是说长时间听这种声音对耳朵不好。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“听”的对象是声音，不能说“听味道”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不能被“听”，句子读来不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“听”不能与“空气”搭配，长时间听空气的说法不成立。"}], "explanations": {"噪音": "正确：“听噪音”指听到让人不舒服的声音，句中是说长时间听这种声音对耳朵不好。", "味道": "搭配：“听”的对象是声音，不能说“听味道”。", "温度": "语义：温度不能被“听”，句子读来不通。", "空气": "搭配：“听”不能与“空气”搭配，长时间听空气的说法不成立。"}, "sentence_index": 6, "correct_answer": "噪音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们唱着欢快的噪音。", "explanation": "这里应该用〈歌声〉。噪音指刺耳杂乱的声音，不能形容欢快的歌唱。"}, {"text": "小狗发出了可爱的噪音。", "explanation": "这里应该用〈叫声〉。噪音令人不适，不能形容可爱的叫声。"}, {"text": "林子里传来婉转的噪音。", "explanation": "这里应该用〈鸟鸣〉。噪音指让人不舒服的声音，不能用来形容婉转悦耳的鸟鸣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13475, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工地上传来一把噪音。", "corrected_sentence": "工地上传来一阵噪音。", "error_description": "量词错误：“把”用于有柄的器物，噪音应用“阵”计量，应说“一阵噪音”，不能说“一把噪音”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13475, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里，楼上传来一阵的噪音。", "corrected_sentence": "夜里，楼上传来一阵噪音。", "error_description": "数量结构错误：“一阵”修饰“噪音”时不能加“的”，应说“一阵噪音”，不能说“一阵的噪音”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
