INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13478, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指个人或群体居住、生活的地方，常带有感情色彩。", "primary_collocate": null, "pronunciation": "jiā yuán", "ipa": "tɕia˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这个项目叫“绿色家园”，是一个本地行动的好例子。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "战争让很多人离开了自己的家园。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要一起保护美丽的家园。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外工作，但常常想念家园。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，人们开始重新建设家园。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球是我们共同的家园。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用画笔画出心中的家园。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了守住家园，村民们不怕辛苦。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌唱出了人们对家园的感情。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在这里住了一辈子，不愿离开家园。", "target_word": "家园", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家園", "label": "繁体"}], "register": "中性", "sense_fingerprint": "带有感情的居住和生活之地，如故乡、共同的栖息地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7aa7a4f-1236-4805-b7d4-46fc3a94a1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家园", "is_correct": true, "explanation": "正确：指带有感情色彩的居住和生活之地，与“绿色行动的项目”相符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是物理量，不能作项目名称，句子说的是一个项目。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是人的生理指标，不能作为项目名称的一部分，与“绿色行动的项目”不合。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种病，不会用来给环保行动项目命名。"}], "explanations": {"家园": "正确：指带有感情色彩的居住和生活之地，与“绿色行动的项目”相符。", "温度": "语义：温度是物理量，不能作项目名称，句子说的是一个项目。", "体温": "语义：体温是人的生理指标，不能作为项目名称的一部分，与“绿色行动的项目”不合。", "感冒": "语义：感冒是一种病，不会用来给环保行动项目命名。"}, "sentence_index": 0, "correct_answer": "家园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在国外的家园很便宜，他买了很多。", "explanation": "这里应用〈房子〉。“家园”指有感情色彩的居住之地，不能当作可以买卖的房屋，应说〈房子〉。"}, {"text": "他每天开车时把家园放在包里带着。", "explanation": "这里应用〈钥匙〉。“家园”是居住生活之地，不是能放进包里的小东西。"}, {"text": "他每天吃完饭就去家园上班。", "explanation": "搭配：这里应用〈公司〉。“家园”指居住生活之地，不是工作场所，不能说“去家园上班”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家园", "is_correct": true, "explanation": "正确：指有感情的居住之地，可以被画在画里，与“心中的”搭配。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不是可以用画笔画出来的具体事物。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种病，不是心中美好的地方，不能这样画出来。"}, {"text": "利息", "is_correct": false, "explanation": "语义：利息是银行里的钱数，不是心中的地方，与句意不合。"}], "explanations": {"家园": "正确：指有感情的居住之地，可以被画在画里，与“心中的”搭配。", "数学": "语义：数学是学科，不是可以用画笔画出来的具体事物。", "感冒": "语义：感冒是一种病，不是心中美好的地方，不能这样画出来。", "利息": "语义：利息是银行里的钱数，不是心中的地方，与句意不合。"}, "sentence_index": 6, "correct_answer": "家园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人在这里住了一辈子，每天在家园里开飞机。", "explanation": "这里应用〈机场〉。“家园”是居住之地，不是开飞机的场所，应说“在机场开飞机”。"}, {"text": "老人在这里住了一辈子，每天在家园里参加奥运会比赛。", "explanation": "这里应用〈体育场〉。“家园”是居住之地，不能举办比赛，应说“在体育场比赛”。"}, {"text": "老人在这里住了一辈子，每天在家园里指挥交响乐团。", "explanation": "这里应用〈音乐厅〉。“指挥交响乐团”需要在音乐厅进行，“家园”不是演出场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们失去了一只家园。", "corrected_sentence": "他们失去了一片家园。", "error_description": "量词错误：“家园”应配“片”或“个”，“只”用于动物或成对的东西。正确形式：一片家园。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些家园们都很干净。", "corrected_sentence": "这些家园都很干净。", "error_description": "词缀错误：“家园”是无生命名词，前面已有“这些”表复数，不能再加“们”。正确形式：这些家园都很干净。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
