INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13481, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指童年时期，幼年的时候。", "primary_collocate": null, "pronunciation": "xiǎo shí hou", "ipa": "ɕjɑʊ˨˩˦ ʂɻ̩˧˥ xoʊ", "syllable_count": 3, "sentences": [{"text": "有一位老人说：“我小时候这里有很多树，现在我们正在把绿色还给城市。”", "target_word": "小时候", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "小时候，我最喜欢和奶奶一起睡。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候住在一个小村子里。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候不爱吃青菜。", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候的朋友，现在还常常联系。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我小时候很爱哭。", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候，每个周末爸爸都带我去公园。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你小时候想当什么？", "target_word": "小时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我小时候学过画画，现在都忘了。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候家里很穷，但是我们很开心。", "target_word": "小时候", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小時候", "label": "繁体"}], "register": "中性", "sense_fingerprint": "童年、幼年的时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b265e353-0a56-4f5b-a790-095a42c113c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13481, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小时候", "is_correct": true, "explanation": "正确。“小时候”指童年，与后文“现在”形成对照，符合句意。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“这里有很多树”这种过去的情况矛盾。"}, {"text": "刚才", "is_correct": false, "explanation": "搭配：“刚才”只指不久前的一段时间，不能与“有很多树”这种长期存在的状态搭配。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”指一周内的时间，不能表示过去长时间里这里一直有很多树。"}], "explanations": {"小时候": "正确。“小时候”指童年，与后文“现在”形成对照，符合句意。", "明天": "语义：“明天”指将来，与“这里有很多树”这种过去的情况矛盾。", "刚才": "搭配：“刚才”只指不久前的一段时间，不能与“有很多树”这种长期存在的状态搭配。", "上周": "语义：“上周”指一周内的时间，不能表示过去长时间里这里一直有很多树。"}, "sentence_index": 0, "correct_answer": "小时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我小时候在北京上过大学。", "explanation": "这里应该用〈以前〉。“小时候”只指童年，不能指成年后上大学的经历；“以前”可泛指任何过去的时期。"}, {"text": "你等我小时候，我就回来。", "explanation": "“小时候”指童年，不表示一小段时间。这句把它当成了“很快”的意思，与句意不符。"}, {"text": "我小时候明年要去北京。", "explanation": "这里应该用〈以后〉。小时候只指过去的童年，不能指将来；〈以后〉才泛指将来的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13481, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小时候", "is_correct": true, "explanation": "正确。“小时候”指童年，与“我”的年龄和“爸爸带我去公园”的情境相符。"}, {"text": "深夜", "is_correct": false, "explanation": "搭配：“深夜”指一个具体的夜间时段，不能与“每个周末”的习惯性时间搭配。"}, {"text": "春节", "is_correct": false, "explanation": "语义：“春节”是一年一次的节日，不能说每个周末都发生。"}, {"text": "那个星期天", "is_correct": false, "explanation": "语义：“那个星期天”指某一个特定的日子，与“每个周末”的反复性矛盾。"}], "explanations": {"小时候": "正确。“小时候”指童年，与“我”的年龄和“爸爸带我去公园”的情境相符。", "深夜": "搭配：“深夜”指一个具体的夜间时段，不能与“每个周末”的习惯性时间搭配。", "春节": "语义：“春节”是一年一次的节日，不能说每个周末都发生。", "那个星期天": "语义：“那个星期天”指某一个特定的日子，与“每个周末”的反复性矛盾。"}, "sentence_index": 6, "correct_answer": "小时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小时候是我最好的朋友。", "explanation": "这里问题在词义：“小时候”是时间，指不了人，不能作“朋友”。应说“我小时候的朋友是我最好的朋友”，用“小时候”修饰人。"}, {"text": "妈妈把小时候搬到了厨房。", "explanation": "这里应该用〈玩具〉之类的具体物品。〈小时候〉表示时间，不能被“搬”，应说“妈妈把玩具搬到了厨房”。"}, {"text": "我们吃完饭，小时候就去睡觉了。", "explanation": "这里应该用〈随后〉。〈小时候〉指童年，不能指刚吃完饭之后的当下时刻，时间与前后文冲突；〈随后〉才表示紧接着的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候了住在乡下。", "corrected_sentence": "我小时候住在乡下。", "error_description": "“小时候”后面不能直接接“了”，“了”应去掉；正确说法是“我小时候住在乡下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候的很爱笑。", "corrected_sentence": "我小时候很爱笑。", "error_description": "“小时候”后面不能加“的”再接副词“很”，“的”应去掉；正确说法是“我小时候很爱笑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13482, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13482, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13482, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指将原本属于别人的东西或地方归还给对方。", "primary_collocate": null, "pronunciation": "huán gěi", "ipa": "xwan˧˥ kei˨˩˦", "syllable_count": 2, "sentences": [{"text": "有一位老人说：“我小时候这里有很多树，现在我们正在把绿色还给城市。”", "target_word": "还给", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "请把这本书还给图书馆。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把借来的钱还给了朋友。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把作业还给了我们。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我借的那本字典，下周一定要还给老师。", "target_word": "还给", "complexity_tier": "T3", "furigana": "wǒ jiè de nà běn zì diǎn , xià zhōu yí dìng yào huán gěi lǎo shī 。", "sentence_source": "generated"}, {"text": "我们要把安静还给这座老城。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把捡到的手机还给了失主。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你明天把雨伞还给我。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把借来的椅子还给了学校。", "target_word": "还给", "complexity_tier": "T3", "furigana": "tā men bǎ jiè lái de yǐ zi huán gěi le xué xiào 。", "sentence_source": "generated"}, {"text": "她想把自由还给那只小鸟。", "target_word": "还给", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "还给了", "label": "体标"}, {"form": "还给过", "label": "体标"}, {"form": "還給", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把原本属于别人的东西或地方归还给对方，也可用于抽象事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b265e353-0a56-4f5b-a790-095a42c113c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还给", "is_correct": true, "explanation": "正确。“还给”表示把原属城市的绿色归还给城市，与“小时候这里有很多树”相呼应。"}, {"text": "卖给", "is_correct": false, "explanation": "语义：“卖给”是出售，与绿色原本属于城市、需要归还的语义相反。"}, {"text": "借给", "is_correct": false, "explanation": "语义：“借给”是暂时借出，与“还”所表示的最终归还不符。"}, {"text": "送出", "is_correct": false, "explanation": "配价：“送出”的方向是离开城市，不能接“城市”作为归还的对象。"}], "explanations": {"还给": "正确。“还给”表示把原属城市的绿色归还给城市，与“小时候这里有很多树”相呼应。", "卖给": "语义：“卖给”是出售，与绿色原本属于城市、需要归还的语义相反。", "借给": "语义：“借给”是暂时借出，与“还”所表示的最终归还不符。", "送出": "配价：“送出”的方向是离开城市，不能接“城市”作为归还的对象。"}, "sentence_index": 0, "correct_answer": "还给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把亲手做的饼干还给了妈妈。", "explanation": "这里应该用〈送给〉。还给表示归还原本属于对方的东西；饼干是我亲手做的，妈妈从未拥有过，应说“送给妈妈”。"}, {"text": "他把刚买的新自行车还给了邻居。", "explanation": "这里应该用〈送给〉。还给要求东西原属对方；这辆车是他刚买的，邻居从未拥有过，应说“送给邻居”。"}, {"text": "我把旧衣服还给了孤儿院。", "explanation": "这里应该用〈捐给〉。还给要求东西原属对方；旧衣服是捐给孤儿院的，应说“捐给孤儿院”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还给", "is_correct": true, "explanation": "正确。“还给”表示把捡到的失物归还给原主，与“捡到的手机”“失主”相符。"}, {"text": "租给", "is_correct": false, "explanation": "语义：“租给”是收费让别人使用，手机本来就是失主的，捡到的人只能归还，不能“租给”失主。"}, {"text": "抢走", "is_correct": false, "explanation": "语义：“抢走”表示强行夺取，与把捡到的手机归还原主的善意语境相反，且“抢走了失主”不成立。"}, {"text": "卖掉", "is_correct": false, "explanation": "语义：“卖掉”是出售处理，不能带“失主”作对象，也与归还原主的语境矛盾。"}], "explanations": {"还给": "正确。“还给”表示把捡到的失物归还给原主，与“捡到的手机”“失主”相符。", "租给": "语义：“租给”是收费让别人使用，手机本来就是失主的，捡到的人只能归还，不能“租给”失主。", "抢走": "语义：“抢走”表示强行夺取，与把捡到的手机归还原主的善意语境相反，且“抢走了失主”不成立。", "卖掉": "语义：“卖掉”是出售处理，不能带“失主”作对象，也与归还原主的语境矛盾。"}, "sentence_index": 6, "correct_answer": "还给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她想把新买的小米还给那只小鸟。", "explanation": "这里应该用〈喂给〉。还给要求东西原属对方；小米是刚买的，小鸟从未拥有过，应说“喂给小鸟”。"}, {"text": "她想把这把伞还给那只小鸟。", "explanation": "这里应该用〈送给〉。还给要求东西原属对方，小鸟从未拥有过这把伞，应说“送给小鸟”。"}, {"text": "她想把自己新买的房子还给学生。", "explanation": "这里应该用〈出租给〉。还给要求东西原属对方；房子是她自己新买的，学生从未拥有过，应说“出租给学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天伞还给你。", "corrected_sentence": "我明天把伞还给你。", "error_description": "“还给”带受事宾语时，宾语前要用“把”引出；漏掉“把”的“伞还给你”不成立，应说“我明天把伞还给你”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没把那本字典还给了老师。", "corrected_sentence": "我没把那本字典还给老师。", "error_description": "否定词“没”与表示完成的“了”不能同时使用：用“没”否定“还给”时要去掉“了”，应说“我没把那本字典还给老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16256cec-15a1-403b-9109-3d87ce25d820') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13484, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13484, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13484, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人或集体能够产生的作用或影响", "primary_collocate": null, "pronunciation": "lì liàng", "ipa": "li˥˩ liɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "虽然一个人的力量很小，但是大家一起努力，就能带来大的改变。", "target_word": "力量", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "团结起来，我们的力量就大了。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都可以为社会贡献一份力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的力量不大，不能做这么大的事。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青年人是国家发展的重要力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者的力量帮了很多人。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用自己的力量改变这个小城市。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的力量合在一起，问题很快解决了。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小小的团队也有改变世界的力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别小看孩子，他们也是一支重要的力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股", "label": "量词"}, {"form": "一支", "label": "量词"}], "register": "中性", "sense_fingerprint": "个人或集体能产生的作用和影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e62f285c-3fff-4d83-96f3-aac2e819e030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "力量", "is_correct": true, "explanation": "正确。力量指个人或集体能产生的作用，与“大家一起努力”“带来大的改变”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，不能产生作用，不能带来改变。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状是外观，不能带来大的改变。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”不能与“带来大的改变”搭配，它不表示能产生的作用。"}], "explanations": {"力量": "正确。力量指个人或集体能产生的作用，与“大家一起努力”“带来大的改变”相合。", "颜色": "语义：颜色是视觉属性，不能产生作用，不能带来改变。", "形状": "语义：形状是外观，不能带来大的改变。", "体重": "搭配：“体重”不能与“带来大的改变”搭配，它不表示能产生的作用。"}, "sentence_index": 0, "correct_answer": "力量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的力量很多，十个部门都有人。", "explanation": "这里应该用〈人手〉。“力量”不能用“很多”来形容人员数量，说人手多要用“人手”。"}, {"text": "这台机器的力量很快，一天能做三千个零件。", "explanation": "这里应该用〈效率〉。「力量」指作用或影响，不能用「快」来形容；机器工作的快慢要说「效率」。"}, {"text": "这些志愿者是一把重要的力量。", "explanation": "这里应该用〈支〉。“把”用于有柄的器具，指一群人组成的力量要说“一支力量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力量", "is_correct": true, "explanation": "正确。这里指个人能产生的作用，可以用来改变城市。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指岁数，不能用来改变城市。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指身体的高矮，不能用来改变城市。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“用……改变城市”不说“用体积”，体积不能作为改变的手段。"}], "explanations": {"力量": "正确。这里指个人能产生的作用，可以用来改变城市。", "年龄": "语义：年龄指岁数，不能用来改变城市。", "身高": "语义：身高指身体的高矮，不能用来改变城市。", "体积": "搭配：“用……改变城市”不说“用体积”，体积不能作为改变的手段。"}, "sentence_index": 6, "correct_answer": "力量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次活动的力量很多，两百人都来了。", "explanation": "这里应该用〈人数〉。“力量”不能用“很多”来计数人，说人多要用“人数”。"}, {"text": "这条河的力量有几百公里。", "explanation": "这里应该用〈长度〉。“力量”指作用或影响，不能用来说河的长短；说河有多长要用“长度”。"}, {"text": "这群年轻人是一块重要的力量。", "explanation": "这里应该用〈支〉。“块”多用于片状或块状的东西，指一群人组成的力量要说“一支力量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动汇聚了一只强大的力量。", "corrected_sentence": "这次活动汇聚了一股强大的力量。", "error_description": "量词错误：“力量”应搭配“股”或“种”，“只”用于动物或成对的东西，不能修饰力量。正确说法是“一股强大的力量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们用自己力量解决了问题。", "corrected_sentence": "他们用自己的力量解决了问题。", "error_description": "错误在于“力量”前的修饰成分漏了“的”。正确说法是“自己的力量”，代词修饰名词时要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b6fc027-c13c-4674-a693-301e756e4da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "很大", "is_correct": true, "explanation": "正确：“大”与“小”互为反义，“影响力很小”的反义是“影响力很大”。"}, {"text": "漂亮", "is_correct": false, "explanation": "无反义关系：“漂亮”形容外貌，与影响力无关。"}, {"text": "热情", "is_correct": false, "explanation": "无反义关系：“热情”形容态度，与影响力的大小无关。"}, {"text": "快速", "is_correct": false, "explanation": "无反义关系：“快速”形容速度，与影响力的大小无关。"}], "correct_answer": "很大", "explanations": {"很大": "正确：“大”与“小”互为反义，“影响力很小”的反义是“影响力很大”。", "漂亮": "无反义关系：“漂亮”形容外貌，与影响力无关。", "热情": "无反义关系：“热情”形容态度，与影响力的大小无关。", "快速": "无反义关系：“快速”形容速度，与影响力的大小无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "大", "is_correct": true, "explanation": "正确：“大”与“小”互为反义，“作用很小”的反义是“作用很大”，这里取“大”。"}, {"text": "活泼", "is_correct": false, "explanation": "无反义关系：“活泼”形容性格或动作，与作用大小无关。"}, {"text": "友好", "is_correct": false, "explanation": "无反义关系：“友好”形容关系或态度，与作用大小无关。"}, {"text": "整齐", "is_correct": false, "explanation": "无反义关系：“整齐”形容排列或状态，与作用大小无关。"}], "correct_answer": "大", "explanations": {"大": "正确：“大”与“小”互为反义，“作用很小”的反义是“作用很大”，这里取“大”。", "活泼": "无反义关系：“活泼”形容性格或动作，与作用大小无关。", "友好": "无反义关系：“友好”形容关系或态度，与作用大小无关。", "整齐": "无反义关系：“整齐”形容排列或状态，与作用大小无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示力量或作用微弱，不足以产生明显影响", "primary_collocate": null, "pronunciation": "hěn xiǎo", "ipa": "xən˨˩ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "虽然一个人的力量很小，但是大家一起努力，就能带来大的改变。", "target_word": "很小", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这点雨对河水的影响很小，水位没有变化。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一杯水的作用很小，火还是没有灭。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是新人，在公司的影响力很小。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药的效果很小，吃了也没有用。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很小，树叶几乎不动。", "target_word": "很小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛我的作用很小，主要靠队友。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法的帮助很小，问题还在。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的力气很小，推不开这扇门。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人的努力作用很小，所以我们要合作。", "target_word": "很小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "力量、作用或影响微弱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9d64f7-d6db-410b-8410-52799dc0c108') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "很小", "is_correct": true, "explanation": "正确答案：很小（hěn xiǎo），形容力量或作用微弱。"}, {"text": "很想", "is_correct": false, "explanation": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“非常想念”。"}, {"text": "很响", "is_correct": false, "explanation": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“声音大”。"}, {"text": "很险", "is_correct": false, "explanation": "xiǎn 与 xiǎo 只差韵母（an 与 ao），意思是“情况危险”。"}], "explanations": {"很小": "正确答案：很小（hěn xiǎo），形容力量或作用微弱。", "很想": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“非常想念”。", "很响": "xiǎng 与 xiǎo 只差韵母（ang 与 ao），意思是“声音大”。", "很险": "xiǎn 与 xiǎo 只差韵母（an 与 ao），意思是“情况危险”。"}, "sentence_index": null, "correct_answer": "很小"}, "level_3": {"options": [{"text": "很小", "is_correct": true, "explanation": "正确：“很小”与“虽然……但是……”的让步关系相符，说明个人力量弱。"}, {"text": "很干净", "is_correct": false, "explanation": "语义：“力量”不能用“干净”来描述。"}, {"text": "很热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不能修饰“力量”。"}, {"text": "很清楚", "is_correct": false, "explanation": "搭配：“清楚”说明是否明白或可见，不用来说力量的状态。"}], "explanations": {"很小": "正确：“很小”与“虽然……但是……”的让步关系相符，说明个人力量弱。", "很干净": "语义：“力量”不能用“干净”来描述。", "很热闹": "搭配：“热闹”形容场面或气氛，不能修饰“力量”。", "很清楚": "搭配：“清楚”说明是否明白或可见，不用来说力量的状态。"}, "sentence_index": 0, "correct_answer": "很小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的价格很小，学生也买得起。", "explanation": "〈很低〉。说价格的高低要用“很低”，“很小”不用于形容价格。"}, {"text": "他的汉语很小，老师都夸他。", "explanation": "〈很流利〉。说语言水平要用“很流利”，“很小”不用于形容汉语。"}, {"text": "现在已经很小了，大家该回家了。", "explanation": "〈很晚〉。说时间的早晚要用“很晚”，“很小”不用于表示时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很小", "is_correct": true, "explanation": "正确：“很小”与“主要靠队友”相合，说明我个人的作用不大。"}, {"text": "很甜", "is_correct": false, "explanation": "语义：“作用”不能用味道来形容。"}, {"text": "很安静", "is_correct": false, "explanation": "搭配：“安静”不能修饰“作用”。"}, {"text": "很热情", "is_correct": false, "explanation": "语义：“热情”描写人的态度，不能修饰“作用”。"}], "explanations": {"很小": "正确：“很小”与“主要靠队友”相合，说明我个人的作用不大。", "很甜": "语义：“作用”不能用味道来形容。", "很安静": "搭配：“安静”不能修饰“作用”。", "很热情": "语义：“热情”描写人的态度，不能修饰“作用”。"}, "sentence_index": 6, "correct_answer": "很小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试很小，大家都没考好。", "explanation": "〈很难〉。说考试的难度要用“很难”，“很小”不用于形容考试。"}, {"text": "他的成绩很小，每次考试都是第一名。", "explanation": "〈很好〉。说成绩好坏要用“很好”，“很小”不用于形容成绩。"}, {"text": "这件事他做得很小，老板很满意。", "explanation": "〈很好〉。说事情做得好坏要用“很好”，“很小”不用于评价做事的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的一句话作用很很小，没人在意。", "corrected_sentence": "他的一句话作用很小，没人在意。", "error_description": "错误：“很很小”。正确：“很小”。程度副词“很”不能重叠使用，应只用一个“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13485, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这点帮助很小小的，问题还没解决。", "corrected_sentence": "这点帮助很小，问题还没解决。", "error_description": "错误：“很小小的”。正确：“很小”。“很”与重叠形式“小小的”不能同时用，应去掉“小的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99a869e5-d7c6-4cee-bf7b-58b3f659b231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
