INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13487, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13487, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "种植树木，即在土地上栽种树苗。", "primary_collocate": null, "pronunciation": "zhí shù", "ipa": "ʈʂɨ˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "植树", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个植树项目告诉我们，保护地球可以从身边的小事做起。", "target_word": "植树", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "春天来了，学校组织同学们去河边植树。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷每年春天都在山坡上植树。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植树的时候，我负责挖坑，哥哥负责浇水。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天我们在公园植树，大家都很开心。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植树可以让空气变得更干净。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们去年在村子后面植树，现在树已经长高了。", "target_word": "植树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植树前，老师给每个人发了一棵树苗。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我想和朋友一起去植树。", "target_word": "植树", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "植了树", "label": "体标（了）"}, {"form": "植过树", "label": "体标（过）"}, {"form": "植树节", "label": "复合"}], "register": "中性", "sense_fingerprint": "植树：把树苗栽种到土地里的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31956932-1185-4de5-add8-d2c55acac8f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13487, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "植树", "is_correct": true, "explanation": "植树（zhí shù）：把树苗栽种到土地里，即本题目标词。"}, {"text": "直属", "is_correct": false, "explanation": "直属（zhí shǔ）第二个音节的声调不同：shǔ 为第三声，shù 为第四声，意思是直接隶属。"}, {"text": "植物", "is_correct": false, "explanation": "植物（zhí wù）第二个音节的声母不同：w 与 sh 不同，意思是生物的一类。"}, {"text": "指数", "is_correct": false, "explanation": "指数（zhǐ shù）第一个音节的声调不同：zhǐ 为第三声，zhí 为第二声，意思是表示变化程度的数值。"}], "explanations": {"植树": "植树（zhí shù）：把树苗栽种到土地里，即本题目标词。", "直属": "直属（zhí shǔ）第二个音节的声调不同：shǔ 为第三声，shù 为第四声，意思是直接隶属。", "植物": "植物（zhí wù）第二个音节的声母不同：w 与 sh 不同，意思是生物的一类。", "指数": "指数（zhǐ shù）第一个音节的声调不同：zhǐ 为第三声，zhí 为第二声，意思是表示变化程度的数值。"}, "sentence_index": null, "correct_answer": "植树"}, "level_3": {"options": [{"text": "植树", "is_correct": true, "explanation": "植树：把树苗栽种到土里，与“季节性任务”和“树苗存活率”的语境一致。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是人的本能，不能被视为季节性任务，与后文记录树苗存活率的语境冲突。"}, {"text": "尊重", "is_correct": false, "explanation": "搭配：“尊重”指对人或规则的态度，与“季节性任务”的常规搭配不符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病不是可以安排的任务，与句中“持续性的本地行动”的语义相反。"}], "explanations": {"植树": "植树：把树苗栽种到土里，与“季节性任务”和“树苗存活率”的语境一致。", "呼吸": "语义：呼吸是人的本能，不能被视为季节性任务，与后文记录树苗存活率的语境冲突。", "尊重": "搭配：“尊重”指对人或规则的态度，与“季节性任务”的常规搭配不符。", "生病": "语义：生病不是可以安排的任务，与句中“持续性的本地行动”的语义相反。"}, "sentence_index": 0, "correct_answer": "植树"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "园丁把修剪下来的枝条拿去植树。", "explanation": "这里应该用〈扦插〉。扦插是把枝条插入土中繁殖，植树指栽种树苗，不用于枝条。"}, {"text": "这些花，我打算在院子里植树。", "explanation": "这里应该用〈栽〉。植树指栽种树木，这些是花卉，应该说栽花，不能用植树。"}, {"text": "妈妈每天在厨房里植树。", "explanation": "植树需要在土地上栽种树苗，厨房里不能植树，这里应该用〈做饭〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13487, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "植树", "is_correct": true, "explanation": "植树（zhí shù）：把树苗栽种到土地里，即本题目标词。"}, {"text": "职务", "is_correct": false, "explanation": "职务（zhí wù）第二个音节的声母不同：w 与 sh 不同，意思是工作中的职位和责任。"}, {"text": "执事", "is_correct": false, "explanation": "执事（zhí shì）第二个音节的韵母不同：shì 为 i 韵，shù 为 u 韵，意思是负责办事的人。"}, {"text": "植株", "is_correct": false, "explanation": "植株（zhí zhū）第二个音节的声母不同：zh 与 sh 不同，意思是植物体（一棵植物）。"}], "explanations": {"植树": "植树（zhí shù）：把树苗栽种到土地里，即本题目标词。", "职务": "职务（zhí wù）第二个音节的声母不同：w 与 sh 不同，意思是工作中的职位和责任。", "执事": "执事（zhí shì）第二个音节的韵母不同：shì 为 i 韵，shù 为 u 韵，意思是负责办事的人。", "植株": "植株（zhí zhū）第二个音节的声母不同：zh 与 sh 不同，意思是植物体（一棵植物）。"}, "sentence_index": null, "correct_answer": "植树"}, "level_3": {"options": [{"text": "植树", "is_correct": true, "explanation": "正确：植树能增加树木、净化空气，与“可以让空气变得更干净”相合。"}, {"text": "吸烟", "is_correct": false, "explanation": "语义：吸烟会污染空气，与“更干净”的结果相反。"}, {"text": "烧纸", "is_correct": false, "explanation": "语义：烧纸会产生烟尘，与“让空气变得更干净”的语境冲突。"}, {"text": "购买", "is_correct": false, "explanation": "语义：购买是买东西的行为，“购买可以让空气变得更干净”说不通，与语境无关。"}], "explanations": {"植树": "正确：植树能增加树木、净化空气，与“可以让空气变得更干净”相合。", "吸烟": "语义：吸烟会污染空气，与“更干净”的结果相反。", "烧纸": "语义：烧纸会产生烟尘，与“让空气变得更干净”的语境冲突。", "购买": "语义：购买是买东西的行为，“购买可以让空气变得更干净”说不通，与语境无关。"}, "sentence_index": 6, "correct_answer": "植树"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小麦在田里植树。", "explanation": "这里应该用〈生长〉。植树的施动者是人，指人栽种树木；小麦是农作物，不能植树，应该说小麦在生长。"}, {"text": "他的心脏每天都在植树。", "explanation": "这里应该用〈跳动〉。植树是人在土地上栽种树木的动作，心脏只能跳动，不能植树。"}, {"text": "这张桌子每天都在植树。", "explanation": "这里应该用〈放〉或〈摆〉。植树的施动者是人，桌子是家具，不能植树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天到了，我们把山坡上植树。", "corrected_sentence": "春天到了，我们在山坡上植树。", "error_description": "误用“把”字句。“把”后的宾语应是被处置的事物，这里却接了地点“山坡上”；地点应改用介词“在”引出，应为“在山坡上植树”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年秋天，我们了植树。", "corrected_sentence": "去年秋天，我们植了树。", "error_description": "完成标记“了”应紧跟动词之后。错误形式把“了”放在“植树”之前，应为“植了树”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
