INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13489, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "长时间遭受、忍受（痛苦、困难等）。", "primary_collocate": null, "pronunciation": "bǎo shòu", "ipa": "pɑʊ˨˩˦ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "在华北平原一个曾饱受风沙侵袭的边缘村落，一场由村民自发组织的生态复兴运动正悄然重塑着人与土地的关系。", "target_word": "饱受", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老人多年来饱受病痛的折磨。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地区长年饱受干旱之苦。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在马路边的人饱受噪音之苦。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家饱受战争之苦。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候饱受欺凌，所以很少说话。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河曾经饱受污染，现在又干净了。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民们饱受虫害，一年只收了一点粮食。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她饱受失眠困扰，每天都很累。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座古城饱受风雨的侵蚀。", "target_word": "饱受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飽受", "label": "繁体"}, {"form": "饱受着", "label": "体标"}, {"form": "饱受过", "label": "体标"}], "register": "书面", "sense_fingerprint": "长时间遭受痛苦、灾害或困难的折磨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c74c4ae1-9515-4459-b540-8770b8d0940f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13489, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饱受", "is_correct": true, "explanation": "饱受表示长时间遭受痛苦或困难，与“风沙侵袭”的负面含义相合。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指愉快地享用，风沙侵袭不能被享受。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象须是值得赏玩的事物，不能说欣赏风沙侵袭。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”表示欢迎到来的人或事，与“侵袭”的破坏性含义相悖。"}], "explanations": {"饱受": "饱受表示长时间遭受痛苦或困难，与“风沙侵袭”的负面含义相合。", "享受": "语义：“享受”指愉快地享用，风沙侵袭不能被享受。", "欣赏": "搭配：“欣赏”的对象须是值得赏玩的事物，不能说欣赏风沙侵袭。", "迎接": "语义：“迎接”表示欢迎到来的人或事，与“侵袭”的破坏性含义相悖。"}, "sentence_index": 0, "correct_answer": "饱受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在公园里饱受快乐的时光。", "explanation": "这里应该用〈享受〉。饱受只用于长时间遭受痛苦或困难，不能用于快乐的时光；享受快乐的时光才对。"}, {"text": "我们班饱受了三名新同学。", "explanation": "这里应该用〈迎来〉。饱受的对象是痛苦或困难，不表示人员增加；迎来三名新同学才对。"}, {"text": "这个月我的体重饱受了三公斤。", "explanation": "这里应该用〈增加〉。饱受表示遭受痛苦，不表示数量上升；体重增加三公斤才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13489, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饱受", "is_correct": true, "explanation": "饱受表示长时间遭受，与“污染”的负面含义相合。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”表示为喜事而欢庆，与污染不相容。"}, {"text": "享有", "is_correct": false, "explanation": "语义：“享有”的宾语是权利、名誉等，不能是污染。"}, {"text": "观赏", "is_correct": false, "explanation": "搭配：“观赏”的对象是景物，不能说观赏污染。"}], "explanations": {"饱受": "饱受表示长时间遭受，与“污染”的负面含义相合。", "庆祝": "语义：“庆祝”表示为喜事而欢庆，与污染不相容。", "享有": "语义：“享有”的宾语是权利、名誉等，不能是污染。", "观赏": "搭配：“观赏”的对象是景物，不能说观赏污染。"}, "sentence_index": 6, "correct_answer": "饱受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店饱受顾客的信任。", "explanation": "这里应该用〈赢得〉。饱受用于遭受痛苦、困难，不用于好的评价；赢得顾客的信任才对。"}, {"text": "学校饱受了一批奖学金。", "explanation": "这里应该用〈获得〉。饱受表示遭受不好的事，奖学金是好事；学校获得一批奖学金才对。"}, {"text": "我饱受了一封朋友的来信。", "explanation": "这里应该用〈收到〉。饱受表示遭受，不用于收信；我收到一封朋友的来信才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村子里的孩子们长期饱受饥饿苦。", "corrected_sentence": "村子里的孩子们长期饱受饥饿之苦。", "error_description": "“饱受”的宾语要用固定说法“……之苦”，漏掉“之”不自然。应改为“饱受饥饿之苦”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座小镇多年来被饱受洪水之苦。", "corrected_sentence": "这座小镇多年来饱受洪水之苦。", "error_description": "错误：“饱受”本身已表示遭受，前面不能再加“被”。应说“这座小镇多年来饱受洪水之苦。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指风和被风吹起的沙土，常形容天气恶劣，也比喻艰难的环境。", "primary_collocate": null, "pronunciation": "fēng shā", "ipa": "fɤŋ˥ ʂa˥", "syllable_count": 2, "sentences": [{"text": "在华北平原一个曾饱受风沙侵袭的边缘村落，一场由村民自发组织的生态复兴运动正悄然重塑着人与土地的关系。", "target_word": "风沙", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "春天北方常有风沙，出门要戴口罩。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在风沙里走了一整天。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的风沙很大，树都长不高。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了挡住风沙，村民在村外种了很多树。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他这些年在外经历过不少风沙，什么苦都吃过。", "target_word": "风沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠边的小城常有风沙，人们都很习惯。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风沙过后，街上的车都变黄了。", "target_word": "风沙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说，再大的风沙，也挡不住回家的路。", "target_word": "风沙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在治理风沙，希望天空变得更蓝。", "target_word": "风沙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场风沙", "label": "量词"}, {"form": "一阵风沙", "label": "量词"}, {"form": "風沙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "风与被风吹起的沙土；恶劣天气，也比喻艰难处境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a99ff1f-84fe-4580-9f45-814e6a0bd5f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风沙", "is_correct": true, "explanation": "风沙指被风吹起的沙土，“饱受风沙侵袭”说村落长期遭受风沙危害，句意通顺。"}, {"text": "掌声", "is_correct": false, "explanation": "语义：掌声是赞扬的声音，不是能侵袭村落的东西，“饱受掌声侵袭”说不通。"}, {"text": "嘴皮子", "is_correct": false, "explanation": "语域：“嘴皮子”是口语说法，与这段书面描述的语体不合，而且不能用来“侵袭”村落。"}, {"text": "收成", "is_correct": false, "explanation": "搭配：“侵袭”的施事多是风沙、洪水之类的灾害，“收成”是结果，不能充当施事，“饱受收成侵袭”说不通。"}], "explanations": {"风沙": "风沙指被风吹起的沙土，“饱受风沙侵袭”说村落长期遭受风沙危害，句意通顺。", "掌声": "语义：掌声是赞扬的声音，不是能侵袭村落的东西，“饱受掌声侵袭”说不通。", "嘴皮子": "语域：“嘴皮子”是口语说法，与这段书面描述的语体不合，而且不能用来“侵袭”村落。", "收成": "搭配：“侵袭”的施事多是风沙、洪水之类的灾害，“收成”是结果，不能充当施事，“饱受收成侵袭”说不通。"}, "sentence_index": 0, "correct_answer": "风沙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一只风沙吹进了屋里，桌上全是沙子。", "explanation": "这里量词用错。〈只〉多用于动物或成对物品中的一个，风沙是成片吹来的天气现象，应该用〈阵〉或〈场〉。"}, {"text": "一颗风沙打在脸上，很疼。", "explanation": "这里量词用错。〈颗〉用于颗粒状的小东西，风沙应该用〈阵〉或〈股〉。"}, {"text": "工人买了两车风沙来盖房子。", "explanation": "这里应该用〈沙子〉。风沙是风和被风吹起的沙土，是一种天气现象，不能当建筑材料买来盖房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风沙", "is_correct": true, "explanation": "风沙指被风吹起的沙土，“沙漠边的小城常有风沙，人们都很习惯”符合常识，句意通顺。"}, {"text": "海浪", "is_correct": false, "explanation": "搭配：“常有”后接的自然现象要和沙漠环境相配，沙漠边的小城不会常有海浪。"}, {"text": "荷花", "is_correct": false, "explanation": "语义：荷花生长在水中，沙漠边的小城不可能常有荷花，句意说不通。"}, {"text": "雪崩", "is_correct": false, "explanation": "语义：雪崩出现在雪山地区，与沙漠环境完全不符，句子不成立。"}], "explanations": {"风沙": "风沙指被风吹起的沙土，“沙漠边的小城常有风沙，人们都很习惯”符合常识，句意通顺。", "海浪": "搭配：“常有”后接的自然现象要和沙漠环境相配，沙漠边的小城不会常有海浪。", "荷花": "语义：荷花生长在水中，沙漠边的小城不可能常有荷花，句意说不通。", "雪崩": "语义：雪崩出现在雪山地区，与沙漠环境完全不符，句子不成立。"}, "sentence_index": 6, "correct_answer": "风沙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏天的风沙很凉快，大家都在院子里乘凉。", "explanation": "这里应该用〈海风〉。海风带来凉爽，风沙裹着沙土，只会让人觉得干燥和呛人，不能说凉快。"}, {"text": "这场风沙来得正好，庄稼都绿了。", "explanation": "这里应该用〈春雨〉。庄稼变绿是春雨滋润的结果，风沙只带沙土，只会伤害庄稼。"}, {"text": "远处刮来一根风沙，打在脸上很疼。", "explanation": "这里量词用错。〈根〉用于细长的东西，风沙应该用〈阵〉或〈股〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天刮了一个风沙，学校的操场上全是沙子。", "corrected_sentence": "昨天刮了一场风沙，学校的操场上全是沙子。", "error_description": "量词错误：“风沙”的正确说法是“一场风沙”或“一阵风沙”，说成“一个风沙”是错的。“个”不能用来计量风沙这类天气现象，应该用“场”或“阵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "傍晚起了一扇风沙，我们只好待在屋里。", "corrected_sentence": "傍晚起了一阵风沙，我们只好待在屋里。", "error_description": "量词错误：“风沙”应说“一阵风沙”，说成“一扇风沙”是错的。“扇”用于门窗之类的东西，不能计量风沙，正确的量词是“阵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13491, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13491, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13491, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "突然进攻或危害，让人或事物受到破坏或影响。", "primary_collocate": null, "pronunciation": "qīn xí", "ipa": "tɕʰin˥ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "在华北平原一个曾饱受风沙侵袭的边缘村落，一场由村民自发组织的生态复兴运动正悄然重塑着人与土地的关系。", "target_word": "侵袭", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "台风侵袭了南方沿海的小城。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "寒流侵袭北方，气温一下子降了十度。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暴雨侵袭这座城市，街上全是水。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病毒侵袭身体时，人会发烧。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的房子常年受到海风侵袭。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洪水侵袭村子的那天晚上，大家都没睡。", "target_word": "侵袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防止虫子侵袭，农民在田里喷了药。", "target_word": "侵袭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪侵袭山区，路上的车都停下来了。", "target_word": "侵袭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙尘暴侵袭这个地区时，天空一片黄色。", "target_word": "侵袭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "侵袭了", "label": "体标"}, {"form": "侵袭着", "label": "体标"}, {"form": "侵袭过", "label": "体标"}, {"form": "侵襲", "label": "繁体"}], "register": "书面", "sense_fingerprint": "灾害、寒潮、病毒等突然来犯并造成破坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a99ff1f-84fe-4580-9f45-814e6a0bd5f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13491, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "侵袭", "is_correct": true, "explanation": "侵袭指突然来犯并造成破坏，“饱受风沙侵袭的村落”说村落长期遭受风沙危害，句意通顺。"}, {"text": "滋润", "is_correct": false, "explanation": "语义：“饱受”后接的应是负面遭遇，“滋润”是正面的好处，与句意矛盾。"}, {"text": "庇护", "is_correct": false, "explanation": "语义：风沙是危害，村落不会被风沙“庇护”，这个说法与句子的意思相反。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”是使事物变美的积极行为，“饱受”后要接遭受的危害，风沙也不会去装饰村落，句意说不通。"}], "explanations": {"侵袭": "侵袭指突然来犯并造成破坏，“饱受风沙侵袭的村落”说村落长期遭受风沙危害，句意通顺。", "滋润": "语义：“饱受”后接的应是负面遭遇，“滋润”是正面的好处，与句意矛盾。", "庇护": "语义：风沙是危害，村落不会被风沙“庇护”，这个说法与句子的意思相反。", "装饰": "语义：“装饰”是使事物变美的积极行为，“饱受”后要接遭受的危害，风沙也不会去装饰村落，句意说不通。"}, "sentence_index": 0, "correct_answer": "侵袭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有人侵袭了他的隐私，他很生气。", "explanation": "这里应该用〈侵犯〉。侵袭多指灾害、病菌突然来袭造成损害，隐私是个人权利，要说“侵犯”。"}, {"text": "这篇文章侵袭了他的观点，大家都不同意。", "explanation": "这里应该用〈攻击〉。侵袭不用于言论和观点，批驳别人的观点要说“攻击”。"}, {"text": "他侵袭了桌上的蛋糕，很快就吃光了。", "explanation": "这里应该用〈吃〉。侵袭指突然进攻或危害，让事物受到破坏，吃东西不是侵害，不能说侵袭蛋糕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13491, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "侵袭", "is_correct": true, "explanation": "侵袭指突然来犯并造成破坏，“洪水侵袭村子的那天晚上”说洪水来袭村子，句意通顺。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：照顾的对象是需要关照的人，洪水不会照顾村子，句意说不通。"}, {"text": "关心", "is_correct": false, "explanation": "语义：关心需要有感情的主体，洪水没有感情，不能关心村子。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”要求有意愿的人做主语，洪水不能欢迎村子。"}], "explanations": {"侵袭": "侵袭指突然来犯并造成破坏，“洪水侵袭村子的那天晚上”说洪水来袭村子，句意通顺。", "照顾": "语义：照顾的对象是需要关照的人，洪水不会照顾村子，句意说不通。", "关心": "语义：关心需要有感情的主体，洪水没有感情，不能关心村子。", "欢迎": "配价：“欢迎”要求有意愿的人做主语，洪水不能欢迎村子。"}, "sentence_index": 6, "correct_answer": "侵袭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他侵袭了朋友的感情，朋友很伤心。", "explanation": "这里应该用〈欺骗〉。侵袭不用于人对人的感情伤害，欺骗别人的感情要说“欺骗”。"}, {"text": "他侵袭了别人的作品，被大家批评了。", "explanation": "这里应该用〈抄袭〉。侵袭不用于窃取他人作品，把别人的作品当成自己的要说“抄袭”。"}, {"text": "同学们侵袭了他的口音，他很难过。", "explanation": "这里应该用〈嘲笑〉。侵袭不用于言语上的取笑，拿别人的口音开玩笑要说“嘲笑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年夏天，台风侵袭的我们的小区。", "corrected_sentence": "去年夏天，台风侵袭了我们的小区。", "error_description": "助词误用：动态助词“了”误作结构助词“的”，应说“台风侵袭了我们的小区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一场大雨侵袭得城北的村子。", "corrected_sentence": "一场大雨侵袭了城北的村子。", "error_description": "结构错误：“侵袭”带宾语时，完成的动作应用动词后的“了”，不能用“得”直接接宾语，应说“一场大雨侵袭了城北的村子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
