INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13492, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指物体或区域靠近外侧界限的部分。", "primary_collocate": null, "pronunciation": "biān yuán", "ipa": "pjɛn˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "在华北平原一个曾饱受风沙侵袭的边缘村落，一场由村民自发组织的生态复兴运动正悄然重塑着人与土地的关系。", "target_word": "边缘", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他坐在桌子的边缘，半个身子都在外面。", "target_word": "边缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心别走到悬崖边缘。", "target_word": "边缘", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "杯子放在桌子边缘，很容易掉下来。", "target_word": "边缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的学校在城市的边缘，离市中心很远。", "target_word": "边缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林边缘的树很少，再往外就是草地。", "target_word": "边缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把船划到湖的边缘，停了下来。", "target_word": "边缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸的边缘有一点破。", "target_word": "边缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙漠的边缘开始有一些草。", "target_word": "边缘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图的边缘有一圈蓝线。", "target_word": "边缘", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "边缘地带", "label": "复合"}, {"form": "邊緣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体或区域靠近外侧界限的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a99ff1f-84fe-4580-9f45-814e6a0bd5f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "边缘", "is_correct": true, "explanation": "“边缘”指靠近外侧界限的部分，修饰“村落”，与“华北平原”“风沙侵袭”的外围位置语境相合。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“眼睛”是身体器官，不能用来修饰“村落”，搭配不通。"}, {"text": "首都", "is_correct": false, "explanation": "语义：“首都”是国家的政治中心，与“村落”这种乡村聚居点的所指相矛盾。"}, {"text": "宫殿", "is_correct": false, "explanation": "语义：“宫殿”指帝王的居所，并非村落，与句中描述的村庄不相符。"}], "explanations": {"边缘": "“边缘”指靠近外侧界限的部分，修饰“村落”，与“华北平原”“风沙侵袭”的外围位置语境相合。", "眼睛": "搭配：“眼睛”是身体器官，不能用来修饰“村落”，搭配不通。", "首都": "语义：“首都”是国家的政治中心，与“村落”这种乡村聚居点的所指相矛盾。", "宫殿": "语义：“宫殿”指帝王的居所，并非村落，与句中描述的村庄不相符。"}, "sentence_index": 0, "correct_answer": "边缘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他坐在会议室的边缘正中央，是全场的焦点。", "explanation": "此处应该用〈中央〉。“边缘”指最外侧的部分，与“正中央”“全场的焦点”的位置相矛盾。"}, {"text": "这项技术是公司业务的边缘，却是最核心的部分。", "explanation": "此处应该用〈核心〉。“边缘”指靠外侧、非主流的部分，与“最核心”矛盾。"}, {"text": "这座城市的边缘最繁华，是全城的中心。", "explanation": "此处应该用〈中心〉。“边缘”指最外侧的部分，不能指全城的中心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "边缘", "is_correct": true, "explanation": "“边缘”指湖的外侧部分，符合“把船划到湖的……停了下来”的空间语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：船无法划到天空，与“划船”的水上语境矛盾。"}, {"text": "手指", "is_correct": false, "explanation": "语义：湖上不会有手指，手指也不能作为划船的终点。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“划到”要求处所名词作终点，“歌曲”不是处所，搭配不通。"}], "explanations": {"边缘": "“边缘”指湖的外侧部分，符合“把船划到湖的……停了下来”的空间语境。", "天空": "语义：船无法划到天空，与“划船”的水上语境矛盾。", "手指": "语义：湖上不会有手指，手指也不能作为划船的终点。", "歌曲": "搭配：“划到”要求处所名词作终点，“歌曲”不是处所，搭配不通。"}, "sentence_index": 6, "correct_answer": "边缘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把日记藏在抽屉的边缘，谁也找不到。", "explanation": "这里应该用〈深处〉。“边缘”指靠外侧的部分，最容易被看到，藏东西不让人找到要放在“深处”。"}, {"text": "这部电影的边缘是最精彩的结尾。", "explanation": "此处应该用〈结尾〉。“边缘”指最外侧的部分，与“最精彩的结尾”的位置矛盾。"}, {"text": "这座房子的边缘恰好是客厅，四面都是卧室。", "explanation": "此处应该用〈中间〉。“边缘”指最外侧的部分，与“客厅”居中、四面环绕卧室的布局矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "船停在湖的边缘里。", "corrected_sentence": "船停在湖的边缘。", "error_description": "方位词多余：“边缘”本身已表示位置，再接“里”重复且不自然，应说“船停在湖的边缘”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "池子的边缘的结了一层冰。", "corrected_sentence": "池子的边缘结了一层冰。", "error_description": "多余的“的”：“池子的边缘”已是完整的主语，谓语“结了”前不能再加“的”，应说“池子的边缘结了一层冰”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2d5561a-5768-437b-a0a0-ef03d2a3b402') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
