INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13495, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "形容声音很低或没有声音；也形容不惊动别人。", "primary_collocate": null, "pronunciation": "qiǎo rán", "ipa": "tɕʰiɑʊ˨˩ ɻan˧˥", "syllable_count": 2, "sentences": [{"text": "在华北平原一个曾饱受风沙侵袭的边缘村落，一场由村民自发组织的生态复兴运动正悄然重塑着人与土地的关系。", "target_word": "悄然", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "天黑以后，他悄然离开了教室。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天悄然来到了这座小城。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她怕吵醒孩子，悄然关上了门。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不知不觉，天色悄然暗了下来。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议开始前，他悄然坐到了最后一排。", "target_word": "悄然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多变化悄然发生，大家都没有注意。", "target_word": "悄然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮悄然升起，湖面慢慢亮了。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他悄然走到老人身后，放下一束花。", "target_word": "悄然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几年来，这里的生活悄然变好了。", "target_word": "悄然", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "悄然", "label": "基本形式"}, {"form": "悄然无声", "label": "复合"}], "register": "书面", "sense_fingerprint": "无声无息、不惊动人地做某事或发生变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a557264c-4aa5-46b9-b35c-1063d06c8088') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13495, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悄然", "is_correct": true, "explanation": "正确：“悄然”表示无声无息地进行，与“正……重塑着”的进行态相合。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已完成，与“正”和“重塑着”的进行态矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”指过去发生过的事，与句中正在进行的“重塑着”矛盾。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”强调马上发生，与持续进行、慢慢改变的“重塑着”不合。"}], "explanations": {"悄然": "正确：“悄然”表示无声无息地进行，与“正……重塑着”的进行态相合。", "已经": "体貌：“已经”表示动作已完成，与“正”和“重塑着”的进行态矛盾。", "曾经": "体貌：“曾经”指过去发生过的事，与句中正在进行的“重塑着”矛盾。", "立即": "语义：“立即”强调马上发生，与持续进行、慢慢改变的“重塑着”不合。"}, "sentence_index": 0, "correct_answer": "悄然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他悄然地喊了一声，声音大得整条街都听见了。", "explanation": "这里应该用〈大声〉。悄然指声音很低或没有声音，与“声音大得整条街都听见”正相矛盾。"}, {"text": "他们悄然放起了鞭炮，把整条街都吵醒了。", "explanation": "这里应该用〈大张旗鼓〉。悄然指不声不响、不引人注意，与“放鞭炮、吵醒整条街”矛盾；大张旗鼓指声势很大地进行。"}, {"text": "这家店悄然开业，门口却排起了长队，连电视台都来采访。", "explanation": "这里应该用〈大张旗鼓〉。悄然指不声不响、不引人注意，而“排起长队、电视台来采访”说明广受关注，二者矛盾；大张旗鼓指声势很大地进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13495, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悄然", "is_correct": true, "explanation": "正确：“悄然”表示不引人注意地发生，与“大家都没有注意”相合。"}, {"text": "当众", "is_correct": false, "explanation": "语义：“当众”指在众人面前进行，与“大家都没有注意”矛盾。"}, {"text": "公然", "is_correct": false, "explanation": "语义：“公然”指公开地进行、毫不隐瞒，与“大家都没有注意”矛盾。"}, {"text": "明显地", "is_correct": false, "explanation": "搭配：“明显地”说情状显眼，与“大家都没有注意”不能搭配。"}], "explanations": {"悄然": "正确：“悄然”表示不引人注意地发生，与“大家都没有注意”相合。", "当众": "语义：“当众”指在众人面前进行，与“大家都没有注意”矛盾。", "公然": "语义：“公然”指公开地进行、毫不隐瞒，与“大家都没有注意”矛盾。", "明显地": "搭配：“明显地”说情状显眼，与“大家都没有注意”不能搭配。"}, "sentence_index": 6, "correct_answer": "悄然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雷声悄然炸响，震得窗户直颤。", "explanation": "这里应该用〈轰然〉。悄然形容声音很低或没有声音，与“炸响、震得窗户直颤”矛盾；轰然指声音很大地响起。"}, {"text": "这首歌悄然响彻了整个礼堂，让人听得入神。", "explanation": "这里应该删去〈悄然〉。悄然形容声音很低或没有声音，与“响彻整个礼堂”（声音很大地传遍）正相矛盾。"}, {"text": "他拿起话筒，悄然向全场宣布：“我要结婚了！”", "explanation": "这里应该用〈大声〉。悄然指没有声音、不惊动别人，而拿话筒向全场宣布是为了让所有人都听见，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13495, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈悄然的走进厨房，没有出声。", "corrected_sentence": "妈妈悄然地走进厨房，没有出声。", "error_description": "错误在于用了“的”。“悄然”修饰动词作状语，后面应接“地”，应说“悄然地走进厨房”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13495, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里，雨悄然得停了。", "corrected_sentence": "夜里，雨悄然地停了。", "error_description": "“悄然”作状语修饰动词时，后面应接助词“地”，不能用“得”；“得”用于动词或形容词之后作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13498, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13498, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13498, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指大规模种植树木，以增加绿化面积、改善生态环境的行为或过程。", "primary_collocate": null, "pronunciation": "zhí shù zào lín", "ipa": "ʈʂɻ̩³⁵ ʂu⁵¹ tsɑʊ̯⁵¹ lin³⁵", "syllable_count": 4, "sentences": [{"text": "这场以“绿脉计划”为名的植树造林行动，起初只是几位退休教师在村口荒坡上栽下的一百棵杨树苗，如今已演变为涵盖三十多个行政村、年均种植超过五万株本土树种的区域性环境保护实践。", "target_word": "植树造林", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "每年春天，我们学校都组织学生去山上植树造林。", "target_word": "植树造林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府鼓励大家植树造林，保护环境。", "target_word": "植树造林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地方以前是沙漠，植树造林让这里变绿了。", "target_word": "植树造林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植树造林对改善空气很有帮助。", "target_word": "植树造林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植树节那天，很多人参加了植树造林活动。", "target_word": "植树造林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在山上植树造林已经二十年了。", "target_word": "植树造林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植树造林需要很多时间，也需要很多人。", "target_word": "植树造林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了防止沙尘，北方正在大力植树造林。", "target_word": "植树造林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几年植树造林的面积越来越大，空气也变好了。", "target_word": "植树造林", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "植樹造林", "label": "繁体"}], "register": "中性", "sense_fingerprint": "植树造林：大规模种树以增加绿化、改善生态环境的行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a557264c-4aa5-46b9-b35c-1063d06c8088') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "植树造林", "is_correct": true, "explanation": "正确：“植树造林”指大规模栽种树木，与“荒坡上栽下的杨树苗”相合。"}, {"text": "垃圾分类", "is_correct": false, "explanation": "语义：“垃圾分类”与栽种树苗、改善荒坡无关，句子意思不通。"}, {"text": "人工降雨", "is_correct": false, "explanation": "语义：“人工降雨”与村口荒坡上栽树苗的情节不符，句子不通。"}, {"text": "大棚种植", "is_correct": false, "explanation": "搭配：“大棚种植”需要棚架设施，与“荒坡上栽下的杨树苗”不能搭配。"}], "explanations": {"植树造林": "正确：“植树造林”指大规模栽种树木，与“荒坡上栽下的杨树苗”相合。", "垃圾分类": "语义：“垃圾分类”与栽种树苗、改善荒坡无关，句子意思不通。", "人工降雨": "语义：“人工降雨”与村口荒坡上栽树苗的情节不符，句子不通。", "大棚种植": "搭配：“大棚种植”需要棚架设施，与“荒坡上栽下的杨树苗”不能搭配。"}, "sentence_index": 0, "correct_answer": "植树造林"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "城市广场上铺上草皮，进行植树造林。", "explanation": "这里应该用〈绿化〉。植树造林指大规模栽种树木，铺草皮、种花草应说绿化。"}, {"text": "我们在院子里植树造林，只种了一棵。", "explanation": "这里应该用〈种树〉。植树造林指大规模造林，与“只种了一棵”的规模矛盾。"}, {"text": "这种兰花需要细心植树造林，才能开出花来。", "explanation": "这里应该用〈栽培〉。植树造林针对树木，兰花等花卉应说栽培。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "植树造林", "is_correct": true, "explanation": "正确：“植树造林”指在山上大规模种树，与“爷爷在山上……已经二十年了”相合。"}, {"text": "下海经商", "is_correct": false, "explanation": "语义：“下海经商”指放弃原来的工作去做生意，与“在山上……已经二十年”种树的语境不合。"}, {"text": "登月探测", "is_correct": false, "explanation": "语义：“登月探测”指去月球探测，与“在山上”的地点和常识矛盾。"}, {"text": "平面设计", "is_correct": false, "explanation": "搭配：“平面设计”是设计工作，不能与“在山上”这一地点搭配。"}], "explanations": {"植树造林": "正确：“植树造林”指在山上大规模种树，与“爷爷在山上……已经二十年了”相合。", "下海经商": "语义：“下海经商”指放弃原来的工作去做生意，与“在山上……已经二十年”种树的语境不合。", "登月探测": "语义：“登月探测”指去月球探测，与“在山上”的地点和常识矛盾。", "平面设计": "搭配：“平面设计”是设计工作，不能与“在山上”这一地点搭配。"}, "sentence_index": 6, "correct_answer": "植树造林"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这几年我们在阳台上植树造林，种满了各种花。", "explanation": "这里应该用〈栽花〉。植树造林针对树木和大面积造林，阳台上种花应说栽花。"}, {"text": "这几年我们在鱼塘里植树造林，鱼的产量一年比一年高。", "explanation": "这里应该用〈养殖〉。植树造林指种植树木，鱼塘里养鱼应说养殖。"}, {"text": "这几年我们植树造林，路越修越长，交通也越来越方便了。", "explanation": "这里应该用〈修路〉。植树造林针对树木，与“路越修越长”的道路建设不符，应说修路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年春天，我们山上植树造林。", "corrected_sentence": "今年春天，我们在山上植树造林。", "error_description": "错误在于漏了介词“在”。“山上”是地点，作状语修饰动词时前面要加“在”，应写成“在山上植树造林”；漏掉“在”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每年都去山区植树造林着。", "corrected_sentence": "他们每年都去山区植树造林。", "error_description": "“着”表示动作的持续或进行，与“每年都去山区”这种习惯性叙述不搭；应去掉“着”，写成“他们每年都去山区植树造林。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bdc81dc-1c8b-4b92-ac86-62b2984c62a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
