INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13506, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "刚长出来的小树，还很小，需要好好照顾才能长大。", "primary_collocate": null, "pronunciation": "shù miáo", "ipa": "ʂu˥˩ mjɑʊ̯˧˥", "syllable_count": 2, "sentences": [{"text": "老师和同学们在村口栽下了一百棵树苗。", "target_word": "树苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者每个月都去看看树苗长得怎么样。", "target_word": "树苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，我们去山上种树苗。", "target_word": "树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸给院子里的树苗浇水。", "target_word": "树苗", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这棵树苗还很小，需要好好照顾。", "target_word": "树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师买了五十棵树苗，同学们周末去种。", "target_word": "树苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的大风把一棵树苗吹倒了。", "target_word": "树苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树苗长大以后，就会变成一棵大树。", "target_word": "树苗", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天给树苗浇水，树苗慢慢长高了。", "target_word": "树苗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上有很多刚栽好的树苗。", "target_word": "树苗", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一棵树苗", "label": "量词"}, {"form": "杨树苗", "label": "复合"}], "register": "中性", "sense_fingerprint": "树苗:刚长出来、需要照顾的小树", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f659c16-daa9-43a1-9d53-9dc21665adf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "树苗", "is_correct": true, "explanation": "树苗：刚长出的小树，可以“栽下”，也可以用“一百棵”计数。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：叶子用“片”计量，“一百棵树叶”不通，树叶也不能栽。"}, {"text": "树枝", "is_correct": false, "explanation": "搭配：枝条用“根”或“条”计量，不能说“一百棵树枝”。"}, {"text": "树皮", "is_correct": false, "explanation": "语义：树皮是包在树干外的一层，不是能被“栽下”的独立植株，与“栽下”冲突。"}], "explanations": {"树苗": "树苗：刚长出的小树，可以“栽下”，也可以用“一百棵”计数。", "树叶": "搭配：叶子用“片”计量，“一百棵树叶”不通，树叶也不能栽。", "树枝": "搭配：枝条用“根”或“条”计量，不能说“一百棵树枝”。", "树皮": "语义：树皮是包在树干外的一层，不是能被“栽下”的独立植株，与“栽下”冲突。"}, "sentence_index": 0, "correct_answer": "树苗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片林子里的树苗高得遮住了天空。", "explanation": "树苗指刚长出、还很小的树，不能说高得遮住天空；这里应该用〈大树〉。"}, {"text": "村口那棵树苗已经有一百多岁了。", "explanation": "树苗是刚长出的小树，不会有一百多岁；这里应该用〈老树〉。"}, {"text": "这片果园里的树苗结满了果子。", "explanation": "树苗还没有长大，不会结果；这里应该用〈果树〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "树苗", "is_correct": true, "explanation": "树苗：刚长出的小树，可以被大风吹倒，与“一棵”相合。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“树叶”是叶子，不能用“棵”计数整株，也不会被大风吹倒。"}, {"text": "树根", "is_correct": false, "explanation": "语义：树根在地下，风吹不到，不能说被吹倒。"}, {"text": "树梢", "is_correct": false, "explanation": "搭配：“梢”只是树的一部分，不能用“棵”计数整株。"}], "explanations": {"树苗": "树苗：刚长出的小树，可以被大风吹倒，与“一棵”相合。", "树叶": "搭配：“树叶”是叶子，不能用“棵”计数整株，也不会被大风吹倒。", "树根": "语义：树根在地下，风吹不到，不能说被吹倒。", "树梢": "搭配：“梢”只是树的一部分，不能用“棵”计数整株。"}, "sentence_index": 6, "correct_answer": "树苗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片林子里的树苗已经生长了几百年。", "explanation": "树苗是刚长出的小树，说几百年的树龄要用〈树木〉。"}, {"text": "这张木桌是用上好的树苗做的。", "explanation": "树苗还没长成，不能当家具用料；做家具要用〈木材〉。"}, {"text": "这棵树苗的树干粗得要两个人才能抱住。", "explanation": "树苗还很细小，树干粗到要两人合抱，这里应该用〈老树〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张树苗长得很快。", "corrected_sentence": "这棵树苗长得很快。", "error_description": "量词错误：“树苗”的量词应为“棵”，“张”用于平面物体，“这张树苗”是错误的，应说“这棵树苗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山坡上种了很多树苗们。", "corrected_sentence": "山坡上种了很多树苗。", "error_description": "“们”用错：“们”只用于指人的名词，“树苗”不能加“们”，前面已有“很多”也不需要。应说“很多树苗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a9abfbc-7425-4180-9c93-5ab63bd1066a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
