INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13507, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13507, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指中国农村按行政划分的村级单位，通常包含若干自然村，设有村委会等管理机构。", "primary_collocate": null, "pronunciation": "xíng zhèng cūn", "ipa": "ɕiŋ˧˥ ʈʂɤŋ˥˩ tsʰwən˥", "syllable_count": 3, "sentences": [{"text": "这场以“绿脉计划”为名的植树造林行动，起初只是几位退休教师在村口荒坡上栽下的一百棵杨树苗，如今已演变为涵盖三十多个行政村、年均种植超过五万株本土树种的区域性环境保护实践。", "target_word": "行政村", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我们县有两百多个行政村。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行政村有一个小学。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村委会在行政村的中心。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新路连接了三个行政村。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个行政村都有村委会。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这个行政村当了十年村干部。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个行政村里常常有几个自然村。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给每个行政村修了路灯。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的老家是山东的一个行政村。", "target_word": "行政村", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "中国农村按行政划分的村级单位，含若干自然村，设村委会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25e7a64-8d32-41c0-a4a3-43a2e96bdbc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13507, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行政村", "is_correct": true, "explanation": "正确：“行政村”指按行政划分的村级单位，可以用“涵盖三十多个”来计数，与前文的植树范围相符。"}, {"text": "二氧化碳", "is_correct": false, "explanation": "搭配：“二氧化碳”是不可数的物质，不能用“个”计数，不能说“涵盖三十多个二氧化碳”。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“涵盖”指范围或区域，不能与“生日”这类时点搭配。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是植树造林项目所涵盖的范围，句子语义不通。"}], "explanations": {"行政村": "正确：“行政村”指按行政划分的村级单位，可以用“涵盖三十多个”来计数，与前文的植树范围相符。", "二氧化碳": "搭配：“二氧化碳”是不可数的物质，不能用“个”计数，不能说“涵盖三十多个二氧化碳”。", "生日": "搭配：“涵盖”指范围或区域，不能与“生日”这类时点搭配。", "厨房": "语义：厨房不是植树造林项目所涵盖的范围，句子语义不通。"}, "sentence_index": 0, "correct_answer": "行政村"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个行政村设有居委会。", "explanation": "这里应该用〈社区〉。社区是城市里的基层单位，设居委会；行政村是农村单位，设村委会，不设居委会。"}, {"text": "这个行政村管辖着二十多个行政村。", "explanation": "这里应该用〈镇〉。镇管辖若干行政村；行政村是最基层的村级单位，不管辖其他行政村。"}, {"text": "这个行政村是几百年前由人们自然聚居形成的。", "explanation": "这里应该用〈自然村〉。自然村是自然聚居形成的村落；行政村是按行政划分设立的单位，不是自然形成的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13507, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行政村", "is_correct": true, "explanation": "正确：“行政村”是村级单位，与“当了十年村干部”的语境相合。"}, {"text": "学校", "is_correct": false, "explanation": "语义：村干部是村里的职务，不能在学校任职。"}, {"text": "县城", "is_correct": false, "explanation": "语义：“村干部”属于村一级，与“县城”的层级不符。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“在……当村干部”要求地点是村一级单位，“饭店”不能与“村干部”搭配。"}], "explanations": {"行政村": "正确：“行政村”是村级单位，与“当了十年村干部”的语境相合。", "学校": "语义：村干部是村里的职务，不能在学校任职。", "县城": "语义：“村干部”属于村一级，与“县城”的层级不符。", "饭店": "搭配：“在……当村干部”要求地点是村一级单位，“饭店”不能与“村干部”搭配。"}, "sentence_index": 6, "correct_answer": "行政村"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在这个行政村当了十年县长。", "explanation": "这里应该用〈县政府〉。县长在县政府任职，是县级职务；行政村是村一级单位，不设县长。"}, {"text": "这个行政村每年治疗几万名病人。", "explanation": "这里应该用〈医院〉。治疗病人是医院的职能；行政村是政府管理的基层单位，不能用来指治疗病人。"}, {"text": "这个行政村审理了这个案子。", "explanation": "这里应该用〈法院〉。审理案件是法院的职能；行政村不负责审理案件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13507, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们市有三百多座行政村。", "corrected_sentence": "我们市有三百多个行政村。", "error_description": "量词错误：行政村应使用量词“个”，不能用“座”。“座”多用于山、楼、桥等大型固定物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13507, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们这个行政村的小学上学。", "corrected_sentence": "孩子们在这个行政村的小学上学。", "error_description": "漏掉介词“在”：表示地点的状语要用“在”引出，应说“孩子们在这个行政村的小学上学”，不能说“孩子们这个行政村的小学上学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
