INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13509, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "树木的种类。", "primary_collocate": null, "pronunciation": "shù zhǒng", "ipa": "ʂu˥˩ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这场以“绿脉计划”为名的植树造林行动，起初只是几位退休教师在村口荒坡上栽下的一百棵杨树苗，如今已演变为涵盖三十多个行政村、年均种植超过五万株本土树种的区域性环境保护实践。", "target_word": "树种", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "摒弃了过去单一树种大规模种植的教训，团队邀请林业专家指导，构建了包含乔木、灌木、草本植物的多层次植被系统。", "target_word": "树种", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这片山上有二十多个树种。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方和北方的树种不一样。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "松树是很常见的树种。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个树种长得很快，三年就高了。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的树种很多，有松树、柳树和杨树。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们认识了几个新树种。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种树只在南方生长，是少见的树种。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "林业专家说，这里应该选耐旱的树种。", "target_word": "树种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "樹種", "label": "繁体"}], "register": "中性", "sense_fingerprint": "树木的种类，如松树、杨树", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25e7a64-8d32-41c0-a4a3-43a2e96bdbc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13509, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "树种", "is_correct": true, "explanation": "正确：“本土树种”指本地的树木种类，与前面的“种植”“株”搭配。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“种植”和“株”的对象是植物，人口不能被种植，也不能按“株”计数。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言不是植物，不能说“年均种植超过五万株方言”。"}, {"text": "货币", "is_correct": false, "explanation": "搭配：“株”是植物的量词，“货币”不能用“株”计量，也不能说种植货币。"}], "explanations": {"树种": "正确：“本土树种”指本地的树木种类，与前面的“种植”“株”搭配。", "人口": "语义：“种植”和“株”的对象是植物，人口不能被种植，也不能按“株”计数。", "方言": "语义：方言不是植物，不能说“年均种植超过五万株方言”。", "货币": "搭配：“株”是植物的量词，“货币”不能用“株”计量，也不能说种植货币。"}, "sentence_index": 0, "correct_answer": "树种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老虎是一种濒危树种。", "explanation": "这里应该用〈物种〉。树种指树木的种类，只用于树；老虎是动物，要用“物种”。"}, {"text": "这个西瓜是新树种。", "explanation": "这里应该用〈品种〉。树种只指树木的种类，西瓜是草本植物，要用“品种”。"}, {"text": "小麦是我们村最重要的树种。", "explanation": "这里应该用〈作物〉。树种只指树木，小麦是粮食作物，要用“作物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13509, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "树种", "is_correct": true, "explanation": "正确：“很多树种”说公园里树的种类，与“有松树、柳树和杨树”相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：句中列出的是树的名称，游客不是树，“游客有松树、柳树”不成立。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：“有松树、柳树和杨树”说的是树，垃圾桶不能是这些树。"}, {"text": "长椅", "is_correct": false, "explanation": "搭配：“有”后接树名时，主语应是植物或地点，“长椅有松树、柳树”不搭配。"}], "explanations": {"树种": "正确：“很多树种”说公园里树的种类，与“有松树、柳树和杨树”相符。", "游客": "语义：句中列出的是树的名称，游客不是树，“游客有松树、柳树”不成立。", "垃圾桶": "语义：“有松树、柳树和杨树”说的是树，垃圾桶不能是这些树。", "长椅": "搭配：“有”后接树名时，主语应是植物或地点，“长椅有松树、柳树”不搭配。"}, "sentence_index": 6, "correct_answer": "树种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河里有很多树种。", "explanation": "这里应该用〈鱼类〉。树种只指树木的种类，河里的生物应说“鱼类”。"}, {"text": "我们家每天吃很多树种。", "explanation": "这里应该用〈蔬菜〉。树种是树木的种类，不能当食物吃，日常食物要用“蔬菜”。"}, {"text": "这头猪是农场里最好的树种。", "explanation": "这里应该用〈品种〉。树种只指树木的种类，家畜的种类要说“品种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13509, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个林场一共有十几只树种。", "corrected_sentence": "这个林场一共有十几个树种。", "error_description": "错误形式：“十几只树种”；正确形式：“十几个树种”。“只”用于动物，“树种”是树木的种类，量词应用“个”或“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13509, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片荒坡上应该种耐旱地树种。", "corrected_sentence": "这片荒坡上应该种耐旱的树种。", "error_description": "错误形式：“耐旱地树种”；正确形式：“耐旱的树种”。修饰名词要用“的”，“地”用于修饰动词，不能修饰名词“树种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13510, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "全国性", "is_correct": true, "explanation": "正确：“全国性”与“区域性”相对，前者指涉及全国，后者指只属于某地区。"}, {"text": "难度", "is_correct": false, "explanation": "无关：“难度”指事情的困难程度，与“区域性”没有反义关系。"}, {"text": "速度", "is_correct": false, "explanation": "无关：“速度”指快慢，不是“区域性”的对立面。"}, {"text": "亮度", "is_correct": false, "explanation": "无关：“亮度”指光的强弱，与“区域性”没有反义关系。"}], "correct_answer": "全国性", "explanations": {"全国性": "正确：“全国性”与“区域性”相对，前者指涉及全国，后者指只属于某地区。", "难度": "无关：“难度”指事情的困难程度，与“区域性”没有反义关系。", "速度": "无关：“速度”指快慢，不是“区域性”的对立面。", "亮度": "无关：“亮度”指光的强弱，与“区域性”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13510, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "全国性", "is_correct": true, "explanation": "正确：“全国性”与“区域性”相对，前者指涉及全国，后者指只属于某地区。"}, {"text": "深度", "is_correct": false, "explanation": "无关：“深度”指深浅的程度，与“区域性”没有反义关系。"}, {"text": "热度", "is_correct": false, "explanation": "无关：“热度”指热烈的程度或受关注的程度，与“区域性”没有反义关系。"}, {"text": "温度", "is_correct": false, "explanation": "无关：“温度”指冷热的程度，与“区域性”没有反义关系。"}], "correct_answer": "全国性", "explanations": {"全国性": "正确：“全国性”与“区域性”相对，前者指涉及全国，后者指只属于某地区。", "深度": "无关：“深度”指深浅的程度，与“区域性”没有反义关系。", "热度": "无关：“热度”指热烈的程度或受关注的程度，与“区域性”没有反义关系。", "温度": "无关：“温度”指冷热的程度，与“区域性”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13510, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指某个地区特有的性质或范围，不涉及其他区域。", "primary_collocate": null, "pronunciation": "qū yù xìng", "ipa": "tɕʰy˥ y˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这场以“绿脉计划”为名的植树造林行动，起初只是几位退休教师在村口荒坡上栽下的一百棵杨树苗，如今已演变为涵盖三十多个行政村、年均种植超过五万株本土树种的区域性环境保护实践。", "target_word": "区域性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这是一个区域性的问题。", "target_word": "区域性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次干旱具有明显的区域性。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政策只有区域性影响，没有扩大到其他省份。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种建筑风格的区域性很强，只在南方出现。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种疾病有区域性，主要出现在南方。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，这次污染的区域性很强。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先开区域性会议，再开全国会议。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛只是区域性的，影响不大。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "区域性的经济计划要考虑当地情况。", "target_word": "区域性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "區域性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "某地区特有的性质或范围，与全国性相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25e7a64-8d32-41c0-a4a3-43a2e96bdbc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13510, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区域性", "is_correct": true, "explanation": "正确：“区域性环境保护实践”指范围限于某地区的环保工作，与“涵盖三十多个行政村”相符。"}, {"text": "全国性", "is_correct": false, "explanation": "语义：句中说项目只涵盖三十多个行政村，“全国性”范围过大，与句意矛盾。"}, {"text": "世界性", "is_correct": false, "explanation": "语义：“世界性”指范围遍及全世界，与“三十多个行政村”的规模不符。"}, {"text": "国际性", "is_correct": false, "explanation": "搭配：“国际性”多修饰跨国的合作、组织或会议，不用来修饰只涵盖村子的实践。"}], "explanations": {"区域性": "正确：“区域性环境保护实践”指范围限于某地区的环保工作，与“涵盖三十多个行政村”相符。", "全国性": "语义：句中说项目只涵盖三十多个行政村，“全国性”范围过大，与句意矛盾。", "世界性": "语义：“世界性”指范围遍及全世界，与“三十多个行政村”的规模不符。", "国际性": "搭配：“国际性”多修饰跨国的合作、组织或会议，不用来修饰只涵盖村子的实践。"}, "sentence_index": 0, "correct_answer": "区域性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个道理很有区域性，人人都明白。", "explanation": "这里应该用〈普遍性〉。区域性指某地特有，不指适用于各处；说道理人人都懂，要用“普遍性”。"}, {"text": "这部小说的情节很有区域性，前后衔接很紧。", "explanation": "这里应该用〈连续性〉。区域性指事物只属于某地，不指前后相连；说情节前后衔接紧要用“连续性”。"}, {"text": "这种药的区域性很大，只能治轻症。", "explanation": "这里应该用〈局限性〉。区域性指事物只属于某地，不指药效的局限程度，要说“局限性很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区域性", "is_correct": true, "explanation": "正确：“污染的区域性很强”说污染只限于某些地方，符合句意。"}, {"text": "观赏性", "is_correct": false, "explanation": "语义：污染不供人观赏，“观赏性”只用于花木、景观等事物。"}, {"text": "趣味性", "is_correct": false, "explanation": "语义：“趣味性”指引人感兴趣的性质，不能用来形容污染。"}, {"text": "艺术性", "is_correct": false, "explanation": "搭配：“艺术性”多修饰作品或表演，不用来修饰污染。"}], "explanations": {"区域性": "正确：“污染的区域性很强”说污染只限于某些地方，符合句意。", "观赏性": "语义：污染不供人观赏，“观赏性”只用于花木、景观等事物。", "趣味性": "语义：“趣味性”指引人感兴趣的性质，不能用来形容污染。", "艺术性": "搭配：“艺术性”多修饰作品或表演，不用来修饰污染。"}, "sentence_index": 6, "correct_answer": "区域性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这款玩具的区域性很高，家长可以放心买。", "explanation": "这里应该用〈安全性〉。区域性指地方特点，不指玩具的安全程度，要说“安全性很高”。"}, {"text": "这套系统的区域性很强，可以随时调整。", "explanation": "这里应该用〈灵活性〉。区域性指地方特点，不指系统能否灵活调整，要说“灵活性很强”。"}, {"text": "这座桥的区域性很好，车辆都能安全通过。", "explanation": "这里应该用〈稳定性〉。区域性不指结构的牢固程度，要说“稳定性很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项政策有很强地区域性。", "corrected_sentence": "这项政策有很强的区域性。", "error_description": "错误形式：“很强地区域性”；正确形式：“很强的区域性”。“区域性”是名词，前面的修饰语要用“的”，不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要分析这个问题的很区域性特点。", "corrected_sentence": "我们要分析这个问题的区域性特点。", "error_description": "多余成分：“区域性”是名词，前面不能加程度副词“很”修饰。应说“这个问题的区域性特点”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13511, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻力", "is_correct": true, "explanation": "“阻力”指阻碍事物前进的力量，与推动前进的驱动力意思相反。"}, {"text": "能源", "is_correct": false, "explanation": "“能源”指能量的来源，与驱动力不构成反义关系。"}, {"text": "乐趣", "is_correct": false, "explanation": "“乐趣”指快乐的情趣，与驱动力没有相对的关系。"}, {"text": "标准", "is_correct": false, "explanation": "“标准”指衡量事物的准则，与驱动力不构成反义。"}], "correct_answer": "阻力", "explanations": {"阻力": "“阻力”指阻碍事物前进的力量，与推动前进的驱动力意思相反。", "能源": "“能源”指能量的来源，与驱动力不构成反义关系。", "乐趣": "“乐趣”指快乐的情趣，与驱动力没有相对的关系。", "标准": "“标准”指衡量事物的准则，与驱动力不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13511, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻力", "is_correct": true, "explanation": "“阻力”指阻碍事物前进的力量，与推动前进的驱动力意思相反。"}, {"text": "海拔", "is_correct": false, "explanation": "“海拔”指地面高出海平面的高度，与驱动力没有相对的关系。"}, {"text": "色彩", "is_correct": false, "explanation": "“色彩”指颜色的表现，与驱动力不构成反义关系。"}, {"text": "体积", "is_correct": false, "explanation": "“体积”指物体所占空间的大小，与驱动力不构成反义。"}], "correct_answer": "阻力", "explanations": {"阻力": "“阻力”指阻碍事物前进的力量，与推动前进的驱动力意思相反。", "海拔": "“海拔”指地面高出海平面的高度，与驱动力没有相对的关系。", "色彩": "“色彩”指颜色的表现，与驱动力不构成反义关系。", "体积": "“体积”指物体所占空间的大小，与驱动力不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13511, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "驱动力指推动事物前进或发展的内在力量或动力。", "primary_collocate": null, "pronunciation": "qū dòng lì", "ipa": "tɕʰy˥ tʊŋ˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "驱动力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "好奇心是学习最大的驱动力。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展的驱动力来自创新。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人是这座城市发展的驱动力。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兴趣成了他坚持下去的驱动力。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要新的驱动力来推动增长。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场需求是企业生产的主要驱动力。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术进步为社会提供了强大的驱动力。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把梦想当作前进的驱动力。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项改革缺少持续的驱动力。", "target_word": "驱动力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "驅動力", "label": "繁体"}], "register": "书面", "sense_fingerprint": "推动事物发展的内在动力，如创新、需求、梦想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25e7a64-8d32-41c0-a4a3-43a2e96bdbc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13511, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "驱动力", "is_correct": true, "explanation": "“驱动力”指推动事物前进的内在力量，与“核心”及“源于……自觉”的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，与推动前进的力量无关，句子读不通。"}, {"text": "地基", "is_correct": false, "explanation": "搭配：“核心地基”与“源于一种生态自觉”不搭配，地基是承托建筑的底部，不是推动发展的力量。"}, {"text": "标点", "is_correct": false, "explanation": "语义：“标点”是书面符号，不能作为推动事物发展的力量。"}], "explanations": {"驱动力": "“驱动力”指推动事物前进的内在力量，与“核心”及“源于……自觉”的语境相符。", "颜色": "语义：“颜色”指色彩，与推动前进的力量无关，句子读不通。", "地基": "搭配：“核心地基”与“源于一种生态自觉”不搭配，地基是承托建筑的底部，不是推动发展的力量。", "标点": "语义：“标点”是书面符号，不能作为推动事物发展的力量。"}, "sentence_index": 0, "correct_answer": "驱动力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的驱动力很重，连书包都背不动。", "explanation": "这里应该用〈力气〉。驱动力指推动前进的力量，不指人的体力；背东西要靠力气。"}, {"text": "改革遇到了很大的驱动力，进展十分缓慢。", "explanation": "这里应该用〈阻力〉。驱动力指推动前进的力量，不能表示阻碍改革的力量；遇到阻碍要用阻力。"}, {"text": "他的驱动力很大，隔壁都听见了。", "explanation": "这里应该用〈声音〉。驱动力指推动前进的力量，不能用来形容声音的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "驱动力", "is_correct": true, "explanation": "“驱动力”指推动企业生产的主要力量，与“市场需求是……主要……”相符。"}, {"text": "税收", "is_correct": false, "explanation": "语义：“税收”指国家征收的税款，不能作为推动生产的力量。"}, {"text": "语法", "is_correct": false, "explanation": "语义：“语法”指语言的组合规则，与企业生产的推动力无关。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“主要天气”与“企业生产”不搭配，天气不能作为生产的推动力。"}], "explanations": {"驱动力": "“驱动力”指推动企业生产的主要力量，与“市场需求是……主要……”相符。", "税收": "语义：“税收”指国家征收的税款，不能作为推动生产的力量。", "语法": "语义：“语法”指语言的组合规则，与企业生产的推动力无关。", "天气": "搭配：“主要天气”与“企业生产”不搭配，天气不能作为生产的推动力。"}, "sentence_index": 6, "correct_answer": "驱动力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯的驱动力很高，照亮了整个房间。", "explanation": "这里应该用〈亮度〉。驱动力指推动前进的力量，不指灯光的明亮程度。"}, {"text": "这场地震的驱动力把房屋全部毁掉了。", "explanation": "这里应该用〈破坏力〉。驱动力指推动前进的力量，不指造成毁坏的力。"}, {"text": "他用驱动力把蚊子赶走。", "explanation": "这里应该用〈驱赶〉。驱动力是抽象的推动力，不能当作把蚊子赶走的动作；赶走蚊子要用驱赶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种精神是我前进的一条驱动力。", "corrected_sentence": "这种精神是我前进的一股驱动力。", "error_description": "量词错误：“条”用于细长之物，不能修饰抽象的驱动力，应说“一股”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次改革有一根很强的驱动力。", "corrected_sentence": "这次改革有一股很强的驱动力。", "error_description": "「驱动力」前应用量词「股」，「根」用于细长之物，不能修饰抽象的力量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
