INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13512, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由上级发出的必须执行的命令或指示", "primary_collocate": null, "pronunciation": "zhǐ lìng", "ipa": "ʈʂɨ˨˩˦ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "指令", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "上级下达的指令往往附有明确的执行期限，下级不能拖延。", "target_word": "指令", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "队长下达指令，大家马上出发。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们必须服从上级的指令。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理接到指令后，立刻通知了所有人。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们按指令把货物搬到了仓库。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有听清楚指令，所以做错了。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条指令要求大家明天早上八点到。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军人的天职就是执行指令。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板的指令很清楚，不能迟到。", "target_word": "指令", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条指令", "label": "量词"}, {"form": "一道指令", "label": "量词"}, {"form": "指令集", "label": "复合"}], "register": "中性", "sense_fingerprint": "指令：上级发出、下属必须执行的命令或指示", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31956932-1185-4de5-add8-d2c55acac8f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13512, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指令", "is_correct": true, "explanation": "正确：指令指上级发出、必须执行的命令，与句中的“上级”相合。"}, {"text": "林地", "is_correct": false, "explanation": "语义：林地是一片土地，不能由上级发出，句子说不通。"}, {"text": "湖泊", "is_correct": false, "explanation": "搭配：湖泊是水域，不能作为“来自上级”的内容，与“上级”不搭。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光是自然现象，不是上级发出的东西，“并非来自上级阳光”说不通。"}], "explanations": {"指令": "正确：指令指上级发出、必须执行的命令，与句中的“上级”相合。", "林地": "语义：林地是一片土地，不能由上级发出，句子说不通。", "湖泊": "搭配：湖泊是水域，不能作为“来自上级”的内容，与“上级”不搭。", "阳光": "语义：阳光是自然现象，不是上级发出的东西，“并非来自上级阳光”说不通。"}, "sentence_index": 0, "correct_answer": "指令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们收到了一只指令，要求明天早上八点到。", "explanation": "这里应该用〈条〉或〈道〉。〈只〉用于动物和成对的物品，指令是一条条的命令，不能用〈只〉来计量。"}, {"text": "我向经理提了一个指令，希望公司改进工作流程。", "explanation": "这里应该用〈建议〉。指令由上级发出、必须执行，下级不能向上级提指令；提出改进意见要用〈建议〉。"}, {"text": "妈妈给我发来一条指令，祝我生日快乐。", "explanation": "这里应该用〈祝福〉。指令是必须执行的命令，不能用来表达祝愿；“祝我生日快乐”应该用〈祝福〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指令", "is_correct": true, "explanation": "正确：指令是需要听清楚的命令，与“听清楚”相合。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是用眼睛看的，不能被“听清楚”。"}, {"text": "泥土", "is_correct": false, "explanation": "搭配：“听清楚”一般搭配话语和命令，不说“听清楚泥土”。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是穿戴用品，不能作为被听的对象，与“做错了”也没有关系。"}], "explanations": {"指令": "正确：指令是需要听清楚的命令，与“听清楚”相合。", "天空": "语义：天空是用眼睛看的，不能被“听清楚”。", "泥土": "搭配：“听清楚”一般搭配话语和命令，不说“听清楚泥土”。", "手套": "语义：手套是穿戴用品，不能作为被听的对象，与“做错了”也没有关系。"}, "sentence_index": 6, "correct_answer": "指令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板给我们发了一支指令，要求明天到。", "explanation": "这里应该用〈条〉或〈道〉。〈支〉用于笔、棍等细长的物体，指令不能用〈支〉来计量。"}, {"text": "朋友给我发来一个指令，希望我参加晚会。", "explanation": "这里应该用〈邀请〉。指令必须执行，邀请则可以接受或拒绝；“希望我参加”应该用〈邀请〉，不能用〈指令〉。"}, {"text": "我有一个指令，希望明年能去北京旅行。", "explanation": "这里应该用〈愿望〉。指令是必须执行的命令，不能用来表达个人的希望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天收到了三本指令。", "corrected_sentence": "他今天收到了三条指令。", "error_description": "量词错误：“指令”应用“条”计量。“本”用于书籍，把它用在指令上是错误的，应改为“三条指令”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们接到了一只指令，要求明天八点到。", "corrected_sentence": "我们接到了一道指令，要求明天八点到。", "error_description": "量词错误：“指令”应用“道”或“条”计量。“只”用于动物等，不能用来计量指令，应改为“一道指令”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dd348c1-5d6e-4d64-bb68-21279fe59201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
