INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13513, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指自己有所认识而主动去做，或自己有所觉悟。", "primary_collocate": null, "pronunciation": "zì jué", "ipa": "tsz̩˥˩ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "自觉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "环保需要每个人的自觉。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要增强环保自觉。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遵守规则靠的是自觉，不是检查。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有很强的文化自觉。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会进步需要公民的自觉。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾分类要靠大家的自觉。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种自觉来自长期的教育。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望学生有学习的自觉。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们缺少节约的自觉。", "target_word": "自觉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自覺", "label": "繁体"}, {"form": "自觉性", "label": "复合"}, {"form": "自觉自愿", "label": "复合"}], "register": "书面", "sense_fingerprint": "自己对责任或价值的认识与觉悟，如环保自觉、文化自觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25e7a64-8d32-41c0-a4a3-43a2e96bdbc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13513, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自觉", "is_correct": true, "explanation": "“自觉”指自己有所认识而主动去做，与“觉醒”“意识到”的语境相符。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：“颜料”是绘画用的着色材料，与生态方面的主动认识无关，句子读不通。"}, {"text": "地毯", "is_correct": false, "explanation": "搭配：“生态地毯”不搭配，地毯是铺在地面的织物，不能指认识与觉悟。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，与生态方面的觉悟无关，句子读不通。"}], "explanations": {"自觉": "“自觉”指自己有所认识而主动去做，与“觉醒”“意识到”的语境相符。", "颜料": "语义：“颜料”是绘画用的着色材料，与生态方面的主动认识无关，句子读不通。", "地毯": "搭配：“生态地毯”不搭配，地毯是铺在地面的织物，不能指认识与觉悟。", "体重": "语义：“体重”指身体的重量，与生态方面的觉悟无关，句子读不通。"}, "sentence_index": 0, "correct_answer": "自觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的自觉很高，能摸到天花板。", "explanation": "这里应该用〈个子〉。自觉指觉悟，不指身高。"}, {"text": "他有很大的自觉，能搬动重物。", "explanation": "这里应该用〈力气〉。自觉指主动去做的认识，不指身体的力量。"}, {"text": "他的自觉很大，像小鹿一样。", "explanation": "这里应该用〈眼睛〉。自觉指觉悟，不指身体器官，不能用来形容眼睛的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
